import smbus2
import time
import logging
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

ADS1015_DEFAULT_ADDRESS = 0x48
ADS1015_IC = 0x00
ADS1115_IC = 0x01

REG_POINTER_CONVERT = 0x00
REG_POINTER_CONFIG = 0x01
REG_POINTER_LOW_THRESHOLD = 0x02
REG_POINTER_HIGH_THRESHOLD = 0x03

CONFIG_OS_SINGLE = 0x8000
CONFIG_OS_CONTINUOUS = 0x0000
CONFIG_MUX_SINGLE_ENDED = 0x4000
CONFIG_MUX_DIFFERENTIAL = 0x0000
CONFIG_PGA_6_144V = 0x0000
CONFIG_PGA_4_096V = 0x0200
CONFIG_PGA_2_048V = 0x0400
CONFIG_PGA_1_024V = 0x0600
CONFIG_PGA_0_512V = 0x0800
CONFIG_PGA_0_256V = 0x0A00
CONFIG_MODE_CONTINUOUS = 0x0000
CONFIG_MODE_SINGLE = 0x0100
CONFIG_DR_128_SPS = 0x0000
CONFIG_DR_250_SPS = 0x0020
CONFIG_DR_490_SPS = 0x0040
CONFIG_DR_920_SPS = 0x0060
CONFIG_DR_1600_SPS = 0x0080
CONFIG_DR_2400_SPS = 0x00A0
CONFIG_DR_3300_SPS = 0x00C0
CONFIG_DR_4900_SPS = 0x00E0
CONFIG_CMODE_TRADITIONAL = 0x0000
CONFIG_CMODE_WINDOW = 0x0010
CONFIG_CPOL_ACTIVE_LOW = 0x0000
CONFIG_CPOL_ACTIVE_HIGH = 0x0008
CONFIG_CLAT_NON_LATCHING = 0x0000
CONFIG_CLAT_LATCHING = 0x0004
CONFIG_CQUE_1_CONV = 0x0000
CONFIG_CQUE_2_CONV = 0x0001
CONFIG_CQUE_4_CONV = 0x0002
CONFIG_CQUE_NONE = 0x0003


class ADS1x15:
    def __init__(self, address=ADS1015_DEFAULT_ADDRESS, ic_type=ADS1015_IC, busnum=1, debug=False):
        self.address = address
        self.ic_type = ic_type
        self.debug = debug
        self.bus = None
        self._closed = False
        try:
            self.bus = smbus2.SMBus(busnum)
        except Exception as e:
            logging.error(f"Failed to initialize I2C bus {busnum}: {e}")
            raise
        self._validate_device()

    def _validate_device(self):
        try:
            self.bus.read_byte(self.address)
        except Exception as e:
            logging.error(f"No ADS1x15 found at address 0x{self.address:02X}: {e}")
            self.close()
            raise

    def _write_register(self, reg, value):
        try:
            self.bus.write_byte_data(self.address, reg, value)
        except Exception as e:
            logging.error(f"I2C write error to register 0x{reg:02X}: {e}")
            raise

    def _read_register(self, reg):
        try:
            return self.bus.read_byte_data(self.address, reg)
        except Exception as e:
            logging.error(f"I2C read error from register 0x{reg:02X}: {e}")
            raise

    def _read_block(self, reg, length):
        try:
            return self.bus.read_i2c_block_data(self.address, reg, length)
        except Exception as e:
            logging.error(f"I2C block read error from register 0x{reg:02X}: {e}")
            raise

    def _build_config(self, mux, pga, sps, mode, active_low, traditional_mode, latching, num_readings):
        config = 0x0000
        config |= CONFIG_OS_SINGLE if mode == 'single' else CONFIG_OS_CONTINUOUS
        config |= CONFIG_MUX_SINGLE_ENDED if mux == 'single_ended' else CONFIG_MUX_DIFFERENTIAL
        if pga == '6_144V':
            config |= CONFIG_PGA_6_144V
        elif pga == '4_096V':
            config |= CONFIG_PGA_4_096V
        elif pga == '2_048V':
            config |= CONFIG_PGA_2_048V
        elif pga == '1_024V':
            config |= CONFIG_PGA_1_024V
        elif pga == '0_512V':
            config |= CONFIG_PGA_0_512V
        elif pga == '0_256V':
            config |= CONFIG_PGA_0_256V
        config |= CONFIG_MODE_CONTINUOUS if mode == 'continuous' else CONFIG_MODE_SINGLE
        if sps == 128:
            config |= CONFIG_DR_128_SPS
        elif sps == 250:
            config |= CONFIG_DR_250_SPS
        elif sps == 490:
            config |= CONFIG_DR_490_SPS
        elif sps == 920:
            config |= CONFIG_DR_920_SPS
        elif sps == 1600:
            config |= CONFIG_DR_1600_SPS
        elif sps == 2400:
            config |= CONFIG_DR_2400_SPS
        elif sps == 3300:
            config |= CONFIG_DR_3300_SPS
        elif sps == 4900:
            config |= CONFIG_DR_4900_SPS
        if traditional_mode:
            config |= CONFIG_CMODE_TRADITIONAL
        if not active_low:
            config |= CONFIG_CPOL_ACTIVE_HIGH
        if latching:
            config |= CONFIG_CLAT_LATCHING
        if num_readings == 1:
            config |= CONFIG_CQUE_1_CONV
        elif num_readings == 2:
            config |= CONFIG_CQUE_2_CONV
        elif num_readings == 4:
            config |= CONFIG_CQUE_4_CONV
        return config

    def read_adc_single_ended(self, channel=0, pga='6_144V', sps=250):
        if channel < 0 or channel > 3:
            raise ValueError("Channel must be between 0 and 3")
        mux = 'single_ended'
        config = self._build_config(mux, pga, sps, 'single', True, True, False, 1)
        config |= (channel << 12)
        self._write_register(REG_POINTER_CONFIG, config)
        time.sleep(0.01)
        data = self._read_block(REG_POINTER_CONVERT, 2)
        raw = (data[0] << 8) | data[1]
        if raw > 0x7FF:
            raw -= 0x1000
        return raw

    def start_continuous_conversion(self, channel=0, pga='6_144V', sps=250):
        if channel < 0 or channel > 3:
            raise ValueError("Channel must be between 0 and 3")
        mux = 'single_ended'
        config = self._build_config(mux, pga, sps, 'continuous', True, True, False, 1)
        config |= (channel << 12)
        self._write_register(REG_POINTER_CONFIG, config)

    def get_last_conversion_results(self):
        data = self._read_block(REG_POINTER_CONVERT, 2)
        raw = (data[0] << 8) | data[1]
        if self.ic_type == ADS1015_IC and raw > 0x7FF:
            raw -= 0x1000
        return raw

    def start_single_ended_comparator(self, channel=0, threshold_high=2047, threshold_low=0, pga='6_144V', sps=250, active_low=True, traditional_mode=True, latching=False, num_readings=1):
        if channel < 0 or channel > 3:
            raise ValueError("Channel must be between 0 and 3")
        mux = 'single_ended'
        config = self._build_config(mux, pga, sps, 'single', active_low, traditional_mode, latching, num_readings)
        config |= (channel << 12)
        config |= (threshold_high << 16)
        config |= (threshold_low << 17)
        self._write_register(REG_POINTER_CONFIG, config)

    def close(self):
        if not self._closed and self.bus is not None:
            try:
                self.bus.close()
            except Exception as e:
                logging.error(f"Error closing I2C bus: {e}")
            finally:
                self._closed = True

    def __del__(self):
        self.close()


def signal_handler(sig, frame):
    logging.info("Interrupt received, exiting...")
    sys.exit(0)


if __name__ == '__main__':
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        adc = ADS1x15(address=ADS1015_DEFAULT_ADDRESS, ic_type=ADS1015_IC, busnum=1, debug=True)
        logging.info("Reading single-ended channel 0...")
        val = adc.read_adc_single_ended(channel=0, pga='6_144V', sps=250)
        logging.info(f"Single-ended channel 0: {val}")
        adc.start_continuous_conversion(channel=0, pga='6_144V', sps=250)
        time.sleep(0.1)
        logging.info(f"Last conversion: {adc.get_last_conversion_results()}")
        adc.start_single_ended_comparator(channel=0, threshold_high=2047, threshold_low=0, pga='6_144V', sps=250, active_low=True, traditional_mode=True, latching=False, num_readings=1)
    except Exception as e:
        logging.error(f"Fatal error: {e}")
    finally:
        if 'adc' in locals():
            adc.close()

