import spidev
import time
import datetime
import csv
import logging
import signal
import sys
import statistics

# Configuration
SPI_BUS = 0
SPI_DEVICE = 0
SPI_MAX_SPEED_HZ = 1000000
DHT_PIN = 4
TEMPERATURE_MIN = -20.0
TEMPERATURE_MAX = 50.0
HUMIDITY_MIN = 0.0
HUMIDITY_MAX = 100.0
WINDOW_SIZE = 5
CALIBRATION_TIME = 60
DATA_LOG_FILE = "gas_data.csv"
ERROR_LOG_FILE = "error.log"

# Logging setup
logging.basicConfig(
    filename=ERROR_LOG_FILE,
    level=logging.ERROR,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

# Global state
spi = None
running = True
temperature_readings = []
humidity_readings = []
last_temperature = None
last_humidity = None
last_temperature_time = None
last_humidity_time = None


def signal_handler(signum, frame):
    global running
    running = False


def init_spi():
    global spi
    try:
        spi = spidev.SpiDev()
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_MAX_SPEED_HZ
        spi.mode = 0
        return True
    except Exception as e:
        logging.error(f"SPI initialization failed: {e}")
        return False


def read_mcp3008(channel):
    if not 0 <= channel <= 7:
        raise ValueError("Channel must be between 0 and 7")
    if spi is None:
        raise RuntimeError("SPI not initialized")
    try:
        adc = spi.xfer2([1, (8 + channel) << 4, 0])
        return ((adc[1] & 3) << 8) + adc[2]
    except Exception as e:
        logging.error(f"Error reading MCP3008 channel {channel}: {e}")
        return None


def read_dht22():
    import RPi.GPIO as GPIO
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(DHT_PIN, GPIO.IN)
    try:
        time.sleep(0.5)
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(DHT_PIN, GPIO.IN)
        for _ in range(100):
            if GPIO.input(DHT_PIN):
                time.sleep(0.05)
        if GPIO.input(DHT_PIN):
            return None, None
        data = []
        for _ in range(40):
            for _ in range(100):
                if GPIO.input(DHT_PIN):
                    start = time.time()
                    for _ in range(100):
                        if GPIO.input(DHT_PIN):
                            end = time.time()
                            break
                    duration = end - start
                    data.append(duration)
                    break
            if duration < 0.0001:
                break
            time.sleep(0.00004)
        if len(data) < 40:
            return None, None
        humidity = sum(data) / len(data)
        humidity = 100 - (humidity * 100)
        for _ in range(100):
            if GPIO.input(DHT_PIN):
                start = time.time()
                for _ in range(100):
                    if GPIO.input(DHT_PIN):
                        end = time.time()
                        break
                duration = end - start
                break
        temperature = sum([duration - 0.0002 * i for i in range(1, 26)]) / 25
        temperature = temperature * 200 - 80
        return temperature, humidity
    except Exception as e:
        logging.error(f"Error reading DHT22: {e}")
        return None, None
    finally:
        GPIO.cleanup()


def validate_temperature(temperature):
    if last_temperature_time is None or (time.time() - last_temperature_time) > 60:
        last_temperature = temperature
        last_temperature_time = time.time()
        return True
    if last_temperature is None:
        return False
    if temperature is None:
        return False
    if not (TEMPERATURE_MIN <= temperature <= TEMPERATURE_MAX):
        logging.error(f"Invalid temperature: {temperature}")
        return False
    if last_temperature is not None and abs(temperature - last_temperature) > 20:
        logging.error(f"Temperature change too large: {temperature} (last: {last_temperature})")
        return False
    return True


def validate_humidity(humidity):
    if last_humidity_time is None or (time.time() - last_humidity_time) > 60:
        last_humidity = humidity
        last_humidity_time = time.time()
        return True
    if last_humidity is None:
        return False
    if humidity is None:
        return False
    if not (HUMIDITY_MIN <= humidity <= HUMIDITY_MAX):
        logging.error(f"Invalid humidity: {humidity}")
        return False
    if last_humidity is not None and abs(humidity - last_humidity) > 20:
        logging.error(f"Humidity change too large: {humidity} (last: {last_humidity})")
        return False
    return True


def moving_average(data, window_size):
    if len(data) < window_size:
        return None
    return statistics.mean(data[-window_size:])


def log_data(temperature, humidity, gas_concentration_channel0, gas_concentration_channel1):
    try:
        with open(DATA_LOG_FILE, "a", newline="") as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow([datetime.datetime.now().isoformat(), temperature, humidity, gas_concentration_channel0, gas_concentration_channel1])
    except Exception as e:
        logging.error(f"Error writing to CSV file: {e}")


def cleanup():
    global spi
    if spi is not None:
        try:
            spi.close()
        except Exception:
            pass
        spi = None


def main():
    global running, temperature_readings, humidity_readings
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    if not init_spi():
        print("Failed to initialize SPI. Check error.log for details.")
        sys.exit(1)
    time.sleep(CALIBRATION_TIME)
    while running:
        try:
            temperature, humidity = read_dht22()
            if temperature is not None and humidity is not None:
                if validate_temperature(temperature):
                    temperature_readings.append(temperature)
                    last_temperature = temperature
                if validate_humidity(humidity):
                    humidity_readings.append(humidity)
                    last_humidity = humidity
                gas_concentration_channel0 = read_mcp3008(0)
                gas_concentration_channel1 = read_mcp3008(1)
                if gas_concentration_channel0 is not None and gas_concentration_channel1 is not None:
                    filtered_temperature = moving_average(temperature_readings, WINDOW_SIZE)
                    filtered_humidity = moving_average(humidity_readings, WINDOW_SIZE)
                    if filtered_temperature is not None and filtered_humidity is not None:
                        log_data(filtered_temperature, filtered_humidity, gas_concentration_channel0, gas_concentration_channel1)
                    else:
                        log_data(temperature, humidity, gas_concentration_channel0, gas_concentration_channel1)
                else:
                    log_data(temperature, humidity, None, None)
            else:
                log_data(None, None, None, None)
            time.sleep(60)
        except Exception as e:
            logging.error(f"An unexpected error occurred: {e}")
            time.sleep(60)
    cleanup()


if __name__ == "__main__":
    main()

