#!/usr/bin/env python3

import RPi.GPIO as GPIO
import spidev
import time
import datetime
import os
import signal
import sys

# Configuration
DHT_PIN = 4
RELAY_PUMP = 17
RELAY_FAN = 27
RELAY_LIGHT = 22
LED_PIN = 25
SPI_BUS = 0
SPI_DEVICE = 0
SPI_CHANNEL = 0
SENSOR_READ_INTERVAL = 300
WATCHDOG_TIMEOUT = 600

# Global state
last_sensor_read_time = time.time()
last_actuator_command_time = time.time()
spi = None
running = True

def log_message(message):
    """Logs a message to greenhouse.log with a timestamp."""
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    try:
        with open("greenhouse.log", "a") as f:
            f.write(f"{timestamp} - {message}\n")
    except IOError as e:
        print(f"Error writing to log file: {e}")

def read_dht22():
    """Reads temperature and humidity from the DHT22 sensor.
    Returns (temperature, humidity) or (None, None) on failure."""
    try:
        import adafruit_dht
        dht_device = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        dht_device.exit()
        if temperature is not None and humidity is not None:
            return temperature, humidity
        else:
            log_message("DHT22 returned None values")
            return None, None
    except RuntimeError as e:
        log_message(f"DHT22 read error: {e}")
        return None, None
    except Exception as e:
        log_message(f"Unexpected DHT22 error: {e}")
        return None, None

def read_mcp3008(channel):
    """Reads analog data from the MCP3008 ADC via SPI.
    Returns the 10-bit value (0-1023) or -1 on failure."""
    if spi is None:
        log_message("SPI not initialized")
        return -1
    try:
        # MCP3008 single-ended read command
        # Start bit (1), single-ended (1), channel (3 bits)
        command = [1, (8 + channel) << 4, 0]
        response = spi.xfer2(command)
        # Extract 10-bit value from response
        adc_value = ((response[1] & 3) << 8) + response[2]
        return adc_value
    except Exception as e:
        log_message(f"SPI read error on channel {channel}: {e}")
        return -1

def control_pump(command):
    """Controls the pump relay."""
    try:
        if command == "on":
            GPIO.output(RELAY_PUMP, GPIO.HIGH)
            log_message("Pump turned ON")
        elif command == "off":
            GPIO.output(RELAY_PUMP, GPIO.LOW)
            log_message("Pump turned OFF")
        else:
            log_message(f"Invalid pump command: {command}")
    except Exception as e:
        log_message(f"Error controlling pump: {e}")

def control_fan(command):
    """Controls the fan relay."""
    try:
        if command == "on":
            GPIO.output(RELAY_FAN, GPIO.HIGH)
            log_message("Fan turned ON")
        elif command == "off":
            GPIO.output(RELAY_FAN, GPIO.LOW)
            log_message("Fan turned OFF")
        else:
            log_message(f"Invalid fan command: {command}")
    except Exception as e:
        log_message(f"Error controlling fan: {e}")

def control_light(command):
    """Controls the light relay."""
    try:
        if command == "on":
            GPIO.output(RELAY_LIGHT, GPIO.HIGH)
            log_message("Light turned ON")
        elif command == "off":
            GPIO.output(RELAY_LIGHT, GPIO.LOW)
            log_message("Light turned OFF")
        else:
            log_message(f"Invalid light command: {command}")
    except Exception as e:
        log_message(f"Error controlling light: {e}")

def set_led_status(status):
    """Sets the status LED state."""
    try:
        if status == "online":
            GPIO.output(LED_PIN, GPIO.HIGH)
        elif status == "offline":
            GPIO.output(LED_PIN, GPIO.LOW)
        elif status == "error":
            for _ in range(5):
                GPIO.output(LED_PIN, GPIO.HIGH)
                time.sleep(0.2)
                GPIO.output(LED_PIN, GPIO.LOW)
                time.sleep(0.2)
        elif status == "synchronizing":
            for _ in range(5):
                GPIO.output(LED_PIN, GPIO.HIGH)
                time.sleep(0.2)
                GPIO.output(LED_PIN, GPIO.LOW)
                time.sleep(0.2)
        else:
            log_message(f"Invalid LED status: {status}")
    except Exception as e:
        log_message(f"Error setting LED status: {e}")

def signal_handler(sig, frame):
    """Handles termination signals for graceful shutdown."""
    global running
    log_message(f"Received signal {sig}, shutting down...")
    running = False

def cleanup():
    """Cleans up GPIO and SPI resources."""
    global spi
    try:
        GPIO.cleanup()
        log_message("GPIO cleanup completed")
    except Exception as e:
        log_message(f"Error during GPIO cleanup: {e}")
    if spi is not None:
        try:
            spi.close()
            log_message("SPI closed")
        except Exception as e:
            log_message(f"Error closing SPI: {e}")

def main():
    """Main program loop."""
    global last_sensor_read_time, last_actuator_command_time, spi, running

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize GPIO
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(RELAY_PUMP, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(RELAY_FAN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(RELAY_LIGHT, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
        log_message("GPIO initialized successfully")
    except Exception as e:
        log_message(f"Failed to initialize GPIO: {e}")
        sys.exit(1)

    # Initialize SPI
    try:
        spi = spidev.SpiDev()
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = 1000000
        spi.mode = 0
        log_message("SPI initialized successfully")
    except Exception as e:
        log_message(f"Failed to initialize SPI: {e}")
        cleanup()
        sys.exit(1)

    # Main loop
    while running:
        try:
            # Read sensor data
            temperature, humidity = read_dht22()
            if temperature is not None and humidity is not None:
                log_message(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                last_sensor_read_time = time.time()
            else:
                log_message("Failed to read sensor data")

            # Read ADC value
            adc_value = read_mcp3008(SPI_CHANNEL)
            if adc_value != -1:
                log_message(f"ADC Channel {SPI_CHANNEL}: {adc_value}")
            else:
                log_message("Failed to read ADC value")

            # Actuator control (example: turn on pump if temperature > 30°C)
            if temperature is not None and temperature > 30:
                control_pump("on")
                last_actuator_command_time = time.time()
            else:
                control_pump("off")

            # Watchdog timer
            if time.time() - last_sensor_read_time > WATCHDOG_TIMEOUT:
                log_message("Watchdog timeout: No sensor data for 600 seconds")
                os.execv(sys.executable, [sys.executable] + sys.argv)
            if time.time() - last_actuator_command_time > WATCHDOG_TIMEOUT:
                log_message("Watchdog timeout: No actuator command for 600 seconds")
                os.execv(sys.executable, [sys.executable] + sys.argv)

            # Set LED status (online)
            set_led_status("online")

            # Sleep for the interval, but check running flag periodically
            for _ in range(SENSOR_READ_INTERVAL):
                if not running:
                    break
                time.sleep(1)

        except Exception as e:
            log_message(f"An error occurred: {e}")
            set_led_status("error")
            time.sleep(1)

    # Cleanup on exit
    cleanup()

if __name__ == "__main__":
    main()

