#!/usr/bin/env python3
"""Sound sensor monitoring system for Raspberry Pi.

Supports digital sound sensors (e.g. KY-038) via GPIO and analog sound
sensors via an MCP3008 ADC.  Events are logged to a queue.Queue.
"""

import argparse
import logging
import queue
import signal
import sys
import threading
import time

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    GPIO = None

try:
    import spidev
except ImportError:
    spidev = None


class SoundSensor:
    """Base class for digital and analog sound sensors."""

    def __init__(self, sensor_id, sensor_type, threshold, sample_rate,
                 gpio_pins=None, channels=None, spi_speed=1000000,
                 log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.running = True
        self.last_event_time = 0.0
        self.event_interval = 0.5
        self.debounce_time = 0.1
        self.last_reading = None
        self.lock = threading.Lock()

        if sensor_type == "digital":
            if GPIO is None:
                raise RuntimeError("RPi.GPIO not available")
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
            if gpio_pins is None or len(gpio_pins) == 0:
                raise ValueError("gpio_pins must be provided for digital sensor")
            for pin in gpio_pins:
                GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            self.gpio_pins = gpio_pins
        elif sensor_type == "analog":
            if spidev is None:
                raise RuntimeError("spidev not available")
            self.spi = spidev.SpiDev()
            try:
                self.spi.open(0, 0)
                self.spi.max_speed_hz = self.spi_speed
                self.spi.mode = 0
            except Exception as e:
                logging.error("Failed to initialize SPI: %s", e)
                raise
            if channels is None or len(channels) == 0:
                raise ValueError("channels must be provided for analog sensor")
            self.channels = channels
        else:
            raise ValueError("Invalid sensor_type. Must be 'digital' or 'analog'.")

    def read(self):
        """Read the sensor value.  Returns None on error."""
        if self.sensor_type == "digital":
            try:
                return self._read_gpio()
            except Exception as e:
                logging.error("Error reading digital sensor %s: %s", self.sensor_id, e)
                return None
        elif self.sensor_type == "analog":
            try:
                return self._read_mcp3008()
            except Exception as e:
                logging.error("Error reading analog sensor %s: %s", self.sensor_id, e)
                return None
        return None

    def _read_gpio(self):
        """Read digital sensor via GPIO."""
        with self.lock:
            for pin in self.gpio_pins:
                try:
                    return GPIO.input(pin)
                except Exception as e:
                    logging.error("Error reading GPIO pin %s: %s", pin, e)
        return None

    def _read_mcp3008(self):
        """Read analog sensor via MCP3008 single-ended channel."""
        channel = self.channels[0]
        if not 0 <= channel <= 7:
            raise ValueError("MCP3008 channel must be 0-7")
        try:
            adc = self.spi.xfer2([1, (8 + channel) << 4, 0])
            data = ((adc[1] & 3) << 8) + adc[2]
            return data
        except Exception as e:
            logging.error("SPI transfer failed for channel %s: %s", channel, e)
            return None

    def detect_event(self):
        """Return True if a sound event should be logged."""
        reading = self.read()
        if reading is None:
            return False
        if self.sensor_type == "digital":
            if reading == 1:
                return True
        elif self.sensor_type == "analog":
            if reading >= self.threshold:
                return True
        return False

    def log_event(self):
        """Log a sound event to the queue."""
        if self.log_queue is not None:
            try:
                self.log_queue.put_nowait(
                    {"sensor_id": self.sensor_id, "event_time": time.time()}
                )
            except queue.Full:
                logging.warning("Log queue full for sensor %s", self.sensor_id)

    def run(self):
        """Main sampling loop."""
        while self.running:
            if self.detect_event():
                now = time.time()
                if now - self.last_event_time > self.event_interval:
                    self.log_event()
                    self.last_event_time = now
            time.sleep(1 / self.sample_rate)

    def stop(self):
        """Stop the sensor and release resources."""
        self.running = False
        if self.sensor_type == "digital":
            if GPIO is not None:
                try:
                    GPIO.cleanup()
                except Exception:
                    pass
        if self.sensor_type == "analog":
            if self.spi is not None:
                try:
                    self.spi.close()
                except Exception:
                    pass


def main():
    parser = argparse.ArgumentParser(
        description="Sound sensor monitoring system for Raspberry Pi"
    )
    parser.add_argument("--sensor_type", required=True,
                        choices=["digital", "analog"])
    parser.add_argument("--threshold", type=int, required=True)
    parser.add_argument("--sample_rate", type=int, required=True)
    parser.add_argument("--log_file", required=True)
    parser.add_argument("--gpio_pins", nargs="+", type=int)
    parser.add_argument("--channels", nargs="+", type=int)
    parser.add_argument("--spi_speed", type=int, default=1000000)
    parser.add_argument("--sensor_ids", nargs="+", type=int, required=True)
    args = parser.parse_args()

    logging.basicConfig(
        filename=args.log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )
    log_queue = queue.Queue()

    sensors = []
    for sid in args.sensor_ids:
        s = SoundSensor(
            sid, args.sensor_type, args.threshold, args.sample_rate,
            gpio_pins=args.gpio_pins, channels=args.channels,
            spi_speed=args.spi_speed, log_queue=log_queue,
        )
        sensors.append(s)

    def signal_handler(signum, frame):
        logging.info("Signal %s received, shutting down", signum)
        for s in sensors:
            s.stop()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    threads = []
    for s in sensors:
        t = threading.Thread(target=s.run, daemon=True)
        t.start()
        threads.append(t)

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received")
    finally:
        for s in sensors:
            s.stop()
        for t in threads:
            t.join(timeout=2)
        logging.info("Program finished")


if __name__ == "__main__":
    main()

