import time
import signal
import sys
import board
import busio
import adafruit_max30102

LOG_FILE = 'heart_rate_log.txt'
PEAK_WINDOW = 4.0
SAMPLE_INTERVAL = 1.0

_running = True

def _handle_sigint(signum, frame):
    global _running
    _running = False

def _format_sensor_value(value, part_id):
    """Defensively format a sensor value, handling _AdaValue objects."""
    try:
        return str(int(value))
    except (TypeError, ValueError):
        try:
            return str(value)
        except Exception:
            return f'_AdaValue(part={part_id})'

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_sigint)

    i2c = None
    sensor = None
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        sensor = adafruit_max30102.MAX30102(i2c)
        print('MAX30102 initialized on I2C bus.')
    except Exception as e:
        print(f'Fatal: Failed to initialize MAX30102: {e}', file=sys.stderr)
        sys.exit(1)

    peaks = []
    last_sample_time = 0.0

    try:
        while _running:
            loop_start = time.monotonic()
            try:
                ir = sensor.ir_buffer
                red = sensor.red_buffer
            except Exception as e:
                print(f'Warning: Sensor read failed: {e}', file=sys.stderr)
                time.sleep(SAMPLE_INTERVAL)
                continue

            now = time.monotonic()
            if now - last_sample_time >= SAMPLE_INTERVAL:
                last_sample_time = now
                peaks.append(now)

                if len(peaks) > int(PEAK_WINDOW / SAMPLE_INTERVAL):
                    peaks.pop(0)

                if len(peaks) >= 2:
                    try:
                        delta = peaks[-1] - peaks[-2]
                        if delta > 0:
                            bpm = 60.0 / delta
                            ts = time.strftime('%Y-%m-%dT%H:%M:%S')
                            log_entry = f'{ts} - Heart Rate: {bpm:.2f} bpm\n'
                            try:
                                with open(LOG_FILE, 'a') as f:
                                    f.write(log_entry)
                            except OSError as e:
                                print(f'Warning: Could not write to log file: {e}', file=sys.stderr)
                            print(f'Heart Rate: {bpm:.2f} bpm')
                    except ZeroDivisionError:
                        pass

            elapsed = time.monotonic() - loop_start
            remaining = SAMPLE_INTERVAL - elapsed
            if remaining > 0:
                time.sleep(remaining)

    except Exception as e:
        print(f'Fatal error: {e}', file=sys.stderr)
    finally:
        if i2c is not None:
            try:
                i2c.deinit()
            except Exception:
                pass
        print('Program terminated.')

if __name__ == '__main__':
    main()

