import cv2
import signal
import sys

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_camera():
    """Initializes the Raspberry Pi camera and returns the capture object."""
    try:
        camera = cv2.VideoCapture(0)
        if not camera.isOpened():
            raise IOError("Cannot open camera")
        return camera
    except Exception as e:
        raise RuntimeError(f"Error initializing camera: {e}")

def load_cascades():
    """Loads face and eye detection cascade classifiers."""
    face_cascade_path = cv2.data.haarcascades + 'haarcascade_frontalface_default.xml'
    eye_cascade_path = cv2.data.haarcascades + 'haarcascade_eye.xml'

    face_cascade = cv2.CascadeClassifier(face_cascade_path)
    eye_cascade = cv2.CascadeClassifier(eye_cascade_path)

    if face_cascade.empty() or eye_cascade.empty():
        raise RuntimeError("Error loading cascade classifiers. Check file paths.")

    return face_cascade, eye_cascade

def detect_faces_and_eyes(frame, face_cascade, eye_cascade):
    """Detects faces and eyes in a frame and draws rectangles."""
    gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    faces = face_cascade.detectMultiScale(gray, 1.1, 5, (30, 30))

    for (x, y, w, h) in faces:
        cv2.rectangle(frame, (x, y), (x + w, y + h), (0, 255, 0), 2)
        roi_gray = gray[y:y + h, x:x + w]
        eyes = eye_cascade.detectMultiScale(roi_gray, 1.1, 3, (20, 20))
        for (ex, ey, ew, eh) in eyes:
            cv2.rectangle(frame, (x + ex, y + ey), (x + ex + ew, y + ey + eh), (0, 0, 255), 2)

def main():
    """Main function to run face and eye detection."""
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    camera = None
    try:
        camera = initialize_camera()
        face_cascade, eye_cascade = load_cascades()

        while _running:
            ret, frame = camera.read()
            if not ret:
                print("Failed to grab frame")
                break

            detect_faces_and_eyes(frame, face_cascade, eye_cascade)
            cv2.imshow("Face and Eye Detection", frame)

            if cv2.waitKey(1) & 0xFF == ord('q'):
                break

    except RuntimeError as e:
        print(f"Error: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        if camera is not None:
            camera.release()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

