import cv2
import time
import signal
import sys

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_camera():
    try:
        camera = cv2.VideoCapture(0, cv2.CAP_V4L2)
        if not camera.isOpened():
            raise IOError("Cannot open Raspberry Pi camera (index 0).")
        camera.set(cv2.CAP_PROP_FRAME_WIDTH, 640)
        camera.set(cv2.CAP_PROP_FRAME_HEIGHT, 480)
        camera.set(cv2.CAP_PROP_FPS, 30)
        camera.set(cv2.CAP_PROP_FORMAT, cv2.CV_CAP_RGB888)
        return camera
    except Exception as e:
        print(f"Error initializing camera: {e}", file=sys.stderr)
        return None

def process_frame(frame):
    try:
        gray_frame = cv2.cvtColor(frame, cv2.COLOR_RGB2GRAY)
        return frame, gray_frame
    except Exception as e:
        print(f"Error processing frame: {e}", file=sys.stderr)
        return None, None

def display_frames(frame, gray_frame, fps, text):
    try:
        cv2.putText(frame, f"{round(fps)} FPS", (10, 30),
                    cv2.FONT_HERSHEY_SIMPLEX, 1, (0, 0, 255), 2)
        cv2.imshow('OriginalRGB', frame)
        cv2.imshow('Grayscale', gray_frame)
    except Exception as e:
        print(f"Error displaying frames: {e}", file=sys.stderr)

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    camera = initialize_camera()
    if camera is None:
        sys.exit(1)

    try:
        while _running:
            start_time = time.time()

            ret, frame = camera.read()
            if not ret:
                print("Failed to grab frame", file=sys.stderr)
                break

            processed_frame, gray_frame = process_frame(frame)
            if processed_frame is None or gray_frame is None:
                continue

            display_frames(processed_frame, gray_frame, 1.0 / (time.time() - start_time), "Real-time")

            key = cv2.waitKey(1) & 0xFF
            if key == 27 or key == ord('q'):
                break
    finally:
        _running = False
        try:
            camera.release()
        except Exception:
            pass
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

