import cv2
import numpy as np
import logging
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class CameraFeed:
    def __init__(self, camera_index=0):
        self.camera_index = camera_index
        self.capture = None
        self.frame = None
        self.prev_frame = None
        self.running = False

    def open(self):
        self.capture = cv2.VideoCapture(self.camera_index, cv2.CAP_V4L2)
        if not self.capture.isOpened():
            logging.error(f"Could not open camera at index {self.camera_index}.")
            return False
        self.capture.set(cv2.CAP_PROP_FRAME_WIDTH, 32)
        self.capture.set(cv2.CAP_PROP_FRAME_HEIGHT, 32)
        self.running = True
        return True

    def read(self):
        if not self.running or self.capture is None:
            return False, None
        ret, frame = self.capture.read()
        if not ret or frame is None:
            logging.error("Failed to read frame from camera.")
            return False, None
        self.frame = frame
        return True, frame

    def process(self):
        if self.frame is None:
            return None
        gray = cv2.cvtColor(self.frame, cv2.COLOR_BGR2GRAY)
        gray = cv2.GaussianBlur(gray, (3, 3), 0)
        compensated = self._lighting_compensation(gray)
        edges = cv2.Canny(gray, 100, 200)
        return gray, compensated, edges

    @staticmethod
    def _lighting_compensation(gray):
        clahe = cv2.createCLAHE(clipLimit=2.0, tileGridSize=(8, 8))
        return clahe.apply(gray)

    def detect_motion(self):
        if self.prev_frame is None:
            self.prev_frame = self.frame.copy()
            return False
        diff = cv2.absdiff(self.prev_frame, self.frame)
        gray_diff = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
        _, thresh = cv2.threshold(gray_diff, 25, 255, cv2.THRESH_BINARY)
        self.prev_frame = self.frame.copy()
        return bool(np.sum(thresh) > 0)

    def release(self):
        self.running = False
        if self.capture is not None:
            self.capture.release()
            self.capture = None

def main():
    feed = CameraFeed(camera_index=0)
    if not feed.open():
        sys.exit(1)
    try:
        while feed.running:
            ret, frame = feed.read()
            if not ret:
                break
            gray, compensated, edges = feed.process()
            if feed.detect_motion():
                logging.info("Motion Detected using MSE!")
            cv2.imshow('Original', frame)
            cv2.imshow('Compensated', compensated)
            cv2.imshow('Grayscale', gray)
            cv2.imshow('Edges', edges)
            if cv2.waitKey(1) & 0xFF == 27:
                break
    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        feed.release()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

