        if MotionSensor is None:
            logging.warning("gpiozero not available; PIR disabled.")
            return
        try:
            self.sensor = MotionSensor(self.pin, pull_up=False)
            self._initialized = True
            logging.info(f"PIR sensor initialized on GPIO {self.pin}.")
        except Exception as e:
            logging.error(f"Failed to initialize PIR sensor: {e}")
            self.sensor = None
            self._initialized = False

    def wait_for_motion(self, timeout=10):
        if not self._initialized or self.sensor is None:
            logging.warning("PIR sensor not available; returning immediately.")
            return False
        try:
            if self.sensor.wait_for_motion(timeout=timeout):
                logging.info("Motion detected!")
                return True
            return False
        except Exception as e:
            logging.error(f"Error waiting for motion: {e}")
            return False

    def close(self):
        if self.sensor is not None:
            try:
                self.sensor.close()
            except Exception:
                pass
            self.sensor = None
            self._initialized = False
            logging.info("PIR sensor closed.")


def parse_arguments():
    parser = configargparse.ArgumentParser(
        default_config_files=["config.ini"],
        auto_env_var_prefix="CAMERA",
    )
    parser.add_argument("--storage_directory", type=str, default="/home/pi/camera_storage")
    parser.add_argument("--disk_space_threshold_mb", type=int, default=100)
    parser.add_argument("--log_file", type=str, default="/home/pi/logs/camera.log")
    parser.add_argument("--pir_pin", type=int, default=4)
    parser.add_argument("--image_width", type=int, default=1920)
    parser.add_argument("--image_height", type=int, default=1080)
    parser.add_argument("--image_quality", type=int, default=85)
    parser.add_argument("--image_bitrate", type=int, default=64)
    parser.add_argument("--video_bitrate", type=int, default=1700000)
    parser.add_argument("--video_frame_rate", type=int, default=20)
    parser.add_argument("--capture_delay", type=float, default=2)
    parser.add_argument("--num_images", type=int, default=3)
    parser.add_argument("--image_interval", type=float, default=0.5)
    parser.add_argument("--video_duration", type=float, default=5)
    return parser.parse_args()


def ensure_log_file(log_file):
    log_dir = os.path.dirname(log_file)
    if log_dir and not os.path.isdir(log_dir):
        try:
            os.makedirs(log_dir, exist_ok=True)
        except OSError as e:
            logging.error(f"Cannot create log directory {log_dir}: {e}")
            log_file = "./logs/camera.log"
    if not os.path.isfile(log_file):
        try:
            with open(log_file, "w") as f:
                f.write("Logging started.\n")
        except OSError as e:
            logging.error(f"Cannot create log file {log_file}: {e}")
            log_file = "./logs/camera.log"
    return log_file


def setup_logging(log_file):
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )
    return ensure_log_file(log_file)


def get_storage_path(storage_directory):
    today = datetime.date.today()
    return os.path.join(storage_directory, today.strftime("%Y/%m/%d"))


def check_disk_space(storage_directory, threshold_mb):
    statvfs = os.statvfs if hasattr(os, "statvfs") else None
    try:
        if statvfs is not None:
            fs_stat = statvfs(storage_directory)
            free_bytes = fs_stat.f_frsize * fs_stat.f_bavail
        else:
            free_bytes = os.path.getfree(storage_directory)
        free_mb = free_bytes / (1024 * 1024)
        if free_mb < threshold_mb:
            logging.warning(
                f"Disk space low: {free_mb:.2f} MB free, threshold {threshold_mb} MB."
            )
            return False
        return True
    except Exception as e:
        logging.error(f"Error checking disk space: {e}")
        return False


def manage_disk_space(storage_directory, threshold_mb):
    logging.info("Starting disk space management...")
    try:
        files = []
        for root, _, fnames in os.walk(storage_directory, topdown=False):
            for fname in fnames:
                fp = os.path.join(root, fname)
                try:
                    fsize = os.path.getsize(fp)
                except OSError:
                    continue
                if fsize > 0:
                    files.append((fp, fsize))
        if not files:
            logging.info("No files to manage.")
            return
        files.sort(key=lambda x: x[1])
        total_deleted = 0
        for fp, fsize in files:
            try:
                os.remove(fp)
                total_deleted += fsize
                logging.info(f"Deleted old file: {fp}")
            except OSError as e:
                logging.error(f"Error deleting {fp}: {e}")
                break
        logging.info(f"Disk space management completed. Deleted {total_deleted} bytes.")
    except Exception as e:
        logging.error(f"Error during disk space management: {e}")


def signal_handler(signum, frame, camera_mgr, pir_mgr):
    logging.info(f"Received signal {signum}, shutting down...")
    camera_mgr.close()
    pir_mgr.close()
    sys.exit(0)


def main():
    args = parse_arguments()
    setup_logging(args.log_file)

    storage_path = get_storage_path(args.storage_directory)
    try:
        os.makedirs(storage_path, exist_ok=True)
    except OSError as e:
        logging.error(f"Cannot create storage directory {storage_path}: {e}")
        sys.exit(1)

    camera_mgr = CameraManager()
    pir_mgr = MotionSensorManager(args.pir_pin)

    signal.signal(signal.SIGINT, lambda s, f: signal_handler(s, f, camera_mgr, pir_mgr))
    signal.signal(signal.SIGTERM, lambda s, f: signal_handler(s, f, camera_mgr, pir_mgr))

    logging.info("Starting camera monitoring system...")

    try:
        while True:
            if not check_disk_space(storage_path, args.disk_space_threshold_mb):
                manage_disk_space(storage_path, args.disk_space_threshold_mb)
                continue

            if pir_mgr.wait_for_motion(timeout=10):
                logging.info("Motion detected!")
                timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
                image_prefix = os.path.join(
                    storage_path, f"{timestamp}_image"
                )
                video_filename = os.path.join(
                    storage_path, f"{timestamp}_video.h264"
                )

                logging.info(
                    f"Capturing {args.num_images} images with "
                    f"{args.image_interval}s interval..."
                )
                for i in range(args.num_images):
                    image_filename = f"{image_prefix}_{i:03d}.jpg"
                    if camera_mgr.capture_still(
                        image_filename,
                        quality=args.image_quality,
                        bitrate=args.image_bitrate,
                    ):
                        time.sleep(args.image_interval)

                logging.info(
                    f"Capturing video for {args.video_duration}s "
                    f"at {args.video_frame_rate} fps..."
                )
                if camera_mgr.capture_video(
                    video_filename,
                    duration=args.video_duration,
                    bitrate=args.video_bitrate,
                    framerate=args.video_frame_rate,
                ):
                    logging.info("Capture sequence complete.")
                else:
                    logging.error("Capture sequence failed.")

                time.sleep(args.capture_delay)
            else:
                logging.debug("No motion detected.")
                time.sleep(1)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        camera_mgr.close()
        pir_mgr.close()
        logging.info("Camera monitoring system stopped.")


if __name__ == "__main__":
    main()

