import cv2
import numpy as np
import serial
import serial.tools.list_ports
import signal
import sys
import time

running = True

def signal_handler(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def open_camera():
    cap = cv2.VideoCapture(0)
    if not cap.isOpened():
        print("Error: Could not open camera.")
        return None
    return cap

def open_serial_port():
    available = [p.device for p in serial.tools.list_ports.comports()]
    preferred = '/dev/ttyACM0'
    if preferred not in available:
        print(f"Warning: {preferred} not found. Available: {available}")
        if available:
            port = available[0]
            print(f"Using fallback port: {port}")
            try:
                ser = serial.Serial(port, 9600, timeout=1)
                return ser
            except serial.SerialException as e:
                print(f"Error opening fallback port {port}: {e}")
                return None
        else:
            print("Warning: No serial ports found. Continuing without serial output.")
            return None
    else:
        try:
            ser = serial.Serial(preferred, 9600, timeout=1)
            return ser
        except serial.SerialException as e:
            print(f"Error opening {preferred}: {e}")
            return None

def classify_ball(x, y, w, h):
    cx = x + w // 2
    cy = y + h // 2
    if cx > w - 50 and cy > h - 50:
        return '1'
    if cx > w - 50 and cy < 50:
        return '2'
    if cx < 50 and cy > h - 50:
        return '3'
    if cx < 50 and cy < 50:
        return '4'
    return '5'

def main():
    global running
    cap = open_camera()
    if cap is None:
        sys.exit(1)
    ser = open_serial_port()
    tracking = False
    min_hsv = np.array([0, 0, 0])
    max_hsv = np.array([0, 0, 0])
    try:
        while running:
            ret, frame = cap.read()
            if not ret:
                print("Error: Could not read frame from camera.")
                break
            h, w = frame.shape[:2]
            hsv = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
            if tracking:
                mask = cv2.inRange(hsv, min_hsv, max_hsv)
                contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
                for c in contours:
                    if cv2.contourArea(c) > 500:
                        x, y, sw, sh = cv2.boundingRect(c)
                        cv2.rectangle(frame, (x, y), (x + sw, y + sh), (255, 0, 0), 2)
                        pos = classify_ball(x, y, sw, sh)
                        if ser is not None:
                            try:
                                ser.write(pos.encode('utf-8'))
                            except serial.SerialException as e:
                                print(f"Error writing to serial port: {e}")
                cv2.imshow("Mask", mask)
            cv2.imshow("Frame", frame)
            key = cv2.waitKey(1) & 0xFF
            if key == ord('s'):
                h_roi = hsv[h // 2 - 10:h // 2 + 10, w // 2 - 10:w // 2 + 10]
                min_hsv = np.array([h_roi[:, :, 0].min(), h_roi[:, :, 1].min(), h_roi[:, :, 2].min()])
                max_hsv = np.array([h_roi[:, :, 0].max(), h_roi[:, :, 1].max(), h_roi[:, :, 2].max()])
                tracking = True
            elif key == ord('o'):
                tracking = False
            elif key == 27:
                running = False
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if cap is not None:
            cap.release()
        if ser is not None and ser.is_open:
            ser.close()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

