import os
import sys
import time
import signal
import random
import logging
import threading
import numpy as np
from PIL import Image

try:
    import RPi.GPIO as GPIO
except ImportError:
    GPIO = None

try:
    import cv2
except ImportError:
    cv2 = None

try:
    import speech_recognition as sr
except ImportError:
    sr = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DHT_PIN = 4
LIGHT_PIN = 17
CAMERA_RESOLUTION = (640, 480)
CAMERA_FRAMERATE = 10
AUDIO_SAMPLE_RATE = 16000
AUDIO_CHANNELS = 1
AUDIO_CHUNK_SIZE = 1024
WAKE_WORD_THRESHOLD = 0.7
WAKE_WORD_TIMEOUT = 5
TEMPERATURE_RANGE = (15, 35)

class GreenhouseController:
    def __init__(self):
        self.lights_on = False
        self.camera = None
        self.recognizer = None
        self.listener = None
        self.running = True
        self._lock = threading.Lock()
        self._init_gpio()
        self._init_camera()
        self._init_speech()

    def _init_gpio(self):
        if GPIO is None:
            logging.warning("RPi.GPIO not available; simulating GPIO.")
            return
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(LIGHT_PIN, GPIO.OUT, initial=GPIO.LOW)
            logging.info("GPIO initialized.")
        except Exception as e:
            logging.error(f"GPIO init failed: {e}; simulating.")
            GPIO = None

    def _init_camera(self):
        if cv2 is None:
            logging.warning("OpenCV not available; camera disabled.")
            return
        try:
            self.camera = cv2.VideoCapture(0)
            if not self.camera.isOpened():
                raise RuntimeError("Cannot open camera.")
            self.camera.set(cv2.CAP_PROP_FRAME_WIDTH, CAMERA_RESOLUTION[0])
            self.camera.set(cv2.CAP_PROP_FRAME_HEIGHT, CAMERA_RESOLUTION[1])
            self.camera.set(cv2.CAP_PROP_FPS, CAMERA_FRAMERATE)
            logging.info("Camera initialized.")
        except Exception as e:
            logging.error(f"Camera init failed: {e}; camera disabled.")
            self.camera = None

    def _init_speech(self):
        if sr is None:
            logging.warning("SpeechRecognition not available; voice commands disabled.")
            return
        try:
            self.recognizer = sr.Recognizer()
            self.microphone = sr.Microphone()
            with self.microphone as source:
                self.recognizer.adjust_for_ambient_noise(source, duration=0.5)
            logging.info("Speech recognizer initialized.")
        except Exception as e:
            logging.error(f"Speech init failed: {e}; voice commands disabled.")
            self.recognizer = None

    def _cleanup(self, signum=None, frame=None):
        logging.info("Shutting down...")
        self.running = False
        with self._lock:
            if self.camera is not None:
                try:
                    self.camera.release()
                except Exception:
                    pass
                self.camera = None
            if GPIO is not None:
                try:
                    GPIO.cleanup()
                except Exception:
                    pass
        if signum is not None:
            sys.exit(0)

    def read_temperature(self):
        if GPIO is None:
            return random.uniform(*TEMPERATURE_RANGE)
        try:
            import RPi.GPIO as GPIO
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(DHT_PIN, GPIO.OUT)
            GPIO.output(DHT_PIN, GPIO.LOW)
            time.sleep(0.018)
            GPIO.output(DHT_PIN, GPIO.HIGH)
            time.sleep(0.000040)
            GPIO.output(DHT_PIN, GPIO.LOW)
            time.sleep(0.000040)
            GPIO.setup(DHT_PIN, GPIO.IN)
            count = 0
            data = 0
            while GPIO.input(DHT_PIN) == GPIO.HIGH:
                count += 1
                if count > 100:
                    raise RuntimeError("DHT11 timeout waiting for low")
            while GPIO.input(DHT_PIN) == GPIO.LOW:
                count += 1
                if count > 100:
                    raise RuntimeError("DHT11 timeout waiting for high")
            while GPIO.input(DHT_PIN) == GPIO.HIGH:
                count += 1
                if count > 100:
                    raise RuntimeError("DHT11 timeout waiting for low after high")
            while GPIO.input(DHT_PIN) == GPIO.LOW:
                count += 1
                if count > 100:
                    raise RuntimeError("DHT11 timeout waiting for high after low")
            for _ in range(8):
                while GPIO.input(DHT_PIN) == GPIO.LOW:
                    count += 1
                    if count > 100:
                        raise RuntimeError("DHT11 timeout reading bit")
                count += 1
                data = data << 1
                if GPIO.input(DHT_PIN) == GPIO.HIGH:
                    data |= 1
            humidity = (data & 0xFF00) >> 8
            temperature = data & 0xFF
            checksum = (humidity >> 4) + (humidity & 0x0F) + (temperature >> 4) + (temperature & 0x0F)
            if (checksum & 0x07) != 0:
                raise RuntimeError(f"DHT11 checksum error: {checksum}")
            return temperature
        except Exception as e:
            logging.warning(f"Temperature read failed: {e}; using simulated value.")
            return random.uniform(*TEMPERATURE_RANGE)

    def turn_on_lights(self):
        with self._lock:
            if self.lights_on:
                logging.info("Lights already on.")
                return
            if GPIO is not None:
                try:
                    GPIO.output(LIGHT_PIN, GPIO.HIGH)
                    self.lights_on = True
                    logging.info("Lights turned on.")
                except Exception as e:
                    logging.error(f"GPIO write failed: {e}")
            else:
                logging.warning("Simulating lights on.")
                self.lights_on = True

    def turn_off_lights(self):
        with self._lock:
            if not self.lights_on:
                logging.info("Lights already off.")
                return
            if GPIO is not None:
                try:
                    GPIO.output(LIGHT_PIN, GPIO.LOW)
                    self.lights_on = False
                    logging.info("Lights turned off.")
                except Exception as e:
                    logging.error(f"GPIO write failed: {e}")
            else:
                logging.warning("Simulating lights off.")
                self.lights_on = False

    def take_picture(self):
        if self.camera is None:
            logging.warning("Camera not available; cannot take picture.")
            return
        try:
            ret, frame = self.camera.read()
            if not ret or frame is None:
                raise RuntimeError("Failed to capture frame.")
            timestamp = int(time.time() * 1000)
            filename = f"greenhouse_{timestamp}.jpg"
            img = Image.fromarray(frame)
            img.save(filename)
            logging.info(f"Picture saved as {filename}")
        except Exception as e:
            logging.error(f"Picture capture failed: {e}")

    def listen_for_wake_word(self):
        if self.recognizer is None:
            logging.warning("Speech recognizer not available; listening disabled.")
            return
        try:
            with self.microphone as source:
                logging.info("Listening for wake word...")
                audio = self.recognizer.listen(source, timeout=WAKE_WORD_TIMEOUT, phrase_time_limit=5)
            try:
                text = self.recognizer.recognize_google(audio)
                logging.info(f"Recognized: {text}")
                return text.lower()
            except sr.UnknownValueError:
                logging.warning("Speech not understood.")
                return None
            except sr.RequestError as e:
                logging.error(f"Speech API error: {e}")
                return None
        except Exception as e:
            logging.error(f"Listening failed: {e}")
            return None

    def process_command(self, command):
        if not command:
            return
        if "turn on the lights" in command:
            self.turn_on_lights()
        elif "turn off the lights" in command:
            self.turn_off_lights()
        elif "what is the temperature" in command:
            temp = self.read_temperature()
            logging.info(f"Temperature: {temp:.1f} C")
        elif "take a picture" in command:
            self.take_picture()
        else:
            logging.warning(f"Unknown command: {command}")

    def run(self):
        signal.signal(signal.SIGINT, self._cleanup)
        signal.signal(signal.SIGTERM, self._cleanup)
        logging.info("Greenhouse controller started.")
        while self.running:
            command = self.listen_for_wake_word()
            if command and "greenhouse" in command:
                self.process_command(command)
        self._cleanup()

if __name__ == "__main__":
    controller = GreenhouseController()
    controller.run()

