            GPIO.output(DHT_PIN, GPIO.HIGH)
            time.sleep(0.000040)
            GPIO.output(DHT_PIN, GPIO.LOW)
            time.sleep(0.000040)
            GPIO.setup(DHT_PIN, GPIO.IN)
            count = 0
            data = 0
            while GPIO.input(DHT_PIN) == GPIO.HIGH:
                count += 1
                if count > 100:
                    raise RuntimeError("DHT11 timeout waiting for low")
            while GPIO.input(DHT_PIN) == GPIO.LOW:
                count += 1
                if count > 100:
                    raise RuntimeError("DHT11 timeout waiting for high")
            while GPIO.input(DHT_PIN) == GPIO.HIGH:
                count += 1
                if count > 100:
                    raise RuntimeError("DHT11 timeout waiting for low after high")
            while GPIO.input(DHT_PIN) == GPIO.LOW:
                count += 1
                if count > 100:
                    raise RuntimeError("DHT11 timeout waiting for high after low")
            for _ in range(8):
                while GPIO.input(DHT_PIN) == GPIO.LOW:
