        except Exception as e:
            logging.error(f"Picture capture failed: {e}")

    def listen_for_wake_word(self):
        if self.recognizer is None:
            logging.warning("Speech recognizer not available; listening disabled.")
            return
        try:
            with self.microphone as source:
                logging.info("Listening for wake word...")
                audio = self.recognizer.listen(source, timeout=WAKE_WORD_TIMEOUT, phrase_time_limit=5)
