        if not command:
            return
        if "turn on the lights" in command:
            self.turn_on_lights()
        elif "turn off the lights" in command:
            self.turn_off_lights()
        elif "what is the temperature" in command:
            temp = self.read_temperature()
            logging.info(f"Temperature: {temp:.1f} C")
        elif "take a picture" in command:
            self.take_picture()
        else:
            logging.warning(f"Unknown command: {command}")

    def run(self):
        signal.signal(signal.SIGINT, self._cleanup)
        signal.signal(signal.SIGTERM, self._cleanup)
        logging.info("Greenhouse controller started.")
        while self.running:
            command = self.listen_for_wake_word()
            if command and "greenhouse" in command:
                self.process_command(command)
        self._cleanup()

if __name__ == "__main__":
    controller = GreenhouseController()
    controller.run()

