import io
import os
import time
import signal
import logging
import configparser
import threading
from datetime import datetime

import numpy as np
import cv2
from picamera2 import Picamera2
from libcamera import Transform
import smbus2
import RPi.GPIO as GPIO

# --- Configuration ---
CONFIG_FILE = 'config.ini'
DEFAULT_CONFIG = {
    'camera': {
        'resolution_width': '1280',
        'resolution_height': '720',
        'framerate': '24',
    },
    'motion_detection': {
        'motion_threshold': '25',
        'motion_sensitivity': '10',
        'debounce_time': '0.5',
    },
    'recording': {
        'recording_duration': '5',
        'disk_space_limit': '100',
    },
    'logging': {
        'log_level': 'INFO',
    },
    'filesystem': {
        'storage_path': '/home/pi/security_footage',
    },
    'camera_id': 'camera1',
}

# --- Logging Setup ---
logging.basicConfig(
    filename='security_system.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s',
)

# --- Global Variables ---
running = True
bus = None
picam2 = None
last_frame = None
circular_buffer = []
config = configparser.ConfigParser()
config.read_dict(DEFAULT_CONFIG)
config.read(CONFIG_FILE)

# --- Signal Handling ---
def signal_handler(sig, frame):
    global running
    logging.info(f"Received signal {sig}, shutting down...")
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# --- Configuration Management ---
def load_config():
    config.read(CONFIG_FILE)
    logging.info("Configuration loaded.")

def save_config():
    with open(CONFIG_FILE, 'w') as configfile:
        config.write(configfile)
    logging.info("Configuration saved.")

# --- Camera Functions ---
def initialize_camera():
    global picam2
    try:
        picam2 = Picamera2()
        width = int(config['camera']['resolution_width'])
        height = int(config['camera']['resolution_height'])
        framerate = int(config['camera']['framerate'])
        config_dict = picam2.create_video_configuration(
            main={"size": (width, height), "format": "YUV420"},
            controls={"FrameRate": framerate},
            transform=Transform(hflip=True, vflip=True),
        )
        picam2.configure(config_dict)
        picam2.start()
        logging.info("Camera initialized successfully.")
        return True
    except Exception as e:
        logging.error(f"Error initializing camera: {e}")
        return False

def capture_frame():
    try:
        return picam2.capture_array()
    except Exception as e:
        logging.error(f"Error capturing frame: {e}")
        return None

def capture_low_resolution_frame():
    try:
        return picam2.capture_array("lores")
    except Exception as e:
        logging.error(f"Error capturing low-res frame: {e}")
        return None

def record_video(filename):
    try:
        picam2.start_recording(filename)
        logging.info(f"Started recording: {filename}")
        time.sleep(int(config['recording']['recording_duration']))
        picam2.stop_recording()
        logging.info(f"Stopped recording: {filename}")
    except Exception as e:
        logging.error(f"Error recording video: {e}")

# --- Motion Detection ---
def detect_motion(frame1, frame2):
    try:
        yuv1 = cv2.cvtColor(frame1, cv2.COLOR_YUV420p2BGR)
        yuv2 = cv2.cvtColor(frame2, cv2.COLOR_YUV420p2BGR)
        gray1 = cv2.cvtColor(yuv1, cv2.COLOR_BGR2GRAY)
        gray2 = cv2.cvtColor(yuv2, cv2.COLOR_BGR2GRAY)
        frame_delta = cv2.absdiff(gray1, gray2)
        thresh = cv2.threshold(frame_delta, 25, 255, cv2.THRESH_BINARY)[1]
        thresh = cv2.dilate(thresh, None, iterations=2)
        return np.sum(thresh > 0)
    except Exception as e:
        logging.error(f"Error detecting motion: {e}")
        return 0

def calculate_average_pixel_difference(frame1, frame2):
    try:
        yuv1 = cv2.cvtColor(frame1, cv2.COLOR_YUV420p2BGR)
        yuv2 = cv2.cvtColor(frame2, cv2.COLOR_YUV420p2BGR)
        gray1 = cv2.cvtColor(yuv1, cv2.COLOR_BGR2GRAY)
        gray2 = cv2.cvtColor(yuv2, cv2.COLOR_BGR2GRAY)
        return float(np.mean(np.abs(gray1.astype(np.int16) - gray2.astype(np.int16))))
    except Exception as e:
        logging.error(f"Error calculating average pixel difference: {e}")
        return 0.0

def calculate_percentage_changed(frame1, frame2):
    try:
        yuv1 = cv2.cvtColor(frame1, cv2.COLOR_YUV420p2BGR)
        yuv2 = cv2.cvtColor(frame2, cv2.COLOR_YUV420p2BGR)
        gray1 = cv2.cvtColor(yuv1, cv2.COLOR_BGR2GRAY)
        gray2 = cv2.cvtColor(yuv2, cv2.COLOR_BGR2GRAY)
        diff = cv2.absdiff(gray1, gray2)
        thresh = cv2.threshold(diff, 25, 255, cv2.THRESH_BINARY)[1]
        thresh = cv2.dilate(thresh, None, iterations=2)
        return float(np.mean(thresh > 0))
    except Exception as e:
        logging.error(f"Error calculating percentage changed: {e}")
        return 0.0

def check_disk_space_limit():
    try:
        total, used, free = os.disk_usage(config['filesystem']['storage_path'])
        total_mb = total // (2**20)
        used_mb = used // (2**20)
        if used_mb > int(config['recording']['disk_space_limit']):
            logging.warning("Disk space limit exceeded. Deleting oldest files.")
            delete_oldest_files()
    except Exception as e:
        logging.error(f"Error checking disk space: {e}")

def delete_oldest_files():
    try:
        files = sorted([f for f in os.listdir(config['filesystem']['storage_path']) if f.endswith('.h264')])
        if not files:
            return
        for f in files:
            file_path = os.path.join(config['filesystem']['storage_path'], f)
            if os.path.exists(file_path):
                os.remove(file_path)
                logging.info(f"Deleted oldest file: {f}")
                return
    except Exception as e:
        logging.error(f"Error deleting files: {e}")

# --- Light Sensor Functions ---
def initialize_light_sensor():
    global bus
    try:
        bus = smbus2.SMBus(1)
        bus.read_byte_data(0x23, 0x00)
        logging.info("Light sensor initialized successfully.")
        return True
    except Exception as e:
        logging.error(f"Error initializing light sensor: {e}")
        return False

def read_light_sensor():
    try:
        bus.write_byte_data(0x23, 0x01, 0x00)
        time.sleep(0.18)
        data = bus.read_i2c_block_data(0x23, 0x00, 2)
        light_level = (data[1] + (256 * data[0])) / 1.2
        return light_level
    except Exception as e:
        logging.error(f"Error reading light sensor: {e}")
        return None

# --- GPIO Setup ---
def setup_gpio():
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(17, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        logging.info("GPIO setup complete.")
    except Exception as e:
        logging.error(f"Error setting up GPIO: {e}")

def cleanup_gpio():
    try:
        GPIO.cleanup()
        logging.info("GPIO cleaned up.")
    except Exception as e:
        logging.error(f"Error cleaning up GPIO: {e}")

# --- Main Program ---
def main():
    global running, last_frame, circular_buffer

    load_config()
    setup_gpio()

    if not initialize_camera():
        logging.critical("Failed to initialize camera. Exiting.")
        return

    if not initialize_light_sensor():
        logging.warning("Failed to initialize light sensor. Continuing without light sensor.")

    try:
        while running:
            check_disk_space_limit()

            frame = capture_low_resolution_frame()
            if frame is None:
                time.sleep(0.1)
                continue

            if last_frame is not None:
                avg_diff = calculate_average_pixel_difference(last_frame, frame)
                pct_changed = calculate_percentage_changed(last_frame, frame)

                motion_threshold = int(config['motion_detection']['motion_threshold'])
                motion_sensitivity = int(config['motion_detection']['motion_sensitivity'])

                if avg_diff > motion_threshold and pct_changed > motion_sensitivity:
                    logging.info("Motion detected!")
                    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
                    filename = os.path.join(config['filesystem']['storage_path'], f"{config['camera_id']}_{timestamp}.h264")
                    record_video(filename)

                    start_time = time.time()
                    while time.time() - start_time < int(config['recording']['recording_duration']):
                        check_disk_space_limit()
                        time.sleep(0.1)

                    while time.time() - start_time < int(config['recording']['recording_duration']) + 3:
                        check_disk_space_limit()
                        time.sleep(0.1)

                    circular_buffer = []
                    last_frame = frame
                    continue

            last_frame = frame
            time.sleep(float(config['motion_detection']['debounce_time']))

    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        if picam2:
            try:
                picam2.stop()
                picam2.close()
            except Exception as e:
                logging.error(f"Error closing camera: {e}")
        if bus:
            try:
                bus.close()
            except Exception as e:
                logging.error(f"Error closing I2C bus: {e}")
        cleanup_gpio()
        logging.info("Program finished.")

if __name__ == "__main__":
    main()

