OUTPUT_PINS = [23, 24]
POLL_INTERVAL = 0.05

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _cleanup():
    try:
        GPIO.cleanup()
    except Exception:
        pass

def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
    except Exception as e:
        print(f"Error: Failed to set GPIO mode: {e}")
        sys.exit(1)

    try:
        for pin in INPUT_PINS + OUTPUT_PINS:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    except Exception as e:
        print(f"Error: Failed to setup GPIO pins: {e}")
        _cleanup()
        sys.exit(1)

    output_state = False

    try:
        while _running:
            try:
                gpio4 = GPIO.input(4)
                gpio5 = GPIO.input(5)
                gpio6 = GPIO.input(6)
            except Exception as e:
                print(f"Warning: GPIO read error: {e}")
                time.sleep(POLL_INTERVAL)
                continue

            try:
                if gpio4 == GPIO.LOW:
                    GPIO.output(23, GPIO.HIGH)
                    GPIO.output(23, GPIO.LOW)
                elif gpio5 == GPIO.LOW:
