#!/usr/bin/env python3
"""CSI camera motion/temperature monitor for Raspberry Pi.

Reads config.txt, captures frames at 64x48 RGB888, compares consecutive
frames for motion in a configurable ROI, and raises alerts when motion
or CPU temperature exceeds thresholds.
"""

import os
import sys
import time
import signal
import logging
import datetime
import configparser
from pathlib import Path

import numpy as np

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

try:
    import psutil
except ImportError:
    psutil = None

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
log = logging.getLogger("csi_monitor")

# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
_running = True
_snapshot_dir = None
_config = None
_picam2 = None


def _signal_handler(signum, frame):
    global _running
    log.info("Signal %s received – shutting down …", signum)
    _running = False


def _load_config(path: str) -> configparser.ConfigParser:
    """Load and validate config.txt; return None on fatal error."""
    cfg = configparser.ConfigParser()
    try:
        if not os.path.isfile(path):
            log.error("Config file not found: %s", path)
            return None
        cfg.read(path)
    except configparser.Error as exc:
        log.error("Error parsing config file: %s", exc)
        return None

    required = ["Camera", "Snapshot", "Alerts"]
    for section in required:
        if section not in cfg:
            log.error("Missing section [%s] in config file", section)
            return None

    try:
        roi = cfg["Camera"]["roi_x1 roi_y1 roi_x2 roi_y2"].split()
        if len(roi) != 4:
            raise ValueError("ROI must have exactly 4 values")
        roi_x1, roi_y1, roi_x2, roi_y2 = [int(v) for v in roi]
        if not (0 <= roi_x1 < roi_x2 and 0 <= roi_y1 < roi_y2):
            raise ValueError("ROI coordinates must form a valid rectangle")
    except (ValueError, KeyError) as exc:
        log.error("Invalid ROI in config: %s", exc)
        return None

    try:
        motion_threshold = float(cfg["Alerts"]["motion_threshold"])
    except (ValueError, KeyError):
        log.error("Invalid motion_threshold in config")
        return None

    try:
        temperature_threshold = float(cfg["Alerts"]["temperature_threshold"])
    except (ValueError, KeyError):
        log.error("Invalid temperature_threshold in config")
        return None

    try:
        confirmation_delay = float(cfg["Alerts"]["confirmation_delay"])
    except (ValueError, KeyError):
        log.error("Invalid confirmation_delay in config")
        return None

    try:
        simulated_temperature = cfg["Alerts"].getboolean("simulated_temperature")
    except (ValueError, KeyError):
        log.error("Invalid simulated_temperature in config")
        return None

    return cfg


def _init_camera() -> Picamera2 | None:
    """Initialise the CSI camera; return None on failure."""
    if Picamera2 is None:
        log.error("picamera2 library not installed")
        return None
    try:
        cam = Picamera2()
        # 64x48 RGB888 is the documented resolution for the CSI camera module.
        config = cam.create_preview_configuration(
            main={"size": (64, 48), "format": "RGB888"}
        )
        cam.configure(config)
        cam.start()
        time.sleep(2)  # warm-up
        log.info("CSI camera initialised at 64x48 RGB888")
        return cam
    except Exception as exc:
        log.error("Failed to initialise CSI camera: %s", exc)
        return None


def _capture_frame(cam: Picamera2) -> np.ndarray | None:
    """Capture a single RGB888 frame; return None on failure."""
    try:
        return cam.capture_array("main")
    except Exception as exc:
        log.error("Frame capture failed: %s", exc)
        return None


def _save_snapshot(frame: np.ndarray, path: str) -> bool:
    """Save *frame* as a snapshot file; return True on success."""
    try:
        os.makedirs(_snapshot_dir, exist_ok=True)
        filename = os.path.join(_snapshot_dir, f"snapshot_{datetime.datetime.now().strftime('%Y%m%d_%H%M%S')}.jpg")
        # picamera2 RGB888 frames are already BGR in memory; convert to JPEG.
        from PIL import Image
        img = Image.fromarray(frame, mode="RGB")
        img.save(filename, format="JPEG")
        log.info("Snapshot saved: %s", filename)
        return True
    except Exception as exc:
        log.error("Failed to save snapshot: %s", exc)
        return False


def _check_temperature(simulated: bool) -> float:
    """Return CPU temperature in °C, or simulated value."""
    if simulated:
        return 40.0
    if psutil is None:
        log.error("psutil not installed – using simulated temperature")
        return 40.0
    try:
        return psutil.sensors_temperatures()["cpu_thermal"][0].current
    except Exception as exc:
        log.error("Could not read CPU temperature: %s", exc)
        return 40.0


def _motion_detected(frame1: np.ndarray, frame2: np.ndarray, roi_x1, roi_y1, roi_x2, roi_y2, threshold: float) -> bool:
    """Return True if more than threshold % of ROI pixels differ."""
    if frame1 is None or frame2 is None:
        return False
    if frame1.shape != frame2.shape:
        log.error("Frame shape mismatch: %s vs %s", frame1.shape, frame2.shape)
        return False
    roi1 = frame1[roi_y1:roi_y2, roi_x1:roi_x2]
    roi2 = frame2[roi_y1:roi_y2, roi_x1:roi_x2]
    diff = np.abs(roi1.astype(np.int16) - roi2.astype(np.int16))
    changed = np.count_nonzero(diff > 128)
    total = roi1.size
    return changed > total * threshold


def main() -> int:
    global _snapshot_dir, _config, _picam2

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _config = _load_config("config.txt")
    if _config is None:
        return 1

    _snapshot_dir = _config["Snapshot"]["snapshot_dir"]
    if not _snapshot_dir:
        log.error("snapshot_dir not configured")
        return 1

    _picam2 = _init_camera()
    if _picam2 is None:
        return 1

    try:
        while _running:
            frame1 = _capture_frame(_picam2)
            if frame1 is None:
                time.sleep(1)
                continue

            time.sleep(0.1)
            frame2 = _capture_frame(_picam2)
            if frame2 is None:
                time.sleep(1)
                continue

            motion = _motion_detected(
                frame1, frame2,
                int(_config["Camera"]["roi_x1"]),
                int(_config["Camera"]["roi_y1"]),
                int(_config["Camera"]["roi_x2"]),
                int(_config["Camera"]["roi_y2"]),
                float(_config["Alerts"]["motion_threshold"]),
            )

            if motion:
                log.info("Motion detected in ROI")
                time.sleep(float(_config["Alerts"]["confirmation_delay"]))
                frame3 = _capture_frame(_picam2)
                if frame3 is None:
                    continue
                if _motion_detected(frame2, frame3, *motion_args, float(_config["Alerts"]["motion_threshold"])):
                    log.warning("Motion confirmed – raising alert")
                    _save_snapshot(frame3, _snapshot_dir)
                else:
                    log.info("Motion false positive")
            else:
                temp = _check_temperature(_config["Alerts"].getboolean("simulated_temperature"))
                if temp > float(_config["Alerts"]["temperature_threshold"]):
                    log.warning("Temperature alert: %.1f °C", temp)
                    _save_snapshot(frame1, _snapshot_dir)

            time.sleep(1)
    finally:
        if _picam2 is not None:
            try:
                _picam2.stop()
            except Exception:
                pass
        log.info("CSI monitor stopped")

    return 0


if __name__ == "__main__":
    sys.exit(main())

