import os
import sys
import time
import signal
import select
import logging
import threading

import cv2
import numpy as np
import config
import face
import audio
from gpiozero import Button, OutputDevice

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class DoorController:
    """Controls door access based on face recognition."""

    def __init__(self, camera_factory=None):
        self.camera = None
        self.lock = None
        self.button = None
        self.audio_player = None
        self._running = True
        self._lock = threading.Lock()

        if camera_factory is None:
            camera_factory = config.default_camera_factory

        try:
            self.camera = camera_factory()
        except Exception as e:
            logger.error(f"Failed to initialize camera: {e}")
            raise

        try:
            self.lock = OutputDevice(config.DoorLockPin, active_high=True, initial_value=False)
        except Exception as e:
            logger.error(f"Failed to initialize lock GPIO: {e}")
            self._cleanup()
            raise

        try:
            self.button = Button(config.ButtonPin, pull_up=True, bounce_time=0.05)
        except Exception as e:
            logger.error(f"Failed to initialize button GPIO: {e}")
            self._cleanup()
            raise

        try:
            self.audio_player = audio.AudioPlayer(
                config.AudioFrequency, config.AudioSize, config.AudioChannels, config.AudioBuffer
            )
        except Exception as e:
            logger.error(f"Failed to initialize audio: {e}")
            self._cleanup()
            raise

        self._load_model()

    def _load_model(self):
        if not os.path.exists(config.TRAINING_FILE):
            logger.error(f"Training file not found: {config.TRAINING_FILE}")
            self._cleanup()
            sys.exit(1)
        try:
            self.face_model = cv2.face.EigenFaceRecognizer_create()
            self.face_model.read(config.TRAINING_FILE)
        except Exception as e:
            logger.error(f"Failed to load face recognition model: {e}")
            self._cleanup()
            sys.exit(1)

    def _cleanup(self):
        if self.camera:
            try:
                self.camera.close()
            except Exception:
                pass
            self.camera = None
        if self.lock:
            try:
                self.lock.close()
            except Exception:
                pass
            self.lock = None
        if self.button:
            try:
                self.button.close()
            except Exception:
                pass
            self.button = None
        if self.audio_player:
            try:
                self.audio_player.quit()
            except Exception:
                pass
            self.audio_player = None

    def _signal_handler(self, signum, frame):
        logger.info(f"Signal {signum} received, shutting down...")
        self._running = False

    def run(self):
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)

        try:
            while self._running:
                if self._should_lock():
                    self.lock_door()
                else:
                    self.unlock_door()
                time.sleep(config.PollingTime)
        except Exception as e:
            logger.exception(f"An unexpected error occurred: {e}")
        finally:
            self._cleanup()

    def _should_lock(self):
        try:
            if self.button.is_pressed:
                return True
            return False
        except Exception as e:
            logger.error(f"Error reading button: {e}")
            return True

    def _capture_image(self):
        try:
            image = self.camera.read()
            if image is None:
                raise RuntimeError("Camera returned None")
            if image.size == 0:
                raise RuntimeError("Captured image is empty")
            return cv2.cvtColor(image, cv2.COLOR_RGB2GRAY)
        except Exception as e:
            logger.error(f"Error capturing image: {e}")
            return None

    def recognize_face(self, image):
        try:
            face_coords = face.detect_single(image)
            if face_coords is None:
                return None, 1.0
            x, y, w, h = face_coords
            cropped = face.crop(image, x, y, w, h)
            resized = face.resize(cropped)
            label, confidence = self.face_model.predict(resized)
            return label, confidence
        except Exception as e:
            logger.error(f"Error during face recognition: {e}")
            return None, 1.0

    def _play_sound(self, channel, sound_file):
        try:
            self.audio_player.play_sound(channel, sound_file)
        except Exception as e:
            logger.error(f"Error playing sound: {e}")

    def lock_door(self):
        try:
            self.lock.on()
            logger.info("Door locked.")
            self._play_sound(config.AudioChannelWait, config.WaitSound)
        except Exception as e:
            logger.error(f"Error locking door: {e}")

    def unlock_door(self):
        try:
            self.lock.off()
            logger.info("Door unlocked.")
            self._play_sound(config.AudioChannelWelcome, config.WelcomeSound)
        except Exception as e:
            logger.error(f"Error unlocking door: {e}")

    def _is_letter_input(self, letter):
        try:
            rlist, _, _ = select.select([sys.stdin], [], [], 0.0)
            if rlist:
                input_char = sys.stdin.read(1)
                return input_char.lower() == letter.lower()
            return False
        except Exception as e:
            logger.error(f"Error checking input: {e}")
            return False

    def input_command(self):
        try:
            if self._is_letter_input('l'):
                logger.info("Manually locking door...")
                self.lock_door()
                return True
            return False
        except Exception as e:
            logger.error(f"Error processing input command: {e}")
            return False


if __name__ == "__main__":
    try:
        door_controller = DoorController()
        door_controller.run()
    except Exception as e:
        logger.exception(f"Fatal error: {e}")
        sys.exit(1)

