import time
import datetime
import logging
import logging.handlers
import json
import threading
import signal
import sys
import numpy as np
from PIL import Image
import smbus2
import matplotlib.pyplot as plt

CONFIG_FILE = "config.json"
DEFAULT_CONFIG = {
    "sampling_rate": 5,
    "motion_detection_threshold": 1.0,
    "logging_file_path": "beehive.log",
    "log_max_size": 1048576,
    "enable_camera": False
}

config = DEFAULT_CONFIG.copy()
config_lock = threading.Lock()

# Global state
running = True
thermal_data = None
circular_buffer = None
bus = None
camera = None
background_thread = None


def load_config():
    global config
    try:
        with open(CONFIG_FILE, "r") as f:
            loaded = json.load(f)
        with config_lock:
            config = {**DEFAULT_CONFIG, **loaded}
        logging.info(f"Configuration loaded from {CONFIG_FILE}")
    except FileNotFoundError:
        logging.warning(f"Configuration file {CONFIG_FILE} not found. Using defaults.")
    except json.JSONDecodeError as e:
        logging.error(f"Error decoding JSON from {CONFIG_FILE}: {e}. Using defaults.")
    except Exception as e:
        logging.error(f"Unexpected error loading config: {e}. Using defaults.")


def initialize_thermal_camera():
    global bus
    max_attempts = 3
    for attempt in range(1, max_attempts + 1):
        try:
            bus = smbus2.SMBus(1)
            time.sleep(0.1)
            # AMG8833: write 0x00 to register 0x00 to wake up
            bus.write_byte_data(0x5A, 0x00, 0x00)
            time.sleep(0.1)
            # Read calibration data (registers 0x01-0x0F)
            cal = bus.read_i2c_block_data(0x5A, 0x01, 16)
            # Verify calibration data (placeholder: in real use, verify checksum)
            logging.info("AMG8833 initialized successfully.")
            return True
        except Exception as e:
            logging.error(f"Failed to initialize AMG8833 (attempt {attempt}/{max_attempts}): {e}")
            if attempt < max_attempts:
                time.sleep(2)
            else:
                logging.critical("Failed to initialize AMG8833 after multiple attempts. Exiting.")
                return False
    return False


def read_thermal_data():
    global thermal_data
    try:
        pixels = []
        for row in range(8):
            data = bus.read_i2c_block_data(0x5A, 0x10 + row * 16, 16)
            for col in range(8):
                pixel = (data[col * 2] << 8 | data[col * 2 + 1]) >> 4
                pixels.append(pixel)
        thermal_data = np.array(pixels).reshape((8, 8))
        return thermal_data
    except Exception as e:
        logging.error(f"Error reading thermal data: {e}")
        return None


def visualize_thermal_data(frame):
    try:
        plt.clf()
        plt.imshow(frame, cmap='jet', interpolation='nearest')
        plt.colorbar(label='Temperature (°C)')
        plt.title(f"Thermal Camera - {datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
        plt.pause(0.001)
    except Exception as e:
        logging.error(f"Error visualizing thermal data: {e}")


def detect_motion(current_frame, previous_frame, threshold):
    try:
        if previous_frame is None:
            return False
        diff = np.abs(current_frame - previous_frame)
        avg_diff = np.mean(diff)
        return avg_diff > threshold
    except Exception as e:
        logging.error(f"Error detecting motion: {e}")
        return False


def capture_image():
    global camera
    try:
        if camera is None:
            logging.warning("Camera not enabled or not available. Skipping image capture.")
            return
        image = camera.capture_image()
        image.save("image.jpg")
        logging.info("Image captured and saved as image.jpg")
    except Exception as e:
        logging.error(f"Error capturing image: {e}")


def log_data(timestamp, thermal_data, motion_detected):
    try:
        log_message = f"{timestamp}, {thermal_data}, {motion_detected}\n"
        logging.info(log_message)
    except Exception as e:
        logging.error(f"Error logging data: {e}")


def rotate_log_file():
    try:
        handler = logging.handlers.RotatingFileHandler(
            config["logging_file_path"],
            maxBytes=config["log_max_size"],
            backupCount=1
        )
        handler.setFormatter(logging.Formatter('%(asctime)s - %(levelname)s - %(message)s'))
        logging.getLogger().removeHandler(logging.getLogger().handlers[0])
        logging.getLogger().addHandler(handler)
        logging.info("Log file rotated.")
    except Exception as e:
        logging.error(f"Error rotating log file: {e}")


def signal_handler(sig, frame):
    global running
    logging.info(f"Received signal {sig}. Shutting down...")
    running = False


def background_loop():
    global running, thermal_data, circular_buffer, camera
    previous_frame = None
    while running:
        try:
            thermal_data = read_thermal_data()
            if thermal_data is not None:
                if circular_buffer is not None:
                    circular_buffer.append(thermal_data)
                    if len(circular_buffer) > 300:
                        circular_buffer.pop(0)
                visualize_thermal_data(thermal_data)
                motion = detect_motion(thermal_data, previous_frame, config["motion_detection_threshold"])
                log_data(datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"), thermal_data, motion)
                previous_frame = thermal_data
                if config["enable_camera"]:
                    capture_image()
                rotate_log_file()
            time.sleep(1.0 / config["sampling_rate"])
        except Exception as e:
            logging.error(f"Error in background loop: {e}")
            time.sleep(1)


def cleanup():
    global running, camera, bus
    running = False
    if background_thread is not None:
        background_thread.join(timeout=2)
    if camera is not None:
        try:
            camera.close()
            logging.info("Camera closed.")
        except Exception as e:
            logging.error(f"Error closing camera: {e}")
    if bus is not None:
        try:
            bus.close()
            logging.info("I2C bus closed.")
        except Exception as e:
            logging.error(f"Error closing I2C bus: {e}")
    logging.info("Program finished.")


if __name__ == "__main__":
    load_config()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    if not initialize_thermal_camera():
        sys.exit(1)
    global circular_buffer
    circular_buffer = []
    background_thread = threading.Thread(target=background_loop, daemon=True)
    background_thread.start()
    try:
        while running:
            time.sleep(1)
    except KeyboardInterrupt:
        pass
    finally:
        cleanup()

