import time
import signal
import threading
import subprocess
import logging
from gpiozero import LED, OutputDevice
from gpiozero.exc import GPIOZeroError

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

LCD_I2C_ADDR = 0x3F
I2C_BUS = 1
LCD_WIDTH = 16
LCD_CHR = 1
LCD_CMD = 0
LCD_LINE_1 = 0x80
LCD_LINE_2 = 0xC0
LCD_BACKLIGHT = 0x08
ENABLE = 0x04
E_PULSE = 0.0005
E_DELAY = 0.0005

led_pins = [17, 18, 23, 27, 22]
leds = []
lcd = None
running = True


def lcd_byte(bits, mode):
    global lcd
    if lcd is None:
        return
    bits_high = mode | (bits & 0xF0) | LCD_BACKLIGHT
    bits_low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT
    lcd.write_byte(bits_high, LCD_CHR)
    lcd.write_byte(bits_low, LCD_CHR)
    time.sleep(E_DELAY)
    lcd.write_byte(bits_high, LCD_CMD)
    lcd.write_byte(bits_low, LCD_CMD)
    time.sleep(E_DELAY)


def lcd_init():
    global lcd
    try:
        from smbus2 import SMBus
        bus = SMBus(I2C_BUS)
        lcd = bus
        lcd_byte(0x33, LCD_CMD)
        lcd_byte(0x32, LCD_CMD)
        lcd_byte(0x06, LCD_CMD)
        lcd_byte(0x0C, LCD_CMD)
        lcd_byte(0x28, LCD_CMD)
        lcd_byte(0x01, LCD_CMD)
        time.sleep(E_DELAY)
    except Exception as e:
        logging.error(f"LCD init failed: {e}")
        lcd = None


def lcd_string(message, line):
    message = message.ljust(LCD_WIDTH)[:LCD_WIDTH]
    lcd_byte(line, LCD_CMD)
    for char in message:
        lcd_byte(ord(char), LCD_CHR)


def get_cpu_stats():
    try:
        output = subprocess.check_output(['cat', '/proc/cpuinfo'], text=True, timeout=5).splitlines()
        for line in output:
            if line.startswith('model name'):
                return line.split(':')[1].strip()
        return 'Unknown'
    except Exception as e:
        logging.error(f"Error reading CPU model: {e}")
        return 'Error'


def get_cpu_temp():
    try:
        output = subprocess.check_output(['cat', '/sys/class/thermal/thermal_zone0/temp'], text=True, timeout=5)
        return float(output.strip()) / 1000.0
    except Exception as e:
        logging.error(f"Error reading CPU temperature: {e}")
        return 0.0


def led_task(cls):
    global running
    if not running:
        return
    try:
        led = leds[cls]
        led.on()
        time.sleep(1)
        led.off()
    except Exception as e:
        logging.error(f"Error in LED task: {e}")


def display_stats():
    global running
    while running:
        try:
            cpu_usage = subprocess.check_output(['top', '-bn1', '-c'], text=True, timeout=5).splitlines()[1]
            cpu_usage = cpu_usage.split()[1]
            cpu_temp = get_cpu_temp()
            cpu_model = get_cpu_stats()
            lcd_string(f"CPU: {cpu_usage}%", LCD_LINE_1)
            lcd_string(f"Temp: {cpu_temp:.1f}C", LCD_LINE_2)
        except Exception as e:
            logging.error(f"Error in display_stats: {e}")
        time.sleep(1)


def signal_handler(sig, frame):
    global running
    running = False


def main():
    global leds
    signal.signal(signal.SIGINT, signal_handler)
    try:
        for pin in led_pins:
            leds.append(LED(pin))
    except GPIOZeroError as e:
        logging.error(f"GPIO setup failed: {e}")
        return
    lcd_init()
    if lcd is None:
        for led in leds:
            led.close()
        return
    stats_thread = threading.Thread(target=display_stats, daemon=True)
    stats_thread.start()
    try:
        while running:
            for i in range(5):
                if not running:
                    break
                led_task(i)
                time.sleep(1)
    except Exception as e:
        logging.error(f"Main loop error: {e}")
    finally:
        running = False
        time.sleep(0.5)
        if lcd is not None:
