#!/usr/bin/env python3
"""Greenhouse controller: DHT22 + LCD + servo vent angle control.

Wiring (BCM):
  DHT22 data  -> GPIO4  (4.7k-10k pull-up to 3V3)
  LCD RS      -> GPIO25
  LCD E       -> GPIO24
  LCD D4      -> GPIO23
  LCD D5      -> GPIO17
  LCD D6      -> GPIO18
  LCD D7      -> GPIO22
  Servo       -> GPIO12
"""

import configparser
import logging
import signal
import sys
import time
from datetime import datetime

import RPi.GPIO as GPIO

try:
    import adafruit_dht
    import board
except ImportError:
    adafruit_dht = None
    board = None

try:
    from lib.oop.vent import vent
except ImportError:
    vent = None

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
CONFIG_FILE = "greenhouse.conf"
LOG_FILE = "greenhouse.log"

DEFAULT_CONFIG = {
    "logging": {
        "level": "INFO",
    },
    "ventilation": {
        "temp_low": "15",
        "temp_mid": "25",
    },
}

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def load_config(config_file):
    config = configparser.ConfigParser()
    config.read_dict(DEFAULT_CONFIG)
    try:
        with open(config_file, "r") as f:
            config.read_file(f)
    except FileNotFoundError:
        logging.warning("Configuration file not found; using defaults.")
    except OSError as exc:
        logging.error("Error reading configuration file: %s", exc)
    return config


def setup_logging(log_file, level_str):
    level = getattr(logging, level_str.upper(), logging.INFO)
    logging.basicConfig(
        filename=log_file,
        level=level,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )
    logging.info("Logging level set to %s", level_str)


# ---------------------------------------------------------------------------
# Hardware helpers
# ---------------------------------------------------------------------------
def init_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)


def init_lcd():
    pins = [25, 24, 23, 17, 18, 22]
    for pin in pins:
        GPIO.setup(pin, GPIO.OUT)
        GPIO.output(pin, GPIO.LOW)
    time.sleep(0.05)
    _lcd_pulse_enable(1)
    _lcd_write_nibble(0x03)
    time.sleep(0.005)
    _lcd_write_nibble(0x03)
    time.sleep(0.001)
    _lcd_write_nibble(0x03)
    time.sleep(0.001)
    _lcd_write_nibble(0x02)
    time.sleep(0.001)
    logging.info("LCD initialised (4-bit mode).")


def _lcd_pulse_enable(state):
    GPIO.output(24, state)


def _lcd_write_nibble(nibble):
    GPIO.output(25, 0)
    for bit in range(4):
        GPIO.output(23 + bit, (nibble >> bit) & 1)
    _lcd_pulse_enable(1)
    for bit in range(4):
        GPIO.output(23 + bit, 0)
    _lcd_pulse_enable(0)


def _lcd_write_byte(byte, is_data):
    GPIO.output(25, is_data)
    for bit in range(8):
        GPIO.output(23 + bit, (byte >> bit) & 1)
    _lcd_pulse_enable(1)
    for bit in range(8):
        GPIO.output(23 + bit, 0)
    _lcd_pulse_enable(0)


def lcd_clear():
    for _ in range(16):
        _lcd_write_byte(0x00, 0)
        _lcd_write_byte(0x01, 0)
        time.sleep(0.001)


def lcd_set_cursor(row, col):
    addr = 0x80 + (0x40 if row == 1 else 0x00) + col
    _lcd_write_byte(addr, 0)


def lcd_write_string(text):
    for char in text:
        _lcd_write_byte(ord(char), 1)


def lcd_display(text1, text2):
    lcd_clear()
    lcd_set_cursor(0, 0)
    lcd_write_string(text1[:16])
    lcd_set_cursor(1, 0)
    lcd_write_string(text2[:16])


def init_dht22():
    if adafruit_dht is None or board is None:
        logging.error("adafruit_dht or board not installed.")
        return None
    try:
        sensor = adafruit_dht.DHT22(board.D4, use_pulseio=False)
        logging.info("DHT22 sensor initialised on GPIO4.")
        return sensor
    except Exception as exc:
        logging.error("Failed to initialise DHT22: %s", exc)
        return None


def init_vent():
    if vent is None:
        logging.error("vent library not installed.")
        return None
    try:
        vent_instance = vent()
        logging.info("Vent API initialised.")
        return vent_instance
    except Exception as exc:
        logging.error("Failed to initialise vent API: %s", exc)
        return None


def read_dht22(sensor):
    if sensor is None:
        return None, None
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        if temperature is None or humidity is None:
            raise RuntimeError("Sensor returned None")
        return temperature, humidity
    except Exception as exc:
        logging.error("Error reading DHT22: %s", exc)
        return None, None


def display_data(temperature, humidity, vent_angle):
    if temperature is None or humidity is None:
        temp_str = "--"
        hum_str = "--"
    else:
        temp_str = f"{temperature:.1f}C"
        hum_str = f"{humidity:.1f}%"
    lcd_display(temp_str, f"Vent: {vent_angle}")


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    init_gpio()

    config = load_config(CONFIG_FILE)
    setup_logging(LOG_FILE, config.get("logging", "level", fallback="INFO"))

    lcd_pin = config.getint("lcd", "rs", fallback=25)
    e_pin = config.getint("lcd", "e", fallback=24)
    d4_pin = config.getint("lcd", "d4", fallback=23)
    d5_pin = config.getint("lcd", "d5", fallback=17)
    d6_pin = config.getint("lcd", "d6", fallback=18)
    d7_pin = config.getint("lcd", "d7", fallback=22)
    servo_pin = config.getint("servo", "pin", fallback=12)

    lcd_pins = [lcd_pin, e_pin, d4_pin, d5_pin, d6_pin, d7_pin]
    for pin in lcd_pins:
        GPIO.setup(pin, GPIO.OUT)
        GPIO.output(pin, GPIO.LOW)
    GPIO.setup(servo_pin, GPIO.OUT)
    GPIO.output(servo_pin, GPIO.LOW)

    try:
        init_lcd()
    except Exception as exc:
        logging.error("LCD init failed: %s", exc)
        GPIO.cleanup()
        return

    sensor = init_dht22()
    vent_instance = init_vent()

    if sensor is None and vent_instance is None:
        logging.error("No hardware initialised. Exiting.")
        GPIO.cleanup()
        return

    last_temp = None
    last_hum = None

    try:
        while _running:
            temperature, humidity = read_dht22(sensor)

            if temperature is not None and humidity is not None:
                last_temp = temperature
                last_hum = humidity
            else:
                temperature = last_temp
                humidity = last_hum

            if temperature is not None and humidity is not None:
                try:
                    vent_angle = vent_instance.vent(temperature, config)
                except Exception as exc:
                    logging.error("Error calling vent API: %s", exc)
                    vent_angle = "--"
            else:
                vent_angle = "--"

            display_data(temperature, humidity, vent_angle)

            if temperature is not None and humidity is not None:
                logging.info(
                    "Temp: %.1fC, Hum: %.1f%%, Vent: %s",
                    temperature, humidity, vent_angle
                )
            else:
                logging.warning(
                    "Sensor read failed; using last good values. Temp: %s, Hum: %s, Vent: %s",
                    last_temp, last_hum, vent_angle
                )

            for _ in range(5):
                if not _running:
                    break
                time.sleep(1)

    except Exception as exc:
        logging.error("Unexpected error in main loop: %s", exc)
    finally:
        try:
            lcd_clear()
        except Exception:
            pass
        try:
            if vent_instance is not None:
                vent_instance.release()
        except Exception:
            pass
        try:
            if sensor is not None:
                sensor.exit()
        except Exception:
            pass
        GPIO.cleanup()
        logging.info("Program finished.")


if __name__ == "__main__":
    main()

