        """Runs the GIF player loop."""
        self._load_gif_files()

        if not self.gif_files:
            print("No GIF files to play. Exiting.")
            return

        try:
            while self.running:
                self.play()
                if not self.running:
                    break
                time.sleep(0.1)
        finally:
            self.cleanup()

    def cleanup(self) -> None:
        """Releases resources and cleans up the display."""
        print("Cleaning up resources...")
        try:
            if self.display is not None:
