import RPi.GPIO as GPIO
import time
import sys

TRIGGER_PIN = 23
ECHO_PIN = 24
LED_PIN = 18
DISTANCE_THRESHOLD = 10.0  # cm
MEASUREMENT_DELAY = 1.0     # seconds
ECHO_TIMEOUT = 0.05         # seconds (50 ms max echo wait)
TRIGGER_PULSE = 0.00001     # 10 microseconds

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(TRIGGER_PIN, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(ECHO_PIN, GPIO.IN)
    GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)

def measure_distance():
    """Return distance in cm, or None on timeout/error."""
    GPIO.output(TRIGGER_PIN, GPIO.HIGH)
    time.sleep(TRIGGER_PULSE)
    GPIO.output(TRIGGER_PIN, GPIO.LOW)

    deadline = time.time() + ECHO_TIMEOUT
    while GPIO.input(ECHO_PIN) == 0:
        if time.time() > deadline:
            return None
    pulse_start = time.time()

    deadline = time.time() + ECHO_TIMEOUT
    while GPIO.input(ECHO_PIN) == 1:
        if time.time() > deadline:
            return None
    pulse_end = time.time()

    pulse_duration = pulse_end - pulse_start
    speed_of_sound = 34300.0  # cm/s
    distance = (pulse_duration * speed_of_sound) / 2.0
    return round(distance, 2)

def cleanup_gpio():
    GPIO.cleanup()

def main():
    try:
        setup_gpio()
        print("Ultrasonic distance monitor started. Press Ctrl+C to exit.")
        while True:
            distance = measure_distance()
            if distance is None:
                print("Error: Sensor timeout or no echo received.")
                GPIO.output(LED_PIN, GPIO.LOW)
            else:
                print(f"Distance: {distance} cm")
                if distance < DISTANCE_THRESHOLD:
                    GPIO.output(LED_PIN, GPIO.HIGH)
                else:
                    GPIO.output(LED_PIN, GPIO.LOW)
            time.sleep(MEASUREMENT_DELAY)
    except KeyboardInterrupt:
        print("\nExiting program.")
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

