import json
import random
import time
import logging
import threading
import paho.mqtt.client as mqtt

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

MQTT_BROKER = "test.mosquitto.org"
MQTT_PORT = 1883
MQTT_TOPIC = "classroom/temperature"
KEEPALIVE = 60
NUM_READINGS = 5
MAX_RETRIES = 3
RETRY_DELAY = 2

shutdown_event = threading.Event()


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        logger.info("Connected to MQTT broker successfully")
    else:
        logger.error(f"Failed to connect to MQTT broker, reason code: {reason_code}")


def on_publish(client, userdata, mid, reason_code, properties):
    logger.debug(f"Message {mid} published successfully")


def connect_with_retry(client):
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            client.connect(MQTT_BROKER, MQTT_PORT, KEEPALIVE)
            return True
        except Exception as e:
            logger.warning(f"Connection attempt {attempt}/{MAX_RETRIES} failed: {e}")
            if attempt < MAX_RETRIES:
                shutdown_event.wait(RETRY_DELAY)
    return False


def main():
    client = mqtt.Client(mqtt.CallbackAPIVersion.VERSION2)
    client.on_connect = on_connect
    client.on_publish = on_publish

    if not connect_with_retry(client):
        logger.error("Exceeded maximum connection retries. Exiting.")
        return

    client.loop_start()

    try:
        for i in range(NUM_READINGS):
            if shutdown_event.is_set():
                logger.info("Shutdown event triggered. Stopping publishing.")
                break

            temperature = round(random.uniform(19.00, 26.00), 2)
            payload = json.dumps({"temperature": temperature, "index": i})

            try:
                info = client.publish(MQTT_TOPIC, payload, qos=0)
                info.wait_for_publish(timeout=10)
            except Exception as e:
                logger.error(f"Failed to publish message {i}: {e}")
                continue

            if info.rc != mqtt.MQTT_ERR_SUCCESS:
                logger.error(f"Publish returned error code: {info.rc}")

            logger.info(f"Published: {payload}")

            if i < NUM_READINGS - 1:
                shutdown_event.wait(1)

        if shutdown_event.is_set():
            logger.info("Shutdown event triggered before completion.")
        else:
            logger.info(f"Total messages published: {NUM_READINGS}")

    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")
    finally:
        client.loop_stop()
        client.disconnect()
        logger.info("Disconnected from MQTT broker.")


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        logger.info("Program interrupted by user.")
    finally:
        shutdown_event.set()
    exit(0 if shutdown_event.is_set() else 1)

