import signal
import sys
import time

import serial

PORT = '/dev/ttyUSB0'
BAUD = 115200
TIMEOUT = 1.0
READ_INTERVAL = 0.5

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_temperature(ser):
    """Read one line from the RS485 port and return the first float value."""
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Error: serial read failed: {exc}", file=sys.stderr)
        return None

    if not raw:
        return None

    text = raw.decode('ascii', errors='replace').strip()
    if not text:
        return None

    try:
        return float(text)
    except ValueError:
        print(f"Error: malformed data received: {text!r}", file=sys.stderr)
        return None

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(
            port=PORT,
            baudrate=BAUD,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f"Error: cannot open {PORT}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            temp = read_temperature(ser)
            if temp is not None:
                print(f"Temperature: {temp:.1f} C")
            time.sleep(READ_INTERVAL)
    finally:
        try:
            ser.close()
        except Exception:
            pass
        print("Serial port closed. Exiting.")

if __name__ == '__main__':
    main()

