import time
import logging
import signal
import smbus2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DHT20_I2C_ADDRESS = 0x76
DHT20_STATUS_REG = 0x00
DHT20_MEAS_REG = 0x01
DHT20_CRC_REG = 0x03
DHT20_MEAS_DELAY = 0.08
DHT20_POWER_STABILIZE_DELAY = 0.5
DHT20_MAX_RETRIES = 5
DHT20_RETRY_DELAY = 2.0
DHT20_TIMEOUT = 0.1
DHT20_STATUS_MASK = 0x80
DHT20_STATUS_EXPECTED = 0x80
DHT20_CRC_POLYNOMIAL = 0x31
DHT20_CRC_INIT = 0xFF
DHT20_CRC_MAX_POLYNOMIAL = 0x100


class DHT20:
    def __init__(self, i2c_bus_number=1):
        self.i2c_address = DHT20_I2C_ADDRESS
        self.i2c_bus = None
        try:
            self.i2c_bus = smbus2.SMBus(i2c_bus_number)
        except Exception as e:
            logging.error(f"Failed to initialize I2C bus {i2c_bus_number}: {e}")
            raise
        time.sleep(DHT20_POWER_STABILIZE_DELAY)
        try:
            status = self.i2c_bus.read_byte_data(self.i2c_address, DHT20_STATUS_REG)
            if (status & DHT20_STATUS_MASK) != DHT20_STATUS_EXPECTED:
                logging.error(f"DHT20 status mismatch: got 0x{status:02X}, expected 0x{DHT20_STATUS_EXPECTED:02X}")
                self.close()
                raise RuntimeError("DHT20 status check failed")
        except Exception as e:
            logging.error(f"Failed to read DHT20 status register: {e}")
            self.close()
            raise

    def close(self):
        if self.i2c_bus is not None:
            try:
                self.i2c_bus.close()
            except Exception:
                pass
            self.i2c_bus = None

    def __del__(self):
        self.close()

    def _calculate_crc8(self, data):
        crc = DHT20_CRC_INIT
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ DHT20_CRC_POLYNOMIAL) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def read(self):
        for attempt in range(DHT20_MAX_RETRIES):
            try:
                self.i2c_bus.write_byte_data(self.i2c_address, DHT20_MEAS_REG, 0x00)
                time.sleep(DHT20_MEAS_DELAY)
                for _ in range(100):
                    time.sleep(0.01)
                    status = self.i2c_bus.read_byte_data(self.i2c_address, DHT20_STATUS_REG)
                    if (status & DHT20_STATUS_MASK) == 0:
                        break
                    if time.time() - start_time > DHT20_TIMEOUT:
                        raise TimeoutError("DHT20 measurement timed out")
                data = self.i2c_bus.read_i2c_block_data(self.i2c_address, DHT20_STATUS_REG, 7)
                if len(data) != 7:
                    raise IOError(f"Unexpected data length: {len(data)}")
                humidity_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
                temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF
                received_crc = data[6]
                calculated_crc = self._calculate_crc8(data[:6])
                crc_error = received_crc != calculated_crc
                if crc_error:
                    logging.warning(f"CRC error: received 0x{received_crc:02X}, calculated 0x{calculated_crc:02X}")
                temperature = (temperature_raw / 5242.88) - 50
                humidity = (humidity_raw / 1048576) * 100
                return temperature, humidity, crc_error
            except Exception as e:
                logging.warning(f"Read attempt {attempt + 1}/{DHT20_MAX_RETRIES} failed: {e}")
                if attempt < DHT20_MAX_RETRIES - 1:
                    time.sleep(DHT20_RETRY_DELAY)
        logging.error("Failed to read DHT20 after all retries")
        return None, None, True


def _signal_handler(signum, frame):
    logging.info("Signal received, exiting.")
    raise SystemExit(0)


if __name__ == '__main__':
    signal.signal(signal.SIGINT, _signal_handler)
    sensor = None
    try:
        sensor = DHT20()
        temp, hum, crc = sensor.read()
        if temp is not None and hum is not None:
            print(f"Temperature: {temp:.2f} C, Humidity: {hum:.2f} %, CRC Error: {crc}")
        else:
            print("Failed to read DHT20 sensor.")
    except Exception as e:
        logging.error(f"Fatal error: {e}")
    finally:
        if sensor is not None:
            sensor.close()

