try:
    i2c_bus = busio.I2C(board.SCL, board.SDA)
except Exception as e:
    print(f"Fatal: Failed to initialize I2C bus: {e}")
    raise SystemExit(1)

# Initialize I2C multiplexer (TCA9548A)
try:
    i2c_mux = adafruit_tca9548a.TCA9548A(i2c_bus)
except Exception as e:
    print(f"Fatal: TCA9548A multiplexer not found on the I2C bus: {e}")
    raise SystemExit(1)

# Initialize BME280 sensor (default I2C address 0x76)
bme280_sensor = None
try:
    bme280_sensor = adafruit_bme280.Adafruit_BME280_I2C(i2c_mux, address=0x76)
except Exception as e:
    print(f"Warning: BME280 not found on the I2C bus: {e}")

# Initialize TSL2591 sensor (default I2C address 0x29)
tsl2591_sensor = None
try:
    tsl2591_sensor = adafruit_tsl2591.TSL2591(i2c_mux)
except Exception as e:
    print(f"Warning: TSL2591 not found on the I2C bus: {e}")

# Verify sensor presence
sensor_list = []
if bme280_sensor:
    sensor_list.append("BME280")
if tsl2591_sensor:
    sensor_list.append("TSL2591")

if not sensor_list:
    print("Warning: No sensors detected on the I2C bus.")
else:
    print(f"Available sensors: {', '.join(sensor_list)}")

# Main loop
try:
    while True:
        try:
            if bme280_sensor:
                temperature = bme280_sensor.temperature
                humidity = bme280_sensor.humidity
                print(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %")
            else:
                print("BME280: Sensor not available.")

            if tsl2591_sensor:
                light_intensity = tsl2591_sensor.lux
                print(f"Light Intensity: {light_intensity:.2f} lux")
            else:
                print("TSL2591: Sensor not available.")

        except Exception as sensor_error:
            print(f"Sensor read error: {sensor_error}")

        time.sleep(READ_INTERVAL_SECONDS)

except KeyboardInterrupt:
    print("\nProgram terminated by user.")
finally:
    # Clean resource release on all exit paths
    print("Exiting program.")

