import time
import logging
import statistics
import signal
import sys
from typing import List, Optional

try:
    import board
    import busio
    import adafruit_bmp280
except ImportError as exc:
    print(f"Missing dependency: {exc.name}. Install with: pip install adafruit-circuitpython-bmp280")
    sys.exit(1)

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s"
)

I2C_BUS = 1
I2C_SDA = board.SCL
I2C_SCL = board.SDA
SEA_LEVEL_PRESSURE = 1013.25
SAMPLE_SIZE = 100
TRIM_PERCENTAGE = 0.25

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

class CalibrationError(Exception):
    pass

class BMP280:
    def __init__(self, i2c_bus: int = I2C_BUS, sda: int = I2C_SDA, scl: int = I2C_SCL):
        self.i2c = None
        self.sensor = None
        try:
            self.i2c = busio.I2C(scl=scl, sda=sda)
            self.sensor = adafruit_bmp280.Adafruit_BMP280_I2C(self.i2c)
            self.sensor.sea_level_pressure = SEA_LEVEL_PRESSURE
            logging.info("BMP280 initialized successfully on I2C bus %d.", i2c_bus)
        except ValueError as e:
            raise CalibrationError(f"Sensor not found on I2C bus {i2c_bus}: {e}") from e
        except OSError as e:
            raise CalibrationError(f"I2C bus error during initialization: {e}") from e
        except Exception as e:
            raise CalibrationError(f"Failed to initialize BMP280: {e}") from e

    def read_pressure(self) -> float:
        try:
            return self.sensor.pressure
        except OSError as e:
            raise OSError(f"Error reading pressure from BMP280: {e}") from e
        except Exception as e:
            raise OSError(f"Unexpected error reading pressure: {e}") from e

    def get_baseline_pressure(self, sample_size: int = SAMPLE_SIZE, trim_percentage: float = TRIM_PERCENTAGE) -> float:
        logging.info("Collecting %d pressure samples to establish baseline...", sample_size)
        pressures: List[float] = []
        for i in range(sample_size):
            try:
                pressures.append(self.read_pressure())
            except OSError:
                logging.error("Skipping sample %d due to read error.", i + 1)
            time.sleep(0.1)

        if not pressures:
            raise OSError("No valid pressure samples collected.")

        pressures.sort()
        start = int(len(pressures) * (1 - trim_percentage))
        end = int(len(pressures) * (1 + trim_percentage))
        if start >= end:
            raise ValueError("Insufficient valid samples after trimming.")

        baseline = statistics.mean(pressures[start:end])
        logging.info("Baseline pressure established: %.2f hPa", baseline)
        return baseline

    def close(self):
        if self.i2c is not None:
            try:
                self.i2c.deinit()
            except Exception:
                pass
            self.i2c = None

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    bmp = None
    try:
        bmp = BMP280()
        baseline = bmp.get_baseline_pressure()
        bmp.sensor.sea_level_pressure = baseline

        while _running:
            try:
                altitude = bmp.sensor.altitude
                print(f"Altitude: {altitude:.2f} meters")
            except OSError as e:
                logging.error("Error reading altitude: %s", e)
            except Exception as e:
                logging.error("Unexpected error reading altitude: %s", e)

            time.sleep(1)

    except CalibrationError as e:
        logging.error("Calibration error: %s", e)
    except OSError as e:
        logging.error("I2C bus error: %s", e)
    except Exception as e:
        logging.error("Unexpected error: %s", e)
    finally:
        if bmp is not None:
            bmp.close()
        logging.info("Program terminated.")

if __name__ == "__main__":
    main()

