    except Exception as e:
        logging.error("Failed to initialize DHT22 sensor: %s", e)
        dht_device = None

def read_dht22():
    if dht_device is None:
        return None, None
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is None or humidity is None:
            raise RuntimeError("Sensor returned None")
        return temperature, humidity
    except RuntimeError as e:
        logging.warning("DHT22 read error: %s. Simulation active.", e)
        return None, None
    except Exception as e:
        logging.error("Unexpected DHT22 error: %s", e)
        return None, None

def validate_data(temperature, humidity):
    if temperature is None or humidity is None:
        return False
    if not (-40 <= temperature <= 80):
        logging.warning("Temperature out of range: %s", temperature)
        return False
    if not (0 <= humidity <= 100):
        logging.warning("Humidity out of range: %s", humidity)
        return False
    return True

def moving_average(data, window_size):
    if len(data) < window_size:
        return sum(data) / len(data) if data else 0
    return sum(data[-window_size:]) / window_size

def send_webhook(data):
    global webhook_failure_lock, webhook_failure_count, last_webhook_success
    if webhook_failure_lock:
        logging.info("Webhook posting paused due to rate limit.")
        return
    webhook_failure_lock = True
    try:
        payload = json.dumps(data).encode("utf-8")
        req = urllib.request.Request(
            config["webhook_url"],
            data=payload,
            headers={"Content-Type": "application/json"},
            method="POST"
        )
        with urllib.request.urlopen(req, timeout=10) as response:
            if response.getcode() == 200:
                logging.info("Webhook sent successfully: %s", data)
                webhook_failure_count = 0
                last_webhook_success = datetime.datetime.now()
            else:
                logging.error("Webhook failed with status code: %s", response.getcode())
                webhook_failure_count += 1
    except urllib.error.URLError as e:
        logging.error("Webhook URL error: %s", e)
    except urllib.error.HTTPError as e:
        logging.error("Webhook HTTP error: %s", e)
    except Exception as e:
        logging.error("Webhook error: %s", e)
    finally:
        webhook_failure_lock = False

def signal_handler(sig, frame):
    global running
    logging.info("Received signal %s. Shutting down gracefully...", sig)
    running = False

def cleanup():
    global dht_device
    if dht_device is not None:
        try:
            dht_device.exit()
            logging.info("DHT22 sensor resources released.")
        except Exception as e:
            logging.error("Error releasing DHT22 resources: %s", e)
        dht_device = None

def main():
    global running, sensor_readings, webhook_failure_count, last_webhook_success

    load_config()
    initialize_dht22()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    logging.info("Starting greenhouse monitoring system...")

    while running:
        try:
            temperature, humidity = read_dht22()

            if temperature is not None and humidity is not None:
                if validate_data(temperature, humidity):
                    timestamp = datetime.datetime.now().isoformat()
                    sensor_data = {
                        "timestamp": timestamp,
                        "temperature": temperature,
                        "humidity": humidity
                    }
                    sensor_readings.append(sensor_data)

                    if len(sensor_readings) > config["moving_average_window"]:
                        sensor_readings.pop(0)

                    avg_temp = moving_average([d["temperature"] for d in sensor_readings], config["moving_average_window"])
                    avg_hum = moving_average([d["humidity"] for d in sensor_readings], config["moving_average_window"])

                    logging.info("Temperature: %.2f C, Humidity: %.2f %%", avg_temp, avg_hum)

                    send_webhook({
                        "timestamp": timestamp,
                        "temperature": avg_temp,
                        "humidity": avg_hum
                    })
                else:
                    logging.warning("Invalid sensor data: Temperature: %.2f, Humidity: %.2f", temperature, humidity)
            else:
                logging.warning("Failed to read sensor data.")

            if config["simulation_enabled"]:
                if not validate_data(temperature, humidity):
                    logging.warning("Simulated sensor data out of range: Temperature: %.2f, Humidity: %.2f", temperature, humidity)

            if webhook_failure_count >= config["max_retries"]:
                logging.warning("Max webhook retries reached. Pausing sensor acquisition for %s seconds.", config["sensor_failure_threshold"])
                time.sleep(config["sensor_failure_threshold"])
                webhook_failure_count = 0
                last_webhook_success = datetime.datetime.now()

            time.sleep(60)

        except Exception as e:
            logging.error("An unexpected error occurred: %s", e)
            time.sleep(60)

    cleanup()
    logging.info("Greenhouse monitoring system stopped.")

if __name__ == "__main__":
    main()

