import time
import signal
import sys
import board
import adafruit_dht

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_dht22(sensor):
    """
    Reads temperature and humidity from a DHT22 sensor with retry logic.

    Args:
        sensor: An initialized adafruit_dht.DHT22 object.

    Returns:
        tuple: (temperature, humidity) as floats, or (None, None) on error.
    """
    for attempt in range(2):
        try:
            temperature = sensor.temperature
            humidity = sensor.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
            else:
                print("Error: Sensor returned None for temperature or humidity.")
        except RuntimeError as e:
            # Common DHT22 transient errors (e.g., checksum, timeout)
            print(f"RuntimeError reading DHT22 (attempt {attempt + 1}/2): {e}")
        except Exception as e:
            # Catch-all for unexpected errors (e.g., sensor disconnected)
            print(f"Unexpected error reading DHT22 (attempt {attempt + 1}/2): {e}")
        if attempt < 1:
            time.sleep(0.1)
    return None, None

def main():
    global _running

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize DHT22 sensor on BCM pin 22
    try:
        sensor = adafruit_dht.DHT22(board.D22)
    except Exception as e:
        print(f"Failed to initialize DHT22 sensor: {e}")
        sys.exit(1)

    # Allow sensor to stabilize after power-up
    time.sleep(1)

    try:
        while _running:
            temperature, humidity = read_dht22(sensor)

            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f} C")
                print(f"Humidity: {humidity:.1f} %")
            else:
                print("Failed to retrieve valid data from DHT22 sensor after retries.")

            # Sleep in small increments to allow prompt signal handling
            for _ in range(30):
                if not _running:
                    break
                time.sleep(0.1)

    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        # Clean up sensor resources
        try:
            sensor.exit()
        except Exception:
            pass
        print("\nProgram terminated.")

if __name__ == "__main__":
    main()

