import signal
import sys
import time
import logging
from datetime import datetime

try:
    import RPi.GPIO as GPIO
    _GPIO_AVAILABLE = True
except (ImportError, RuntimeError):
    GPIO = None
    _GPIO_AVAILABLE = False

DHT_PIN = 17
FAN_PIN = 18
LOG_FILE = 'urban_data_log.txt'
READ_INTERVAL = 2
NUM_READINGS = 5

logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format='%(asctime)s - %(message)s',
    datefmt='%Y-%m-%dT%H:%M:%S',
)
console = logging.StreamHandler(sys.stdout)
console.setLevel(logging.INFO)
console.setFormatter(logging.Formatter('%(asctime)s - %(message)s', datefmt='%H:%M:%S'))
logging.getLogger().addHandler(console)

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_dht11():
    """Return (temperature, humidity) or (None, None) on failure."""
    if not _GPIO_AVAILABLE:
        return None, None
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(DHT_PIN, GPIO.OUT)
        GPIO.output(DHT_PIN, GPIO.LOW)
        time.sleep(0.018)
        GPIO.output(DHT_PIN, GPIO.HIGH)
        time.sleep(0.000040)
        GPIO.setup(DHT_PIN, GPIO.IN)
        data = []
        for _ in range(40):
            while GPIO.input(DHT_PIN) == GPIO.HIGH:
                pass
            start = time.time()
            while GPIO.input(DHT_PIN) == GPIO.LOW:
                pass
            duration = time.time() - start
            if duration < 0.00005:
                data.append(1)
            else:
                data.append(0)
        if len(data) != 40:
            return None, None
        humidity = sum(data[0:8]) * 100
        temperature = sum(data[16:24]) * 100
        checksum = sum(data[24:32])
        if checksum != sum(data[32:40]):
            return None, None
        return temperature, humidity
    except Exception:
        return None, None
    finally:
        try:
            GPIO.cleanup()
        except Exception:
            pass


def control_fan(temperature, humidity):
    if temperature is None or humidity is None:
        return
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(FAN_PIN, GPIO.OUT)
        if temperature > 30 or humidity > 70:
            GPIO.output(FAN_PIN, GPIO.HIGH)
            logging.info('Fan ON: temp=%.1fC, humidity=%.1f%%', temperature, humidity)
        else:
            GPIO.output(FAN_PIN, GPIO.LOW)
            logging.info('Fan OFF: temp=%.1fC, humidity=%.1f%%', temperature, humidity)
    except Exception:
        pass


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)
    if not _GPIO_AVAILABLE:
        logging.warning('RPi.GPIO not available; running in degraded mode.')
    try:
        while _running and NUM_READINGS > 0:
            temperature, humidity = read_dht11()
            if temperature is not None and humidity is not None:
                logging.info('Temp: %.1fC, Humidity: %.1f%%', temperature, humidity)
                control_fan(temperature, humidity)
                logging.info('Data logged to %s', LOG_FILE)
            else:
                logging.error('Failed to read DHT11 sensor data.')
            NUM_READINGS -= 1
            if _running and NUM_READINGS >= 0:
                time.sleep(READ_INTERVAL)
    except Exception as e:
        logging.error('Unexpected error: %s', e)
    finally:
        try:
            GPIO.cleanup()
        except Exception:
            pass
        logging.info('GPIO cleanup completed.')


if __name__ == '__main__':
    main()

