import time
import board
import busio
import adafruit_ahtx0

# --- Configuration -----------------------------------------------------------
READ_INTERVAL_S = 5          # seconds between readings
RETRY_INTERVAL_S = 5        # seconds between sensor-detection retries
TEMP_MIN_C = -40.0
TEMP_MAX_C = 85.0
HUM_MIN_PCT = 0.0
HUM_MAX_PCT = 100.0

# --- Globals for cleanup -----------------------------------------------------
i2c = None
sensor = None
running = True


def cleanup():
    """Release hardware resources on exit."""
    global i2c, sensor
    if sensor is not None:
        try:
            sensor = None
        except Exception:
            pass
    if i2c is not None:
        try:
            i2c.deinit()
        except Exception:
            pass
        i2c = None


def init_sensor():
    """Initialize I2C bus and AHT20 sensor; return sensor object or None."""
    global i2c, sensor
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} I2C init failed: {exc}")
        i2c = None
        return None

    # Retry until the sensor is detected
    while running:
        try:
            sensor = adafruit_ahtx0.AHTx0(i2c)
            return sensor
        except Exception as exc:
            print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} Sensor init failed: {exc}")
            # Try again after the read interval
            time.sleep(RETRY_INTERVAL_S)

    return None


def read_sensor():
    """Return (temperature_c, humidity_pct) or (None, None) on error."""
    if sensor is None:
        return None, None
    try:
        temp = sensor.temperature
        hum = sensor.relative_humidity
        return temp, hum
    except Exception as exc:
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} Read error: {exc}")
        return None, None


def validate(temperature, humidity):
    """Return True if readings are within valid ranges."""
    if temperature is None or humidity is None:
        return False
    if not (TEMP_MIN_C <= temperature <= TEMP_MAX_C):
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} Temperature out of range: {temperature} C")
        return False
    if not (HUM_MIN_PCT <= humidity <= HUM_MAX_PCT):
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} Humidity out of range: {humidity} %")
        return False
    return True


def main():
    global running
    sensor = init_sensor()
    if sensor is None:
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} Sensor not detected. Exiting.")
        cleanup()
        return

    print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} AHT20 ready. Reading every {READ_INTERVAL_S} s. Ctrl-C to stop.")

    while running:
        temperature, humidity = read_sensor()

        if temperature is not None and humidity is not None:
            if validate(temperature, humidity):
                print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} Temperature: {temperature:.1f} C Humidity: {humidity:.1f} %")
            else:
                print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} Invalid reading: {temperature} C, {humidity} %")
        else:
            print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} No reading this cycle.")

        # Reinitialize on bus errors or mid-run disconnect
        if temperature is None or humidity is None:
            try:
                i2c.deinit()
            except Exception:
                pass
            try:
                i2c = busio.I2C(board.SCL, board.SDA)
            except Exception as exc:
                print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} I2C reinit failed: {exc}")
                i2c = None
            try:
                sensor = adafruit_ahtx0.AHTx0(i2c)
            except Exception as exc:
                print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} Sensor reinit failed: {exc}")
                sensor = None
            time.sleep(RETRY_INTERVAL_S)
            continue

        time.sleep(READ_INTERVAL_S)

    print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} Shutdown requested.")
    cleanup()


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} Interrupted by user.")
    finally:
        cleanup()
        raise SystemExit(0)

