import time
import signal
import sys
import logging
from gpiozero import PWMOutputDevice

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("fanctl")

FAN_PIN = 14
PWM_FREQ = 100
INTERVAL = 5
TEMP_PATH = "/sys/class/thermal/thermal_zone0/temp"

_running = True

def _handle_signal(signum, frame):
    global _running
    log.info("Received signal %s, shutting down...", signum)
    _running = False

def read_cpu_temp():
    try:
        raw = open(TEMP_PATH, "r").readline().strip()
        return float(raw) / 1000.0
    except (OSError, ValueError) as exc:
        try:
            import subprocess
            out = subprocess.check_output(["vcgencmd", "measure_temp"], text=True, timeout=5).strip()
            return float(out.split("=")[1].split("'")[0])
        except Exception as exc2:
            log.error("Failed to read CPU temperature: %s", exc2)
            return None

def temp_to_duty(temp):
    if temp >= 70:
        return 100.0
    if temp >= 60:
        return 85.0
    if temp >= 50:
        return 70.0
    if temp >= 40:
        return 50.0
    if temp >= 30:
        return 25.0
    return 0.0

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0.0)
    except Exception as exc:
        log.error("Failed to initialize PWM on GPIO%d: %s", FAN_PIN, exc)
        sys.exit(1)

    log.info("Fan control started on GPIO%d @ %d Hz", FAN_PIN, PWM_FREQ)

    try:
        while _running:
            temp = read_cpu_temp()
            if temp is None:
                log.warning("Temperature read failed; keeping current fan speed.")
            else:
                duty = temp_to_duty(temp)
                fan.value = duty / 100.0
                log.info("CPU temp: %.1f°C -> fan duty: %.1f%%", temp, duty)
            time.sleep(INTERVAL)
    except Exception as exc:
        log.exception("Unexpected error: %s", exc)
    finally:
        try:
            fan.value = 0.0
            fan.close()
        except Exception:
            pass
        log.info("GPIO resources released. Exiting.")

if __name__ == "__main__":
    main()

