import signal
import sys
import time
import logging
import threading

import paho.mqtt.client as mqtt
from gpiozero import DigitalInputDevice, DigitalOutputDevice

try:
    import adafruit_dht
    import board
except ImportError:
    logging.error("adafruit-circuitpython-dht and/or board not installed.")
    sys.exit(1)

from config import Config

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("dht22_mqtt")

config = Config()

DEGREE_CELSIUS = "\u00B0C"
READ_INTERVAL = 2.0
MAX_RETRIES = 3
RETRY_DELAY = 2.0

shutdown_event = threading.Event()


def signal_handler(signum, frame):
    log.info("Signal %s received, shutting down...", signum)
    shutdown_event.set()


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        log.info("Connected to MQTT broker.")
    else:
        log.error("MQTT connection failed with reason code: %s", reason_code)


def on_disconnect(client, userdata, flags, reason_code, properties):
    if reason_code != 0:
        log.warning("Unexpected MQTT disconnect (rc=%s).", reason_code)
    else:
        log.info("MQTT disconnected cleanly.")


def publish_value(client, topic, payload, qos=1):
    full_topic = f"homie/{config.homieclientid}/{topic}"
    info = client.publish(full_topic, payload, qos=qos)
    info.wait_for_publish(timeout=5)
    if info.rc != mqtt.MQTT_ERR_SUCCESS:
        log.error("Failed to publish to %s (rc=%s).", full_topic, info.rc)


def read_dht22(sensor):
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            temperature = sensor.temperature
            humidity = sensor.humidity
            if temperature is not None and humidity is not None:
                return round(temperature, 1), round(humidity, 1)
            log.warning("DHT22 returned None (attempt %d/%d).", attempt, MAX_RETRIES)
        except RuntimeError as e:
            log.warning("DHT22 read error (attempt %d/%d): %s", attempt, MAX_RETRIES, e)
        except Exception as e:
            log.error("Unexpected DHT22 error (attempt %d/%d): %s", attempt, MAX_RETRIES, e)
        if attempt < MAX_RETRIES:
            time.sleep(RETRY_DELAY)
    return None, None


def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    mqtt_client = None
    dht_sensor = None
    data_pin = None
    output_pin = None

    try:
        try:
            pin = getattr(board, f"D{config.dhtgpiopin}")
        except AttributeError:
            log.error("No board pin D%d found for config.dhtgpiopin=%d.", config.dhtgpiopin, config.dhtgpiopin)
            sys.exit(1)

        data_pin = DigitalInputDevice(pin, pull_up=False)
        output_pin = DigitalOutputDevice(pin, active_high=True, initial_value=True)
        time.sleep(0.5)
        sensor = adafruit_dht.DHT22(data_pin, use_pulseio=False)

        mqtt_client = mqtt.Client(
            callback_api_version=mqtt.CallbackAPIVersion.VERSION2,
            client_id=config.mqttclientid,
        )
        mqtt_client.on_connect = on_connect
        mqtt_client.on_disconnect = on_disconnect

        if config.mqttusername and config.mqttpassword:
            mqtt_client.username_pw_set(config.mqttusername, config.mqttpassword)

        mqtt_client.connect(config.mqttbroker, config.mqttport, keepalive=60)
        mqtt_client.loop_start()

        while not shutdown_event.is_set():
            temperature, humidity = read_dht22(sensor)

            if temperature is not None and humidity is not None:
                log.info("Temperature = %.1f %s, Humidity = %.1f %%", temperature, DEGREE_CELSIUS, humidity)
                publish_value(mqtt_client, config.homienodes, str(temperature))
                publish_value(mqtt_client, f"{config.homienodes}/humidity", str(humidity))
            else:
                log.error("Failed to read DHT22 after %d retries.", MAX_RETRIES)

            shutdown_event.wait(READ_INTERVAL)

    except Exception as e:
        log.exception("Fatal error: %s", e)
    finally:
        log.info("Cleaning up resources...")
        if mqtt_client is not None:
            try:
                mqtt_client.loop_stop()
                mqtt_client.disconnect()
            except Exception:
                pass
        if dht_sensor is not None:
            try:
                dht_sensor.exit()
            except Exception:
                pass
        if output_pin is not None:
            output_pin.close()
        if data_pin is not None:
            data_pin.close()
        log.info("Done.")


if __name__ == "__main__":
    main()

