#!/usr/bin/env python3
"""
Raspberry Pi UPS Plus HAT INA219 Monitor

Reads voltage, current, and power from two INA219 sensors on the UPS Plus HAT.
Supply INA219 shunt resistor: 0.00725 ohms
Battery INA219 shunt resistor: 0.005 ohms

Requires: adafruit-circuitpython-ina219, adafruit-circuitpython-busdevice
"""

import signal
import sys
import time
import logging

import board
import busio
from adafruit_ina219 import INA219, DeviceRangeError

# Constants
SUPPLY_SHUNT_RESISTOR = 0.00725
BATTERY_SHUNT_RESISTOR = 0.005
I2C_BUS = 1
SAMPLE_INTERVAL = 1.0

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)

_running = True


def _signal_handler(signum, frame):
    global _running
    logger.info("Signal %s received, shutting down...", signum)
    _running = False


class UPSPlusMonitor:
    """Monitors a UPS Plus HAT with two INA219 sensors."""

    def __init__(self, supply_shunt, battery_shunt, i2c_bus=1):
        self.supply_shunt = supply_shunt
        self.battery_shunt = battery_shunt
        self.i2c_bus_num = i2c_bus
        self.i2c = None
        self.ina_supply = None
        self.ina_battery = None
        self._initialize_i2c()
        self._initialize_sensors()

    def _initialize_i2c(self):
        try:
            self.i2c = busio.I2C(board.SCL, board.SDA)
            logger.info("I2C bus %d initialized.", self.i2c_bus_num)
        except Exception as e:
            logger.error("Failed to initialize I2C bus %d: %s", self.i2c_bus_num, e)
            raise

    def _initialize_sensors(self):
        try:
            self.ina_supply = INA219(
                self.supply_shunt, self.i2c, busnum=self.i2c_bus_num
            )
            self.ina_battery = INA219(
                self.battery_shunt, self.i2c, busnum=self.i2c_bus_num
            )
            logger.info(
                "INA219 sensors initialized (supply shunt=%.5f, battery shunt=%.5f).",
                self.supply_shunt,
                self.battery_shunt,
            )
        except Exception as e:
            logger.error("Failed to initialize INA219 sensors: %s", e)
            self.close()
            raise

    def read_supply_data(self):
        if self.ina_supply is None:
            logger.error("Supply INA219 not initialized.")
            return None, None, None
        try:
            voltage = self.ina_supply.bus_voltage
            current = self.ina_supply.current
            power = self.ina_supply.power
            return voltage, current, power
        except DeviceRangeError:
            logger.warning("Supply power out of range.")
            return None, None, None
        except Exception as e:
            logger.error("Error reading supply data: %s", e)
            return None, None, None

    def read_battery_data(self):
        if self.ina_battery is None:
            logger.error("Battery INA219 not initialized.")
            return None, None, None
        try:
            voltage = self.ina_battery.bus_voltage
            current = self.ina_battery.current
            power = self.ina_battery.power
            return voltage, current, power
        except DeviceRangeError:
            logger.warning("Battery power out of range.")
            return None, None, None
        except Exception as e:
            logger.error("Error reading battery data: %s", e)
            return None, None, None

    def display_data(self, supply_data, battery_data):
        def _d(v, c, p):
            if v is not None and c is not None and p is not None:
                return f"{v:.3f}V, {c:.3f}mA, {p:.3f}mW"
            return "N/A"

        supply_str = f"Supply: {_d(supply_data[0], supply_data[1], supply_data[2])}"
        battery_str = f"Battery: {_d(battery_data[0], battery_data[1], battery_data[2])}"
        logger.info("UPS Plus Monitor - %s | %s", supply_str, battery_str)

    def close(self):
        for dev in (self.ina_supply, self.ina_battery):
            if dev is not None:
                try:
                    dev.close()
                except Exception:
                    pass
        if self.i2c is not None:
            try:
                self.i2c.deinit()
            except Exception:
                pass
            self.i2c = None
        logger.info("I2C bus closed.")


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        monitor = UPSPlusMonitor(SUPPLY_SHUNT_RESISTOR, BATTERY_SHUNT_RESISTOR, I2C_BUS)
    except Exception:
        logger.error("Could not start UPS Plus monitor. Exiting.")
        sys.exit(1)

    try:
        while _running:
            supply_data = monitor.read_supply_data()
            battery_data = monitor.read_battery_data()
            monitor.display_data(supply_data, battery_data)
            time.sleep(SAMPLE_INTERVAL)
    except Exception as e:
        logger.error("Unexpected error in main loop: %s", e)
    finally:
        monitor.close()


if __name__ == "__main__":
    main()

