import time
import sys

LED_PIN = 17
led_state = False

def cleanup_gpio():
    """Drive the LED pin low and release it."""
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
    except Exception:
        pass
    GPIO.cleanup()

def main():
    global led_state
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while True:
            try:
                user_input = input("Enter '1' to turn LED on, '0' to turn LED off, or 'exit' to quit: ")
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_input == '1':
                led_state = True
                print("LED is now ON")
            elif user_input == '0':
                led_state = False
                print("LED is now OFF")
            elif user_input.lower() == 'exit':
                print("Exiting program.")
                break
            else:
                print("Invalid input")

            time.sleep(0.1)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"An error occurred: {e}", file=sys.stderr)
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

