import signal
import sys
import time

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO can only be run on a Raspberry Pi.", file=sys.stderr)
    sys.exit(1)

SENSOR_PINS = {1: 17, 2: 27, 3: 22}
POLL_INTERVAL = 1.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def initialize_gpio(pins):
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    for sensor_id, pin in pins.items():
        try:
            GPIO.setup(pin, GPIO.IN, pull_up=True)
        except Exception as exc:
            print(f"Error: failed to initialize GPIO{pin} for sensor {sensor_id}: {exc}", file=sys.stderr)
            raise

def read_sensor(pin):
    try:
        return GPIO.input(pin)
    except Exception as exc:
        print(f"Error: failed to read GPIO{pin}: {exc}", file=sys.stderr)
        return None

def process_sensor_responses(sensor_id, pin, response):
    print(f"Response for sensor {sensor_id}: {response}")

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        initialize_gpio(SENSOR_PINS)
    except Exception:
        print("GPIO initialization failed. Exiting.", file=sys.stderr)
        GPIO.cleanup()
        sys.exit(1)

    print(f"Monitoring sensors on pins {list(SENSOR_PINS.values())} every {POLL_INTERVAL:.1f}s. Press Ctrl+C to exit.")

    try:
        while _running:
            for sensor_id, pin in SENSOR_PINS.items():
                value = read_sensor(pin)
                if value is not None:
                    process_sensor_responses(sensor_id, pin, "HIGH" if value == GPIO.HIGH else "LOW")
            time.sleep(POLL_INTERVAL)
    except Exception as exc:
        print(f"Unexpected error in main loop: {exc}", file=sys.stderr)
    finally:
        GPIO.cleanup()
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

