import signal
import sys
import threading
import time
import traceback

import RPi.GPIO as GPIO

DO = None
_running = threading.Event()
_running.set()
_stop_event = threading.Event()


def _cleanup(signum=None, frame=None):
    """Stop the receive loop, release GPIO resources, and invoke DO.GPOK()."""
    global DO, _running
    if not _running.is_set():
        return
    _running.clear()
    _stop_event.set()
    try:
        if DO is not None:
            try:
                DO.GPOK()
            except Exception:
                pass
    except Exception:
        pass
    try:
        GPIO.cleanup()
    except Exception:
        pass
    if signum is not None:
        sys.exit(0)


def _receive_loop():
    """Background thread: poll DOG.receive() every 0.1 s and write to log file."""
    global DO
    while not _stop_event.is_set():
        try:
            data = DO.receive()
            if data is not None:
                try:
                    with open(DO.log, 'a') as f:
                        f.write(str(data) + '\n')
                except OSError as e:
                    print(f"Error writing to log file: {e}", file=sys.stderr)
        except Exception as e:
            print(f"Error in receive loop: {e}", file=sys.stderr)
        _stop_event.wait(0.1)


def _help(args):
    man = {
        "help": "Call 'help <command>' to see information about the command.\nCommands:\n\t-display\n\t-help\n\t-send\n\t-start\n\t-stop\n\t-exit\n\t-write",
        "start": "Help for 'start':\nStarts listening to data and logs it to a file.\nUsage: start <filename>",
        "stop": "Help for 'stop':\nStops listening to data.",
        "exit": "Help for 'exit':\nCloses this program.",
        "display": "Help for 'display':\nDisplays the data that has been received.",
        "send": "Help for 'send':\nSends data using DO.send().\nUsage: send <data>",
        "write": "Help for 'write':\nWrites data directly to the log file.\nUsage: write <data>",
    }
    if len(args) == 1:
        print(man.get("help"))
    elif len(args) == 2:
        print(man.get(args[1], "No help found for this command."))


def _send(data):
    global DO
    if DO is None:
        print("Error: DO not initialized. Use 'start' first.", file=sys.stderr)
        return
    try:
        DO.send(data)
    except Exception as e:
        print(f"Error sending data: {e}", file=sys.stderr)


def _display():
    global DO
    if DO is None:
        print("Error: DO not initialized. Use 'start' first.", file=sys.stderr)
        return
    try:
        with open(DO.log, 'r') as f:
            print(f.read())
    except FileNotFoundError:
        print("Log file not found.", file=sys.stderr)
    except OSError as e:
        print(f"Error reading log file: {e}", file=sys.stderr)


def _write(data):
    global DO
    if DO is None:
        print("Error: DO not initialized. Use 'start' first.", file=sys.stderr)
        return
    try:
        with open(DO.log, 'a') as f:
            f.write(str(data) + '\n')
    except OSError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)


def _start(filename):
    global DO, _running
    if _running.is_set():
        print("DO is already running.", file=sys.stderr)
        return
    try:
        DO = __import__('DOG').DOG()
        DO.log = filename
        DO.run()
        _running.set()
        _stop_event.clear()
        t = threading.Thread(target=_receive_loop, daemon=True)
        t.start()
    except ImportError:
        print("Error: The DOG library was not found. Please ensure it is installed.", file=sys.stderr)
    except Exception as e:
        print(f"Error starting DO: {e}", file=sys.stderr)
        traceback.print_exc(file=sys.stderr)
    except KeyboardInterrupt:
        print("KeyboardInterrupt: exiting before DO.start()", file=sys.stderr)
        _cleanup()


def main():
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    while True:
        try:
            cmd = input("JAYES@ROVER53:\t").strip()
        except EOFError:
            break
        if not cmd:
            continue
        args = cmd.split()
        if not args:
            continue

        if args[0] == "help":
            _help(args[1:])
        elif args[0] == "start":
            _start(args[1] if len(args) == 2 else None)
        elif args[0] == "stop":
            _cleanup()
        elif args[0] == "exit":
            _cleanup()
        elif args[0] == "display":
            _display()
        elif args[0] == "send":
            _send(' '.join(args[1:]))
        elif args[0] == "write":
            _write(' '.join(args[1:]))
        else:
            print(f"Unknown command: {args[0]}", file=sys.stderr)
            print("Commands:\n\t-display\n\t-help\n\t-send\n\t-start\n\t-stop\n\t-exit\n\t-write", file=sys.stderr)


if __name__ == "__main__":
    main()

