import time
import signal
import sys
import requests

VOLTAGE_PIN = 17
ALERT_ENDPOINT = 'http://example.com/alert'
POLL_INTERVAL = 1.0
POST_TIMEOUT = 5.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def check_power_status():
    """Read the voltage-status pin and return True if power is present."""
    try:
        return bool(GPIO.input(VOLTAGE_PIN))
    except Exception as exc:
        print(f"Error reading GPIO pin {VOLTAGE_PIN}: {exc}", file=sys.stderr)
        return False

def send_power_failure_alert():
    """POST an alert to the configured endpoint with a 5-second timeout."""
    try:
        response = requests.post(
            ALERT_ENDPOINT,
            json={'alert': 'Power failure detected'},
            timeout=POST_TIMEOUT
        )
        response.raise_for_status()
        print("Power failure alert sent successfully.")
    except requests.exceptions.Timeout:
        print("Error sending alert: request timed out after 5 seconds.", file=sys.stderr)
    except requests.exceptions.ConnectionError as exc:
        print(f"Error sending alert: connection error - {exc}", file=sys.stderr)
    except requests.exceptions.HTTPError as exc:
        print(f"Error sending alert: HTTP error - {exc}", file=sys.stderr)
    except requests.exceptions.RequestException as exc:
        print(f"Error sending alert: {exc}", file=sys.stderr)

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(VOLTAGE_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    except Exception as exc:
        print(f"Failed to initialize GPIO: {exc}", file=sys.stderr)
        sys.exit(1)

    print("Monitoring power status on GPIO 17 (BCM). Press Ctrl+C to exit.")

    try:
        while _running:
            if check_power_status():
                print("Power is present (GPIO pin HIGH).")
            else:
                print("Power failure detected (GPIO pin LOW).")
                send_power_failure_alert()
            time.sleep(POLL_INTERVAL)
    finally:
        GPIO.cleanup()
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    import RPi.GPIO as GPIO
    main()

