import signal
import sys
import time
import logging

try:
    from gpiozero import DigitalOutputDevice, DigitalInputDevice
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    print("Error: gpiozero is required. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DATA_OUT_PIN = 5
TIMER_OUT_PIN = 6
DATA_IN_PIN = 20
TIMER_IN_PIN = 21
START_SIGNAL = 0b00000001
END_SIGNAL = 0b11111111
RECEIVE_TIMEOUT = 1.0
TRANSMIT_DELAY = 0.0005

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False
    logging.info(f"Signal {signum} received, shutting down...")

def char_to_bits(char):
    if not isinstance(char, str) or len(char) != 1:
        raise ValueError("Input must be a single character.")
    ascii_value = ord(char)
    if ascii_value > 127:
        raise ValueError("Input character exceeds 7-bit ASCII range.")
    return [int(bit) for bit in bin(ascii_value)[2:].zfill(7)]

def bits_to_char(bits):
    if not isinstance(bits, list) or len(bits) != 7:
        raise ValueError("Input must be a list of 7 bits.")
    return chr(int("".join(map(str, bits)), 2))

def send_data(data):
    try:
        data_out = DigitalOutputDevice(DATA_OUT_PIN)
        timer_out = DigitalOutputDevice(TIMER_OUT_PIN)
    except GPIOZeroError as e:
        logging.error(f"Failed to initialize output pins: {e}")
        return

    try:
        for char in data:
            bits = char_to_bits(char)
            for bit in bits:
                if not _running:
                    logging.info("Transmission interrupted by signal.")
                    break
                data_out.value = bit
                timer_out.value = 1
                time.sleep(TRANSMIT_DELAY)
                timer_out.value = 0
            if not _running:
                break
            time.sleep(TRANSMIT_DELAY)
        if _running:
            end_bits = [0] * 8
            for bit in end_bits:
                if not _running:
                    break
                data_out.value = bit
                timer_out.value = 1
                time.sleep(TRANSMIT_DELAY)
                timer_out.value = 0
    except Exception as e:
        logging.error(f"Error during data transmission: {e}")
    finally:
        try:
            data_out.close()
            timer_out.close()
        except Exception:
            pass

def receive_data():
    try:
        data_in = DigitalInputDevice(DATA_IN_PIN)
        timer_in = DigitalInputDevice(TIMER_IN_PIN)
    except GPIOZeroError as e:
        logging.error(f"Failed to initialize input pins: {e}")
        return

    received_data = ""
    try:
        start_time = time.time()
        while _running:
            if timer_in.value == 1:
                start_time = time.time()
                current_bits = [0] * 8
                for i in range(8):
                    if time.time() - start_time > RECEIVE_TIMEOUT:
                        raise TimeoutError("Reception timeout exceeded.")
                    current_bits[i] = data_in.value
                    start_time = time.time()
                if current_bits == START_SIGNAL:
                    break
            else:
                if time.time() - start_time > RECEIVE_TIMEOUT:
                    raise TimeoutError("Reception timeout exceeded.")
        while _running:
            if timer_in.value == 0:
                start_time = time.time()
                current_bits = [0] * 8
                for i in range(8):
                    if time.time() - start_time > RECEIVE_TIMEOUT:
                        raise TimeoutError("Reception timeout exceeded.")
                    current_bits[i] = data_in.value
                    start_time = time.time()
                if current_bits == END_SIGNAL:
                    break
                received_data += bits_to_char(current_bits)
            else:
                if time.time() - start_time > RECEIVE_TIMEOUT:
                    raise TimeoutError("Reception timeout exceeded.")
    except TimeoutError as e:
        logging.error(f"Error during data reception: {e}")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        try:
            data_in.close()
            timer_in.close()
        except Exception:
            pass
    return received_data

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        send_data("Hello")
    except Exception as e:
        logging.error(f"Error in sender: {e}")
    if _running:
        try:
            received = receive_data()
            if received:
                logging.info(f"Received data: {received}")
            else:
                logging.info("No data received.")
        except Exception as e:
            logging.error(f"Error in receiver: {e}")

if __name__ == "__main__":
    main()

