import signal
import threading
import time
from typing import Optional

try:
    from gpiozero import OutputDevice, InputDevice
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError as exc:
    raise ImportError(
        "gpiozero is required. Install with: sudo apt install python3-gpiozero"
    ) from exc


class OutputPin:
    """Generic output pin with validation and safe shutdown."""

    def __init__(self, name: str, pin_number: int):
        if not isinstance(pin_number, int) or not (0 <= pin_number <= 53):
            raise ValueError(f"Invalid BCM pin number: {pin_number}")
        if not isinstance(name, str) or not name:
            raise ValueError("Pin name must be a non-empty string")

        self.name = name
        self.pin_number = pin_number
        self._value = 0
        self._lock = threading.Lock()
        self._device: Optional[OutputDevice] = None

        try:
            self._device = OutputDevice(pin_number, active_high=True, initial_value=False)
        except GPIOZeroError as exc:
            raise RuntimeError(
                f"Failed to initialize GPIO {pin_number} for '{name}': {exc}"
            ) from exc

    def set_value(self, value: int) -> None:
        if not isinstance(value, int) or value not in (0, 1):
            raise ValueError(f"Value must be 0 or 1, got {value}")
        with self._lock:
            if self._device is None:
                raise RuntimeError(f"{self.name} is not initialized")
            self._value = value
            self._device.value = bool(value)

    def get_value(self) -> int:
        with self._lock:
            return self._value

    def shutdown(self) -> None:
        with self._lock:
            if self._device is None:
                return
            try:
                self._device.close()
            except DeviceClosed:
                pass
            except GPIOZeroError as exc:
                print(f"Warning: error closing {self.name}: {exc}")
            finally:
                self._device = None

    def __repr__(self) -> str:
        return str(self.get_value())


class TriggerPin(OutputPin):
    """Output pin that can generate a 100-microsecond high pulse."""

    def __init__(self, name: str, pin_number: int, pulse_high: bool = True):
        super().__init__(name=name, pin_number=pin_number)
        self.pulse_high = pulse_high
        self._trigger_lock = threading.Lock()

    def trigger(self) -> None:
        with self._trigger_lock:
            if self._device is None:
                raise RuntimeError(f"{self.name} is not initialized")
            self._device.on()
            time.sleep(1e-4)
            self._device.off()

    def shutdown(self) -> None:
        with self._lock:
            if self._device is None:
                return
            try:
                self._device.close()
            except DeviceClosed:
                pass
            except GPIOZeroError as exc:
                print(f"Warning: error closing {self.name}: {exc}")
            finally:
                self._device = None


# ---------------------------------------------------------------------------
# Signal handling for clean shutdown
# ---------------------------------------------------------------------------
_pins: list[OutputPin] = []

def _signal_handler(signum, frame):
    print(f"\nReceived signal {signum}, shutting down...")
    for pin in _pins:
        try:
            pin.shutdown()
        except Exception as exc:
            print(f"Error shutting down pin {pin.name}: {exc}")
    raise SystemExit(0)


def main() -> None:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    output_pin = OutputPin(name="ExampleOutput", pin_number=21)
    _pins.append(output_pin)

    trigger_pin = TriggerPin(
        name="ExampleTrigger",
        pin_number=20,
        pulse_high=True,
    )
    _pins.append(trigger_pin)

    print("Initial output:", output_pin)
    print("Initial trigger:", trigger_pin)

    # Demonstrate a 100-microsecond pulse
    trigger_pin.trigger()
    print("Pulse generated.")

    # Set output to 1
    output_pin.set_value(1)
    print("Output set to 1:", output_pin)

    # Wait briefly before shutdown
    time.sleep(1)
    trigger_pin.shutdown()
    output_pin.shutdown()


if __name__ == "__main__":
    main()

