import signal
import sys
import time
import logging
from typing import Callable, Optional

import RPi.GPIO as GPIO

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)


class RotaryEncoder:
    """
    Quadrature rotary encoder reader for Raspberry Pi using RPi.GPIO.

    CLK (pin 17) and DT (pin 18) are wired to GPIO17 and GPIO18 respectively,
    each with an internal pull-up.  A 20 ms software debounce is applied to
    both edges on both pins.  A 4-state quadrature transition table is used
    to derive the direction of each transition and update an internal counter.
    A user callback may be supplied to receive the new counter value on each
    change; if no callback is provided the transitions are logged instead.
    """

    STATE_COUNT = 4
    DEBOUNCE_MS = 20

    def __init__(
        self,
        clk_pin: int,
        dt_pin: int,
        callback: Optional[Callable[[int], None]] = None,
    ) -> None:
        if not (0 <= clk_pin <= 27 and 0 <= dt_pin <= 27):
            raise ValueError("GPIO pin numbers must be in the range 0-27.")
        if clk_pin == dt_pin:
            raise ValueError("CLK and DT pins must be different.")

        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.callback = callback
        self._state: int = 0
        self._counter: int = 0
        self._last_event_time: float = 0.0
        self._running: bool = True

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
            GPIO.setup(self.clk_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
            GPIO.setup(self.dt_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        except Exception as exc:
            logging.error("Failed to initialize GPIO pins %d/%d: %s", clk_pin, dt_pin, exc)
            raise

        try:
            GPIO.add_event_detect(
                self.clk_pin, GPIO.BOTH, callback=self._on_clk, bouncetime=self.DEBOUNCE_MS
            )
            GPIO.add_event_detect(
                self.dt_pin, GPIO.BOTH, callback=self._on_dt, bouncetime=self.DEBOUNCE_MS
            )
        except Exception as exc:
            logging.error("Failed to add event detection: %s", exc)
            self.cleanup()
            raise

        self._install_signal_handlers()

    # ------------------------------------------------------------------
    # Signal handling
    # ------------------------------------------------------------------
    def _install_signal_handlers(self) -> None:
        for sig in (signal.SIGINT, signal.SIGTERM):
            try:
                signal.signal(sig, self._signal_handler)
            except (ValueError, OSError) as exc:
                logging.warning("Could not install handler for signal %s: %s", sig, exc)

    def _signal_handler(self, signum, frame) -> None:
        logging.info("Received signal %s, shutting down.", signum)
        self._running = False

    # ------------------------------------------------------------------
    # Quadrature state / transition table
    # ------------------------------------------------------------------
    @staticmethod
    def _state_from_levels(clk: int, dt: int) -> int:
        """Return a 0-3 integer representing the quadrature state from pin levels."""
        return (4 * clk) + dt

    def _on_clk(self, channel: int) -> None:
        """Rising-edge handler for CLK pin."""
        self._transition(channel, GPIO.RISING)

    def _on_dt(self, channel: int) -> None:
        """Falling-edge handler for DT pin."""
        self._transition(channel, GPIO.FALLING)

    def _transition(self, channel: int, edge: int) -> None:
        """Process a single quadrature transition and update the counter."""
        now = time.monotonic()
        if now - self._last_event_time < self.DEBOUNCE_MS / 1000.0:
            return
        self._last_event_time = now

        try:
            clk_level = GPIO.input(self.clk_pin)
            dt_level = GPIO.input(self.dt_pin)
        except Exception as exc:
            logging.error("GPIO read error on channel %d: %s", channel, exc)
            return

        old_state = self._state
        self._state = self._state_from_levels(clk_level, dt_level)

        if self._state == old_state:
            return

        delta = 0
        if self._state == 0b00:
            delta = -1
        elif self._state == 0b11:
            delta = 1

        self._counter += delta

        if self.callback is not None and callable(self.callback):
            try:
                self.callback(self._counter)
            except Exception as exc:
                logging.error("Callback raised an exception: %s", exc)
        else:
            logging.info("Counter changed: %d -> %d", self._counter - delta, self._counter)

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------
    def get_counter(self) -> int:
        """Return the current counter value."""
        return self._counter

    def cleanup(self) -> None:
        """Remove event detections and release GPIO resources."""
        if not hasattr(self, "_gpio_initialized"):
            return
        try:
            GPIO.remove_event_detect(self.clk_pin)
        except Exception:
            pass
        try:
            GPIO.remove_event_detect(self.dt_pin)
        except Exception:
            pass
        try:
            GPIO.cleanup((self.clk_pin, self.dt_pin))
        except Exception as exc:
            logging.error("GPIO cleanup error: %s", exc)
        self._gpio_initialized = False
        logging.info("GPIO cleanup complete.")


# ----------------------------------------------------------------------
# Example usage
# ----------------------------------------------------------------------
if __name__ == "__main__":
    encoder = None
    try:
        def on_change(value: int) -> None:
            print(f"Counter: {value}")

        encoder = RotaryEncoder(clk_pin=17, dt_pin=18, callback=on_change)
        logging.info("Rotary encoder ready. Rotate the knob (Ctrl+C to exit).")
        while encoder._running:
            time.sleep(0.1)
    except Exception as exc:
        logging.error("Fatal error: %s", exc)
    finally:
        if encoder is not None:
            encoder.cleanup()
        sys.exit(0)

