import sys

PWM_PIN = 12
FREQ_HZ = 25000

hw_pwm = None
sw_pwm = None

try:
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(PWM_PIN, GPIO.OUT, initial=GPIO.LOW)

    # Attempt hardware PWM first
    try:
        hw_pwm = GPIO.PWM(PWM_PIN, FREQ_HZ)
        hw_pwm.start(0)
    except Exception:
        hw_pwm = None

    if hw_pwm is None:
        sw_pwm = GPIO.PWM(PWM_PIN, FREQ_HZ)
        sw_pwm.start(0)

    print(f"PWM fan control started on GPIO{PWM_PIN} @ {FREQ_HZ} Hz.")
    print("Enter a speed 0-100 (or 'q' to quit).")

    while True:
        try:
            raw = input("Fan Speed (0-100): ").strip()
        except EOFError:
            break

        if raw.lower() == 'q':
            break

        try:
            speed = float(raw)
        except ValueError:
            print("Invalid input. Please enter a number between 0 and 100.")
            continue

        if not (0 <= speed <= 100):
            print("Invalid input. Please enter a number between 0 and 100.")
            continue

        if hw_pwm is not None:
            hw_pwm.ChangeDutyCycle(speed)
        elif sw_pwm is not None:
            sw_pwm.ChangeDutyCycle(speed)

        print(f"Duty cycle set to {speed:.1f}%")

except KeyboardInterrupt:
    print("\nFan control interrupted by keyboard.")
except Exception as e:
    print(f"Error: {e}", file=sys.stderr)
finally:
    if hw_pwm is not None:
        try:
            hw_pwm.stop()
        except Exception:
            pass
    if sw_pwm is not None:
        try:
            sw_pwm.stop()
        except Exception:
            pass
    GPIO.cleanup()
    print("GPIO cleaned up. Exiting.")

