import signal
import sys
import time

try:
    import smbus2 as smbus
except ImportError:
    import smbus

# BH1750FVI default I2C address (ADDR pin tied to GND)
LIGHT_SENSOR_ADDRESS = 0x23
I2C_BUS_NUMBER = 1
MEASUREMENT_DELAY_S = 1.0

_running = True


def _handle_sigint(signum, frame):
    global _running
    _running = False


def initialize_i2c_bus(bus_number):
    try:
        return smbus.SMBus(bus_number)
    except FileNotFoundError:
        print(f"Error: I2C bus {bus_number} not found. Enable I2C with 'sudo raspi-config'.")
        return None
    except PermissionError:
        print(f"Error: Permission denied on I2C bus {bus_number}. Run as root or add user to 'i2c' group.")
        return None
    except OSError as e:
        print(f"Error: Failed to initialize I2C bus {bus_number}: {e}")
        return None


def initialize_light_sensor(i2c_bus, address):
    try:
        i2c_bus.write_byte(address, 0x01)
        time.sleep(0.18)
        return True
    except OSError:
        return False


def read_light_intensity(i2c_bus, address):
    try:
        i2c_bus.write_byte(address, 0x00)
        time.sleep(0.18)
        data = i2c_bus.read_i2c_block_data(address, 0x00, 2)
        raw = (data[0] << 8) | data[1]
        return raw / 1.2
    except OSError:
        return None


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_sigint)

    i2c_bus = initialize_i2c_bus(I2C_BUS_NUMBER)
    if i2c_bus is None:
        sys.exit(1)

    if not initialize_light_sensor(i2c_bus, LIGHT_SENSOR_ADDRESS):
        print(f"Error: BH1750FVI not detected at address 0x{LIGHT_SENSOR_ADDRESS:02X} on bus {I2C_BUS_NUMBER}.")
        i2c_bus.close()
        sys.exit(1)

    print("BH1750FVI initialized. Reading luminance (Ctrl+C to stop)...")

    try:
        while _running:
            lux = read_light_intensity(i2c_bus, LIGHT_SENSOR_ADDRESS)
            if lux is not None:
                print(f"Luminance: {lux:.2f} lux")
            else:
                print("Warning: I2C read error — sensor may be disconnected or address conflict.")
            time.sleep(MEASUREMENT_DELAY_S)
    finally:
        i2c_bus.close()
        print("\nI2C bus closed. Exiting.")


if __name__ == "__main__":
    main()

