# Program: Simple LED Blink
# Hardware: Raspberry Pi 3 Model B+, LED + current-limiting resistor on GPIO17
# Wiring: LED anode -> 330 ohm resistor -> GPIO17; LED cathode -> GND

import sys
import time

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, BadPinFactory
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

LED_PIN = 17


def main():
    led = None
    try:
        led = LED(LED_PIN)
        print(f"LED initialized on GPIO{LED_PIN}.")

        while True:
            led.on()
            print("LED is ON")
            time.sleep(1)

            led.off()
            print("LED is OFF")
            time.sleep(1)

    except KeyboardInterrupt:
        print("\nProgram stopped. LED is OFF.")

    except (GPIOZeroError, BadPinFactory) as e:
        print(f"GPIO error: {e}")

    except Exception as e:
        print(f"Unexpected error: {e}")

    finally:
        if led is not None:
            try:
                led.off()
                led.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

