import time
import logging
import signal
import sys
from collections import deque

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")

OBSTACLE = 1
FREE_SPACE = 0
LED_PIN = 18
LED_RESISTOR = 330
GRID_WIDTH = 5
GRID_HEIGHT = 5
START_CELL = (0, 0)
DEFECT_CELL = (GRID_WIDTH - 1, GRID_HEIGHT - 1)

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False
    logging.info("Signal %s received, shutting down...", signum)


def plan_route(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])):
        raise ValueError(f"Start cell {start} is out of grid bounds")
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        raise ValueError(f"Goal cell {goal} is out of grid bounds")
    if any(row[-1] != FREE_SPACE for row in grid):
        raise ValueError("Grid contains obstacle cells (1)")
    if start == goal:
        return [start]
    frontier = deque([start])
    came_from = {start: None}
    while frontier:
        if not _running:
            raise RuntimeError("Planning interrupted by signal")
        current = frontier.popleft()
        if current == goal:
            break
        for neighbor in [(current[0] + 1, current[1]), (current[0] - 1, current[1]),
                         (current[0], current[1] + 1), (current[0], current[1] - 1)]:
            if (0 <= neighbor[0] < len(grid) and 0 <= neighbor[1] < len(grid[0]) and
                    grid[neighbor[0]][neighbor[1]] == FREE_SPACE and
                    neighbor not in came_from):
                came_from[neighbor] = current
                frontier.append(neighbor)
    if goal not in came_from:
        return None
    path = []
    cursor = goal
    while cursor is not None:
        path.append(cursor)
        cursor = came_from[cursor]
    path.reverse()
    return path


def indicate_success():
    logging.info("Route found: %s", plan_route([[FREE_SPACE] * GRID_WIDTH for _ in range(GRID_HEIGHT)], START_CELL, DEFECT_CELL))
    try:
        import RPi.GPIO as GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.output(LED_PIN, GPIO.HIGH)
        time.sleep(2)
        GPIO.output(LED_PIN, GPIO.LOW)
    except Exception as e:
        logging.warning("LED control failed: %s", e)


def indicate_failure():
    logging.info("No route found")
    try:
        import RPi.GPIO as GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
        for _ in range(3):
            if not _running:
                break
            GPIO.output(LED_PIN, GPIO.HIGH)
            time.sleep(0.5)
            GPIO.output(LED_PIN, GPIO.LOW)
            time.sleep(0.5)
    except Exception as e:
        logging.warning("LED control failed: %s", e)


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        import RPi.GPIO as GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        logging.warning("GPIO init failed: %s", e)
    try:
        route = plan_route([[FREE_SPACE] * GRID_WIDTH for _ in range(GRID_HEIGHT)], START_CELL, DEFECT_CELL)
        if route is not None:
            indicate_success()
        else:
            indicate_failure()
    except (ValueError, RuntimeError) as e:
        logging.error("Planning error: %s", e)
        indicate_failure()
    except Exception as e:
        logging.error("Unexpected error: %s", e)
        indicate_failure()
    finally:
        try:
            GPIO.cleanup()
        except Exception:
            pass


if __name__ == "__main__":
    main()

