#!/usr/bin/env python3
"""
Blink an LED on GPIO17 (BCM) at 1 Hz on a Raspberry Pi 3 Model B+.

Hardware:
  - LED anode  -> 330 ohm resistor -> GPIO17 (physical pin 11)
  - LED cathode -> GND (physical pin 9)

The program prefers the blink() method with background=False, falls back
to an explicit on/off loop, and always releases the LED resource cleanly.
"""

import sys
import time

