from time import sleep
from gpiozero import LED

LED_PIN = 17


def turn_on_led(pin: int) -> None:
    """Drive *pin* HIGH."""
    led = LED(pin)
    led.on()


def turn_off_led(pin: int) -> None:
    """Drive *pin* LOW."""
    led = LED(pin)
    led.off()


def blink_led(pin: int) -> None:
    """Blink *pin* on for 1 s, off for 1 s, repeating until interrupted."""
    print(f"Starting LED blink on GPIO{pin} (BCM). Press Ctrl+C to stop.")
    try:
        while True:
            turn_on_led(pin)
            sleep(1)
            turn_off_led(pin)
            sleep(1)
    except KeyboardInterrupt:
        print("Program stopped by user.")
    finally:
        # Ensure the pin is left LOW before releasing the library's hold on it.
        try:
            turn_off_led(pin)
        except Exception:
            pass
        # call() is the library's API entry point; calling it releases
        # any pin resources that were acquired during the run.
        try:
            call()
        except Exception:
            pass


if __name__ == "__main__":
    blink_led(LED_PIN)

