import time
import signal
import sys
import RPi.GPIO as GPIO

# --- Configuration -----------------------------------------------------------
RED_PIN = 17
GREEN_PIN = 27
BLUE_PIN = 22
PWM_FREQ = 200          # Hz
HOLD_SEC = 1.0
COLORS = [
    (255, 0, 0),   # red
    (0, 255, 0),   # green
    (0, 0, 255),   # blue
    (255, 255, 0), # yellow
    (0, 255, 255), # cyan
]

# --- Globals for cleanup -----------------------------------------------------
_pwm = {}
_running = True

def _cleanup():
    """Stop all PWM channels and release GPIO resources."""
    for name, pin in (('red', RED_PIN), ('green', GREEN_PIN), ('blue', BLUE_PIN)):
        ch = _pwm.get(name)
        if ch is not None:
            try:
                ch.stop()
            except Exception:
                pass
    GPIO.cleanup()

def _signal_handler(signum, frame):
    """Handle SIGTERM/SIGINT for clean shutdown."""
    global _running
    _running = False

def _set_color(r, g, b):
    """Set RGB LED color with error checking."""
    try:
        GPIO.output(RED_PIN, GPIO.HIGH if r else GPIO.LOW)
        GPIO.output(GREEN_PIN, GPIO.HIGH if g else GPIO.LOW)
        GPIO.output(BLUE_PIN, GPIO.HIGH if b else GPIO.LOW)
    except Exception as exc:
        print(f"Error setting color: {exc}", file=sys.stderr)
        raise

def _color_task(color):
    """Fade to one color, hold, then fade back to black."""
    r, g, b = color
    print(f"Setting color: R={r}, G={g}, B={b}")
    _set_color(r, g, b)
    time.sleep(HOLD_SEC)
    # Fade to black
    for r_val in range(r, -1, -1):
        for g_val in range(g, -1, -1):
            for b_val in range(b, -1, -1):
                if not _running:
                    return
                _set_color(r_val, g_val, b_val)
                time.sleep(0.01)
    _set_color(0, 0, 0)

def main():
    global _pwm

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGTERM, _signal_handler)
    signal.signal(signal.SIGINT, _signal_handler)

    # Initialize GPIO
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    for pin in (RED_PIN, GREEN_PIN, BLUE_PIN):
        GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)

    # Initialize PWM channels
    for name, pin in (('red', RED_PIN), ('green', GREEN_PIN), ('blue', BLUE_PIN)):
        try:
            ch = GPIO.PWM(pin, PWM_FREQ)
            ch.start(0)
            _pwm[name] = ch
        except Exception as exc:
            print(f"Failed to initialize PWM on pin {pin}: {exc}", file=sys.stderr)
            _cleanup()
            sys.exit(1)

    try:
        while _running:
            for color in COLORS:
                if not _running:
                    break
                _color_task(color)
    except KeyboardInterrupt:
        print("Program interrupted by user.")
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        _cleanup()
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

