import time
import signal
import sys
import requests
import RPi.GPIO as GPIO

BUTTON_PIN = 17
SERVER_URL = 'http://localhost:8000/quality'
POLL_INTERVAL = 2.0
REQUEST_TIMEOUT = 10.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def get_button_state():
    return GPIO.input(BUTTON_PIN)

def generate_report(is_button_pressed):
    part_id = 'PART-204'
    defect_count = 1 if is_button_pressed else 0
    passed = not is_button_pressed
    return {
        'part_id': part_id,
        'passed': passed,
        'defect_count': defect_count,
    }

def send_report(report):
    try:
        response = requests.post(
            SERVER_URL,
            json=report,
            headers={'Content-Type': 'application/json'},
            timeout=REQUEST_TIMEOUT,
        )
        print(f'Server response: {response.status_code}')
    except requests.exceptions.Timeout:
        print('Error: Request timed out. Check your network connection.')
    except requests.exceptions.ConnectionError:
        print('Error: Could not connect to the server. Is the server running?')
    except requests.exceptions.RequestException as e:
        print(f'Error sending data: {e}')

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    GPIO.setmode(GPIO.BCM)
    GPIO.setup(BUTTON_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

    try:
        while _running:
            try:
                current_state = get_button_state()
            except Exception as e:
                print(f'Error reading button state: {e}')
                time.sleep(POLL_INTERVAL)
                continue

            report = generate_report(current_state)
            send_report(report)

            time.sleep(POLL_INTERVAL)
    finally:
        GPIO.cleanup()
        print('GPIO cleanup completed.')

if __name__ == '__main__':
    main()

