import logging
import signal
import sys
import time

from driverlib.chassis_controller import ChassisController
from gpiozero import DigitalOutputDevice, Device
from gpiozero.pins.native import NativeFactory

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

TILT_ANGLE_SEQUENCE = [25, -25, 0, 30, -15, 40, -30, 10]
MOTOR_FORWARD_LEFT_PIN = 17
MOTOR_BACKWARD_LEFT_PIN = 18
MOTOR_FORWARD_RIGHT_PIN = 22
MOTOR_BACKWARD_RIGHT_PIN = 23
MOTOR_ENABLE_A_PIN = 12
MOTOR_ENABLE_B_PIN = 13
ENABLE_MOTOR_COMMAND = "enable_motors"
DRIVE_FORWARD_COMMAND = "drive_forward"
TURN_LEFT_COMMAND = "turn_left"
STOP_ALL_COMMAND = "stop_all"
EXECUTION_DURATION = 0.5
TILT_THRESHOLD = 20
SPEED_FACTOR = 0.1


class WearableRoverController:
    """Controls a wearable-mounted rover chassis via L298N motor driver."""

    def __init__(self, tilt_angle_sequence):
        self.tilt_angle_sequence = tilt_angle_sequence
        self.chassis = None
        self.enable_a = None
        self.enable_b = None
        self._running = True

    def _setup_gpio(self):
        try:
            self.enable_a = DigitalOutputDevice(MOTOR_ENABLE_A_PIN)
            self.enable_b = DigitalOutputDevice(MOTOR_ENABLE_B_PIN)
            self.enable_a.on()
            self.enable_b.on()
            logging.info("GPIO pins initialized for motor enable.")
        except Exception as e:
            logging.error(f"Failed to initialize GPIO pins: {e}")
            raise

    def _setup_chassis(self):
        try:
            self.chassis = ChassisController()
            logging.info("Chassis controller initialized.")
        except Exception as e:
            logging.error(f"Failed to initialize chassis controller: {e}")
            raise

    def _read_tilt_angle(self):
        try:
            return self.tilt_angle_sequence.pop(0)
        except IndexError:
            logging.warning("No more tilt angles available.")
            return None

    def _determine_command(self, tilt_angle):
        if tilt_angle > TILT_THRESHOLD:
            return DRIVE_FORWARD_COMMAND
        if tilt_angle < -TILT_THRESHOLD:
            return TURN_LEFT_COMMAND
        return STOP_ALL_COMMAND

    def _execute_command(self, command, tilt_angle):
        try:
            if command == DRIVE_FORWARD_COMMAND:
                logging.info(f"Driving forward (tilt: {tilt_angle}).")
                self.chassis.drive_forward(SPEED_FACTOR * abs(tilt_angle))
            elif command == TURN_LEFT_COMMAND:
                logging.info(f"Turning left (tilt: {tilt_angle}).")
                self.chassis.turn_left(SPEED_FACTOR * abs(tilt_angle))
            elif command == STOP_ALL_COMMAND:
                logging.info("Stopping all movement.")
                self.chassis.stop_all()
            else:
                logging.warning(f"Unknown command: {command}")
        except Exception as e:
            logging.error(f"Error executing command '{command}': {e}")
            raise

    def run(self):
        try:
            self._setup_gpio()
            self._setup_chassis()
            for tilt_angle in self.tilt_angle_sequence:
                if not self._running:
                    break
                command = self._determine_command(tilt_angle)
                self._execute_command(command, tilt_angle)
                time.sleep(EXECUTION_DURATION)
        except Exception as e:
            logging.error(f"An error occurred: {e}")
        finally:
            self.cleanup()

    def cleanup(self):
        logging.info("Cleaning up resources.")
        if self.chassis is not None:
            try:
                self.chassis.stop_all()
            except Exception:
                pass
        if self.enable_a is not None:
            try:
                self.enable_a.close()
            except Exception:
                pass
        if self.enable_b is not None:
            try:
                self.enable_b.close()
            except Exception:
                pass
        logging.info("Cleanup complete.")


def main():
    controller = WearableRoverController(TILT_ANGLE_SEQUENCE)

    def signal_handler(signum, frame):
        logging.info(f"Signal {signum} received, shutting down.")
        controller._running = False

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    controller.run()


if __name__ == "__main__":
    main()

