#!/usr/bin/env python3
"""Sort objects by color and weight using a robotic arm and color sensor."""

import time
import random
import logging
import signal
import sys
import os

try:
    from gpiozero import PWMOutputDevice
    from gpiozero.pins.native import NativeFactory
except ImportError:
    PWMOutputDevice = None
    NativeFactory = None

try:
    from smbus2 import SMBus
except ImportError:
    SMBus = None

try:
    from tcs34725 import TCS34725
except ImportError:
    TCS34725 = None

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
BASE_SERVO_PIN = 17
SHOULDER_SERVO_PIN = 27
GRIPPER_SERVO_PIN = 22

PWM_FREQUENCY = 50  # Hz

# Weight thresholds (g) for each color
RED_WEIGHT_MIN = 20.0
RED_WEIGHT_MAX = 40.0
GREEN_WEIGHT_MIN = 15.0
GREEN_WEIGHT_MAX = 35.0
BLUE_WEIGHT_MIN = 25.0
BLUE_WEIGHT_MAX = 45.0

# Predefined servo angles (degrees)
PICKUP_BASE_ANGLE = 90
PICKUP_SHOULDER_ANGLE = 45
PLACE_BASE_ANGLE = 0
PLACE_SHOULDER_ANGLE = 0

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
logging.basicConfig(
    filename='robotic_arm.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# ---------------------------------------------------------------------------
# Global state for signal handling
# ---------------------------------------------------------------------------
_running = True
_bus = None
_tcs = None
_servos = {}


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False
    logging.info(f"Received signal {signum}; initiating graceful shutdown.")


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)


# ---------------------------------------------------------------------------
# Servo helpers
# ---------------------------------------------------------------------------
def _create_servo(pin: int) -> PWMOutputDevice:
    """Create a PWMOutputDevice for a single servo pin."""
    if PWMOutputDevice is None:
        raise RuntimeError("gpiozero is not installed")
    if NativeFactory is None:
        raise RuntimeError("NativeFactory is not available")
    return PWMOutputDevice(pin, frequency=PWM_FREQUENCY, initial_value=0)


def _set_servo_angle(servo: PWMOutputDevice, angle: float) -> None:
    """Command a servo to the given angle (0-180°)."""
    if not 0 <= angle <= 180:
        raise ValueError(f"Angle {angle} out of range (0-180)")
    # gpiozero expects a value in [0.0, 1.0]
    servo.value = angle / 180.0
    time.sleep(0.02)


def _cleanup_servos() -> None:
    """Turn off all servos and close their GPIO resources."""
    for name, servo in _servos.items():
        try:
            servo.value = 0
            servo.close()
        except Exception as exc:
            logging.error(f"Error cleaning up {name}: {exc}")
    _servos.clear()


# ---------------------------------------------------------------------------
# Color sensor
# ---------------------------------------------------------------------------
def _init_color_sensor() -> TCS34725:
    """Initialize the TCS34725 color sensor on I2C bus 1."""
    if SMBus is None:
        raise RuntimeError("smbus2 is not installed")
    if TCS34725 is None:
        raise RuntimeError("tcs34725 is not installed")
    try:
        bus = SMBus(1)
    except Exception as exc:
        raise RuntimeError(f"Cannot open I2C bus 1: {exc}")
    try:
        tcs = TCS34725(bus)
        tcs.enable()
        tcs.integration_time = 0.024
        tcs.gain = 1
        return tcs
    except Exception as exc:
        bus.close()
        raise RuntimeError(f"TCS34725 initialization failed: {exc}")


def _read_color(tcs: TCS34725) -> str:
    """Read color from the TCS34725 and return 'red', 'green', 'blue', or 'unknown'."""
    try:
        r, g, b, _ = tcs.get_raw_data()
        if r > g and r > b:
            return "red"
        if g > r and g > b:
            return "green"
        if b > r and b > g:
            return "blue"
        return "unknown"
    except Exception as exc:
        logging.error(f"Color sensor read error: {exc}")
        return "unknown"


def _cleanup_color_sensor() -> None:
    """Close the I2C bus if open."""
    global _bus
    if _bus is not None:
        try:
            _bus.close()
        except Exception:
            pass
        _bus = None


# ---------------------------------------------------------------------------
# Weight simulation
# ---------------------------------------------------------------------------
def read_weight() -> float:
    """Simulate a weight reading in grams (10.0–50.0)."""
    return random.uniform(10.0, 50.0)


# ---------------------------------------------------------------------------
# Sorting logic
# ---------------------------------------------------------------------------
def sort_object(color: str, weight: float) -> None:
    """Sort an object based on its color and weight."""
    if color == "red":
        if not (RED_WEIGHT_MIN <= weight <= RED_WEIGHT_MAX):
            logging.warning(f"Weight anomaly: {weight:.2f}g (red range: {RED_WEIGHT_MIN}-{RED_WEIGHT_MAX}g)")
    elif color == "green":
        if not (GREEN_WEIGHT_MIN <= weight <= GREEN_WEIGHT_MAX):
            logging.warning(f"Weight anomaly: {weight:.2f}g (green range: {GREEN_WEIGHT_MIN}-{GREEN_WEIGHT_MAX}g)")
    elif color == "blue":
        if not (BLUE_WEIGHT_MIN <= weight <= BLUE_WEIGHT_MAX):
            logging.warning(f"Weight anomaly: {weight:.2f}g (blue range: {BLUE_WEIGHT_MIN}-{BLUE_WEIGHT_MAX}g)")


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main() -> int:
    global _bus, _tcs, _servos

    # --- Servos ----------------------------------------------------------
    try:
        _servos = {
            "base": _create_servo(BASE_SERVO_PIN),
            "shoulder": _create_servo(SHOULDER_SERVO_PIN),
            "gripper": _create_servo(GRIPPER_SERVO_PIN),
        }
    except Exception as exc:
        logging.error(f"Failed to initialize servos: {exc}")
        _cleanup_servos()
        return 1

    # --- Color sensor ----------------------------------------------------
    try:
        _tcs = _init_color_sensor()
    except Exception as exc:
        logging.error(f"Color sensor unavailable: {exc}")
        _tcs = None

    # --- Single sort cycle ------------------------------------------------
    try:
        if _tcs is not None:
            color = _read_color(_tcs)
        else:
            color = "unknown"

        weight = read_weight()
        sort_object(color, weight)
        logging.info(f"Color: {color}, Weight: {weight:.2f}g, Action: sorted")
    except Exception as exc:
        logging.error(f"Error during sort cycle: {exc}")
    finally:
        _cleanup_servos()
        _cleanup_color_sensor()

    return 0


if __name__ == "__main__":
    sys.exit(main())

