import RPi.GPIO as GPIO
from smbus2 import SMBus, i2c_msg
from vl53l0x import VL53L0X

# --- Configuration ---
PIR_PIN = 17
THRESHOLD = 50
DEBOUNCE_TIME = 3
LOG_FILE = "bird_feeder.log"
I2C_BUS = 1
VL53L0X_ADDRESS = 0x29

# --- Logging Setup ---
logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

# --- Global State for Cleanup ---
vl53 = None
bus = None
running = True


def signal_handler(sig, frame):
    """Handle Ctrl+C gracefully."""
    global running
    logging.info("Interrupt received, shutting down...")
    running = False


def initialize_vl53l0x():
    """Initialize the VL53L0X sensor with retries."""
    global vl53, bus
    for attempt in range(1, 4):
        try:
            bus = SMBus(I2C_BUS)
            vl53 = VL53L0X(i2c_dev=bus)
            vl53.open()
            vl53.start_ranging(VL53L0X.VL53L0X_RANGE_CONTINUOUS)
            logging.info("VL53L0X initialized successfully.")
            return True
        except Exception as e:
            logging.error(f"VL53L0X init attempt {attempt}/3 failed: {e}")
            if bus is not None:
                try:
                    bus.close()
                except Exception:
                    pass
                bus = None
            if attempt < 3:
                time.sleep(2)
    return False


def get_distance():
    """Read distance from VL53L0X. Returns None on error."""
    try:
        distance = vl53.get_distance()
        if distance is None:
            logging.warning("VL53L0X returned None distance.")
            return None
        return distance
    except Exception as e:
        logging.error(f"Error reading distance: {e}")
        return None


def simulate_motion_distance():
    """Simulate distance when motion is detected."""
    return 155


def main():
    global vl53, bus, running

    signal.signal(signal.SIGINT, signal_handler)

    if not initialize_vl53l0x():
        logging.error("Failed to initialize VL53L0X after 3 attempts. Exiting.")
        sys.exit(1)

    try:
        while running:
            try:
                GPIO.wait_for_edge(PIR_PIN, GPIO.RISING)
            except Exception as e:
                logging.error(f"Error waiting for PIR edge: {e}")
                time.sleep(0.1)
                continue

            if not running:
                break

            logging.info("Motion detected!")
            distance = simulate_motion_distance()
            baseline = 300  # mm, placeholder for baseline

            if distance < baseline - THRESHOLD:
                logging.info(f"Bird detected! Distance: {distance} mm")
            else:
                logging.info(f"No bird detected. Distance: {distance} mm")

            time.sleep(DEBOUNCE_TIME)

    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        if vl53 is not None:
            try:
                vl53.stop_ranging()
            except Exception as e:
                logging.error(f"Error stopping VL53L0X ranging: {e}")
        if bus is not None:
            try:
                bus.close()
            except Exception as e:
                logging.error(f"Error closing I2C bus: {e}")
        GPIO.cleanup()
        logging.info("GPIO cleaned up. Exiting.")


if __name__ == "__main__":
    main()

