import time
import signal
import sys
import atexit

try:
    from gpiozero import LED, DigitalInputDevice
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

# BCM pin assignments
LED_PIN = 17
SENSOR_PIN = 2  # BCM 2 (physical pin 3) — digital input with internal pull-up

# Global references for cleanup
led = None
sensor = None


def cleanup():
    """Release GPIO resources cleanly."""
    global led, sensor
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
        led = None
    if sensor is not None:
        try:
            sensor.close()
        except Exception:
            pass
        sensor = None


# Register cleanup on normal exit and on signals
atexit.register(cleanup)
signal.signal(signal.SIGTERM, lambda *_: sys.exit(0))


def main():
    global led, sensor

    # Initialize LED output
    try:
        led = LED(LED_PIN)
    except GPIOZeroError as e:
        print(f"Error: Failed to initialize LED on BCM pin {LED_PIN}: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error initializing LED: {e}")
        sys.exit(1)

    # Initialize digital soil-moisture sensor input with internal pull-up
    try:
        sensor = DigitalInputDevice(
            SENSOR_PIN,
            pull_up=True,
            bounce_time=None,
