import time
import signal
import sys
import RPi.GPIO as GPIO

LEFT_SENSOR_PIN = 5
RIGHT_SENSOR_PIN = 6
LEFT_MOTOR_PIN = 16
RIGHT_MOTOR_PIN = 26
NUM_ITERATIONS = 20
DELAY_SECONDS = 0.1

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    for pin in (LEFT_SENSOR_PIN, RIGHT_SENSOR_PIN, LEFT_MOTOR_PIN, RIGHT_MOTOR_PIN):
        GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)

def read_sensor(pin):
    try:
        return GPIO.input(pin)
    except Exception as exc:
        print(f"Error reading sensor on pin {pin}: {exc}", file=sys.stderr)
        return None

def control_motors(left, right):
    if left and right:
        GPIO.output(LEFT_MOTOR_PIN, GPIO.HIGH)
        GPIO.output(RIGHT_MOTOR_PIN, GPIO.HIGH)
    elif left:
        GPIO.output(LEFT_MOTOR_PIN, GPIO.HIGH)
        GPIO.output(RIGHT_MOTOR_PIN, GPIO.LOW)
    elif right:
        GPIO.output(LEFT_MOTOR_PIN, GPIO.LOW)
        GPIO.output(RIGHT_MOTOR_PIN, GPIO.HIGH)
    else:
        GPIO.output(LEFT_MOTOR_PIN, GPIO.LOW)
        GPIO.output(RIGHT_MOTOR_PIN, GPIO.LOW)

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        setup_gpio()
    except Exception as exc:
        print(f"GPIO setup failed: {exc}", file=sys.stderr)
        sys.exit(1)
    try:
        for i in range(NUM_ITERATIONS):
            if not _running:
                break
            left = read_sensor(LEFT_SENSOR_PIN)
            right = read_sensor(RIGHT_SENSOR_PIN)
            if left is None or right is None:
                control_motors(False, False)
            else:
                control_motors(left, right)
            print(f"Iteration {i + 1}: left={left}, right={right}")
            time.sleep(DELAY_SECONDS)
    except Exception as exc:
        print(f"Runtime error: {exc}", file=sys.stderr)
    finally:
        GPIO.output(LEFT_MOTOR_PIN, GPIO.LOW)
        GPIO.output(RIGHT_MOTOR_PIN, GPIO.LOW)
        GPIO.cleanup()
        print("GPIO cleaned up. Exiting.")

if __name__ == "__main__":
    main()

