import logging

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
logger = logging.getLogger(__name__)


class MotorError(Exception):
    """Custom exception for motor-related errors."""
    pass


class Motor:
    """
    Controls a DC motor via a PWM pin on a Raspberry Pi.

    The motor is driven through a DC motor driver (e.g. L298N) whose PWM input
    is connected to the specified BCM pin.  The driver library is expected to
    expose ``set_frequency(freq_hz)`` and ``set_duty_cycle(duty_cycle)`` methods
    that return a status code (e.g. 0 on success, non-zero on failure).
    """

    def __init__(self, driver, pin, frequency=1000):
        """
        Initialise the motor.

        Args:
            driver:  An object exposing ``set_frequency`` and ``set_duty_cycle``
                     methods, and a ``pi`` property that is a connected
                     ``libcamera``-compatible ``libgpiod``-backed ``library.pi``
                     instance.
            pin (int):  BCM pin number connected to the driver PWM input.
            frequency (int):  Initial PWM frequency in Hz (default 1000).

        Raises:
            MotorError:  If the driver, pin, or frequency is invalid, or if
                         the driver library returns an error while initialising
                         the PWM signal.
        """
        if driver is None:
            raise MotorError("Driver instance is None")
        if not isinstance(pin, int) or pin < 0:
            raise MotorError(f"Invalid pin number: {pin!r}")
        if not isinstance(frequency, (int, float)) or frequency <= 0:
            raise MotorError(f"Invalid frequency: {frequency!r}")

        self.driver = driver
        self.pin = pin
        self.frequency = float(frequency)
        self.duty_cycle = 0

        try:
            self.pi = driver.pi
        except AttributeError:
            raise MotorError(
                "Driver object has no 'pi' property; cannot access library.pi"
            )
        except Exception as exc:
            raise MotorError(f"Failed to retrieve 'pi' from driver: {exc}") from exc

        if self.pi is None:
            raise MotorError("Driver library.pi instance is None")

        try:
            self.pi.set_mode(self.pin, self.pi.OUTPUT)
        except Exception as exc:
            raise MotorError(
                f"Failed to set BCM pin {self.pin} as OUTPUT: {exc}"
            ) from exc

        try:
            self.pi.set_pwm_freq(self.pin, self.frequency)
        except Exception as exc:
            raise MotorError(
                f"Failed to set PWM frequency on pin {self.pin} to {self.frequency} Hz: {exc}"
            ) from exc

        try:
            self.pi.set_pwm(self.pin, 0, 0)
        except Exception as exc:
            raise MotorError(
                f"Failed to initialise PWM on pin {self.pin}: {exc}"
            ) from exc

        logger.info(
            "Motor initialised on BCM pin %d at %d Hz, duty cycle 0",
            self.pin,
            self.frequency,
        )

    def set_frequency(self, frequency):
        """
        Set the PWM frequency.

        Args:
            frequency (int|float):  Desired frequency in Hz.

        Raises:
            MotorError:  If the frequency is invalid or the driver returns an
                         error.
        """
        if not isinstance(frequency, (int, float)) or frequency <= 0:
            raise MotorError(f"Invalid frequency: {frequency!r}")

        try:
            return self.driver.set_frequency(self.pin, float(frequency))
        except Exception as exc:
            raise MotorError(
                f"Failed to set frequency on pin {self.pin}: {exc}"
            ) from exc

    def set_duty_cycle(self, duty_cycle):
        """
        Set the PWM duty cycle.

        Args:
            duty_cycle (int):  Duty cycle value in the range 0-255.

        Raises:
            MotorError:  If the duty cycle is out of range or the driver
                         returns an error.
        """
        if not isinstance(duty_cycle, int):
            raise MotorError(f"Invalid duty cycle: {duty_cycle!r}")
        if not 0 <= duty_cycle <= 255:
            raise MotorError(
                f"Duty cycle must be 0-255, got {duty_cycle}"
            )

        try:
            return self.driver.set_duty_cycle(self.pin, duty_cycle)
        except Exception as exc:
            raise MotorError(
                f"Failed to set duty cycle on pin {self.pin}: {exc}"
            ) from exc

    def stop(self):
        """Stop the motor by setting the duty cycle to 0."""
        self.duty_cycle = 0
        try:
            self.set_duty_cycle(0)
        except MotorError as exc:
            logger.warning("Could not stop motor: %s", exc)

    def close(self):
        """Stop the motor and release the PWM resource."""
        self.stop()

    def __del__(self):
        """Destructor: stop the motor and release the PWM resource."""
        try:
            self.close()
        except Exception as exc:
            logger.warning("Error during __del__: %s", exc)

