            MotorError:  If the duty cycle is out of range or the driver
                         returns an error.
        """
        if not isinstance(duty_cycle, int):
            raise MotorError(f"Invalid duty cycle: {duty_cycle!r}")
        if not 0 <= duty_cycle <= 255:
            raise MotorError(
                f"Duty cycle must be 0-255, got {duty_cycle}"
            )

        try:
            return self.driver.set_duty_cycle(self.pin, duty_cycle)
        except Exception as exc:
            raise MotorError(
                f"Failed to set duty cycle on pin {self.pin}: {exc}"
            ) from exc

    def stop(self):
        """Stop the motor by setting the duty cycle to 0."""
        self.duty_cycle = 0
        try:
            self.set_duty_cycle(0)
        except MotorError as exc:
            logger.warning("Could not stop motor: %s", exc)

    def close(self):
        """Stop the motor and release the PWM resource."""
        self.stop()

    def __del__(self):
        """Destructor: stop the motor and release the PWM resource."""
        try:
            self.close()
        except Exception as exc:
            logger.warning("Error during __del__: %s", exc)

