import serial
import time
import signal
import sys
from gpiozero import PWMOutputDevice

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERVO_PIN = 17
PWM_FREQUENCY = 50
HOLD_SECONDS = 1.0

serial_connection = None
servo_pwm = None
running = True

def cleanup():
    global serial_connection, servo_pwm
    if servo_pwm is not None:
        try:
            servo_pwm.value = 0
            servo_pwm.close()
        except Exception:
            pass
        servo_pwm = None
    if serial_connection is not None and serial_connection.is_open:
        try:
            serial_connection.close()
        except Exception:
            pass
        serial_connection = None

def signal_handler(signum, frame):
    global running
    running = False

def main():
    global serial_connection, servo_pwm
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}")
        sys.exit(1)

    try:
        servo_pwm = PWMOutputDevice(SERVO_PIN, frequency=PWM_FREQUENCY, initial_value=0)
    except Exception as e:
        print(f"Error initializing PWM on BCM pin {SERVO_PIN}: {e}")
        cleanup()
        sys.exit(1)

    try:
        while running:
            try:
                raw = serial_connection.readline()
                if not raw:
                    continue
                angle_str = raw.decode('ascii', errors='replace').strip()
                if not angle_str:
                    continue
                angle = int(angle_str)
                if not (0 <= angle <= 180):
                    print(f"Error: angle {angle} out of range (0-180)")
                    continue
                servo_pwm.value = angle / 180.0
                time.sleep(HOLD_SECONDS)
                servo_pwm.value = 0
            except ValueError:
                print(f"Error: invalid angle data received: {angle_str!r}")
            except serial.SerialException as e:
                print(f"Serial read error: {e}")
                time.sleep(0.5)
            except Exception as e:
                print(f"Unexpected error: {e}")
                time.sleep(0.5)
    finally:
        cleanup()

if __name__ == '__main__':
    main()

