                "number": 2,
                "type": "word"
            }
        },
        "servo_error_register": {
            "R/W": "R",
            "Register": "0x0FF2",
            "functioncode": 3,
            "data": {
                "number": 2,
                "type": "word"
            }
        },
    }

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------
    def read_register(self, register_address: int, register_name: str, data_type: str = "word") -> Optional[int]:
        """Read a register via FC3 (holding registers)."""
        if register_name not in self._REGISTER_MAP:
            logger.warning("Unknown register name: %s", register_name)
            return None
        if self.uart is None or not self.uart.is_open:
            logger.warning("UART not connected; cannot read %s", register_name)
            return None
        reg = self._REGISTER_MAP[register_name]
        if reg["functioncode"] != 3:
            logger.warning("Register %s is not readable (FC=%d)", register_name, reg["functioncode"])
            return None
        addr = int(reg["Register"], 16)
        count = self._word_count(data_type)
        if count == 0:
            logger.warning("Invalid data type: %s", data_type)
            return None
        frame = self._build_frame(reg["functioncode"], [addr, count])
        try:
            resp = self._send_frame(frame)
            if resp is None:
                logger.warning("No response for read %s at 0x%04X", register_name, addr)
                return None
            func_code, payload = self._parse_frame(resp)
            if func_code != 3:
                logger.warning("Unexpected function code %d in response", func_code)
                return None
            if len(payload) < count * 2:
                logger.warning("Short read: got %d bytes, expected %d", len(payload), count * 2)
                return None
            return int.from_bytes(payload[:2], byteorder="big")
        except ModbusRTUError as e:
            logger.warning("Read error for %s: %s", register_name, e)
            return None
        except Exception as e:
            logger.warning("Unexpected error reading %s: %s", register_name, e)
            return None

    def write_register(self, register_address: int, register_name: str, value: int, data_type: str = "word") -> bool:
        """Write a value to a register via FC6 (single holding) or FC16 (multiple holding)."""
        if register_name not in self._REGISTER_MAP:
            logger.warning("Unknown register name: %s", register_name)
            return False
        if self.uart is None or not self.uart.is_open:
            logger.warning("UART not connected; cannot write %s", register_name)
            return False
        reg = self._REGISTER_MAP[register_name]
        if reg["R/W"] != "W":
            logger.warning("Register %s is not writable", register_name)
            return False
        addr = int(reg["Register"], 16)
        count = self._dword_count(data_type) if reg["functioncode"] == 16 else self._word_count(data_type)
        if count == 0:
            logger.warning("Invalid data type: %s", data_type)
            return False
        frame = self._build_frame(reg["functioncode"], [addr, count, value & 0xFFFF])
        try:
            self._send_frame(frame)
            return True
        except ModbusRTUError as e:
            logger.warning("Write error for %s: %s", register_name, e)
            return False
        except Exception as e:
            logger.warning("Unexpected error writing %s: %s", register_name, e)
            return False

    # ------------------------------------------------------------------
    # Low-level send / receive
    # ------------------------------------------------------------------
    def _send_frame(self, frame: bytes) -> Optional[bytes]:
        """Send a frame and return the response, or None on error."""
        if self.uart is None or not self.uart.is_open:
            logger.warning("UART not open; cannot send frame")
            return None
        try:
            self.uart.reset_input_buffer()
            self.uart.write(frame)
            time.sleep(0.01)
            response = self.uart.read(256)
            if not response:
                raise ModbusRTUError("No response from device")
            return response
        except serial.SerialException as e:
            logger.warning("Serial error sending frame: %s", e)
            return None
        except Exception as e:
            logger.warning("Unexpected send error: %s", e)
            return None

    def _recv_frame(self, timeout: float = 1.0) -> Optional[bytes]:
        """Receive a Modbus RTU frame with timeout, or None if no frame arrives."""
        if self.uart is None or not self.uart.is_open:
            logger.warning("UART not open; cannot receive frame")
            return None
        deadline = time.monotonic() + timeout
        frame = bytearray()
        while time.monotonic() < deadline:
            chunk = self.uart.read(1)
            if chunk:
                frame.extend(chunk)
                if len(frame) >= 3 and (frame[0] & 0x03) == 0x03:
                    return bytes(frame)
            else:
                time.sleep(0.005)
        logger.warning("Timeout waiting for Modbus frame")
        return None

    # ------------------------------------------------------------------
    # Helpers
    # ------------------------------------------------------------------
    @staticmethod
    def _word_count(data_type: str) -> int:
        if data_type == "word":
            return 2
        if data_type == "dword":
            return 4
        return 0

    @staticmethod
    def _dword_count(data_type: str) -> int:
        if data_type == "dword":
            return 4
        return 0

    def _send_and_receive(self, frame: bytes) -> Optional[bytes]:
        """Send a frame and wait for a response, or None on error."""
        if self.uart is None or not self.uart.is_open:
            logger.warning("UART not open; cannot send/receive")
            return None
        try:
            self.uart.reset_input_buffer()
            self.uart.write(frame)
            time.sleep(0.01)
            response = self.uart.read(256)
            if not response:
                raise ModbusRTUError("No response from device")
            return response
        except serial.SerialException as e:
            logger.warning("Serial error: %s", e)
            return None
        except Exception as e:
            logger.warning("Unexpected error: %s", e)
            return None


# ----------------------------------------------------------------------
# Example usage
# ----------------------------------------------------------------------
if __name__ == "__main__":
    rtu = ModbusRTU(port="/dev/serial0", baudrate=115200, timeout=1.0)
    rtu._install_signal_handlers()
    try:
        if not rtu.connect():
            logger.warning("Could not connect to Modbus RTU device. Exiting.")
            sys.exit(1)
        pos = rtu.read_register(0, "servo_position")
        if pos is not None:
            logger.info("Current servo position: %d", pos)
        else:
            logger.warning("Failed to read servo position")
    except Exception as e:
        logger.error("Fatal error: %s", e)
    finally:
        rtu.close()
        rtu._restore_signal_handlers()

