                self.vserv = None
        else:
            print("Warning: servo library not available; servos disabled.")
            self.hserv = None
            self.vserv = None

    def aim(self, b):
        """Aim at the specified target indices (1-based)."""
        if self.hserv is None or self.vserv is None:
            print("Warning: servos not initialized; skipping aiming sequence.")
            return
        try:
            for i in b:
