import signal
import sys
import json
from http.server import BaseHTTPRequestHandler, HTTPServer
import RPi.GPIO as GPIO

RELAY_PIN = 23
SERVER_PORT = 5000

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def setup_gpio():
    """Initialize GPIO and set relay pin as output, default LOW."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(RELAY_PIN, GPIO.OUT, initial=GPIO.LOW)

def cleanup_gpio():
    """Cleanly release GPIO resources."""
    try:
        GPIO.output(RELAY_PIN, GPIO.LOW)
    except Exception:
        pass
    GPIO.cleanup()

class RelayHandler(BaseHTTPRequestHandler):
    def do_POST(self):
        if self.path != '/relay':
            self.send_error(404, 'Not Found')
            return

        content_length = int(self.headers.get('Content-Length', 0))
        if content_length == 0:
            self.send_error(400, 'Empty request body')
            return

        try:
            post_data = self.rfile.read(content_length).decode('utf-8')
        except Exception as e:
            self.send_error(400, f'Invalid request body: {e}')
            return

        try:
            payload = json.loads(post_data)
        except json.JSONDecodeError:
            self.send_error(400, 'Invalid JSON payload')
            return

        if 'state' not in payload:
            self.send_error(400, 'Missing "state" key in payload')
            return

        state = payload['state']
        if state not in ('on', 'off'):
            self.send_error(400, 'Invalid state. Must be "on" or "off".')
            return

        try:
            if state == 'on':
                GPIO.output(RELAY_PIN, GPIO.HIGH)
            else:
                GPIO.output(RELAY_PIN, GPIO.LOW)
        except Exception as e:
            self.send_error(500, f'GPIO output error: {e}')
            return

        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps({'status': 'Relay state changed'}).encode('utf-8'))

    def log_message(self, format, *args):
        # Suppress default stderr logging; we manage our own output
        pass

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        setup_gpio()
    except Exception as e:
        print(f'GPIO initialization failed: {e}', file=sys.stderr)
        sys.exit(1)

    try:
        server = HTTPServer(('0.0.0.0', SERVER_PORT), RelayHandler)
        print(f'Server listening on 0.0.0.0:{SERVER_PORT}/relay')
        while _running:
            server.handle_request()
    except Exception as e:
        print(f'Server error: {e}', file=sys.stderr)
    finally:
        cleanup_gpio()
        print('GPIO cleaned up. Exiting.')

if __name__ == '__main__':
    main()

