import signal
import sys
import RPi.GPIO as GPIO

RELAY_PIN = 17
SUNRISE_TIME = 7
SUNSET_TIME = 19
CHECK_INTERVAL = 60
RELAY_DELAY = 1

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(RELAY_PIN, GPIO.OUT, initial=GPIO.HIGH)

def cleanup_gpio():
    try:
        GPIO.output(RELAY_PIN, GPIO.HIGH)
    except Exception:
        pass
    GPIO.cleanup()

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        setup_gpio()
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            now = time.localtime()
            current_time = time.strftime("%H:%M", now)

            if current_time == SUNRISE_TIME:
                GPIO.output(RELAY_PIN, GPIO.LOW)
                print(f"{time.strftime('%Y-%m-%d %H:%M:%S', now)} - Opening door (relay LOW)")
                time.sleep(RELAY_DELAY)
            elif current_time == SUNSET_TIME:
                GPIO.output(RELAY_PIN, GPIO.HIGH)
                print(f"{time.strftime('%Y-%m-%d %H:%M:%S', now)} - Closing door (relay HIGH)")
                time.sleep(RELAY_DELAY)

            for _ in range(CHECK_INTERVAL):
                if not _running:
                    break
                time.sleep(1)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

