import signal
import sys
import logging
from typing import Optional

from gpiozero import OutputDevice
from gpiozero.pins.lgpio import LGPIOFactory

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("greenhouse")

PUMP_PIN = 20
LIGHT_PIN = 21
PHRASES = [
    ("turn the pump on", "pump_on"),
    ("switch the light", "light_toggle"),
    ("turn pump off", "pump_off"),
    ("unknown command", "unknown"),
]

_running = True


def _handle_signal(signum, frame):
    global _running
    log.info("Received signal %s, shutting down...", signum)
    _running = False


def parse_intent(raw: str) -> str:
    """Return the intent name (lowercase, underscore-separated) for a phrase."""
    raw = raw.lower()
    for phrase, intent in PHRASES:
        if phrase in raw:
