import signal
import sys
import time
import logging
from typing import Optional

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    print("Error: gpiozero is required. Install with: pip install gpiozero", file=sys.stderr)
    sys.exit(1)

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s"
)

SOLENOID_PIN = 24
ACTIVATION_DURATION = 0.4
DELAY_BETWEEN_PULSES = 1.0


class SolenoidController:
    """Controls a solenoid via a relay module on a Raspberry Pi GPIO pin."""

    def __init__(self, pin: int):
        self.pin = pin
        self.relay: Optional[OutputDevice] = None
        self._initialize_gpio()

    def _initialize_gpio(self) -> None:
        """Initialize the GPIO pin as a digital output and energize the relay."""
        try:
            self.relay = OutputDevice(self.pin, active_high=True, initial_value=False)
            logging.info("GPIO pin %d initialized as output (relay de-energized).", self.pin)
        except GPIOZeroError as e:
            logging.error("Failed to initialize GPIO pin %d: %s", self.pin, e)
            raise

    def activate(self, duration: float) -> None:
        """Energize the solenoid for the specified duration, then de-energize it."""
        if self.relay is None:
            raise RuntimeError("Relay not initialized.")
        try:
            self.relay.on()
            logging.info("Solenoid activated on pin %d for %.2f seconds.", self.pin, duration)
            time.sleep(duration)
        except DeviceClosed:
            logging.error("Device closed during activation; cannot energize relay.")
            raise
        finally:
            self.deactivate()

    def deactivate(self) -> None:
        """De-energize the solenoid."""
        if self.relay is not None:
            try:
                self.relay.off()
                logging.info("Solenoid deactivated on pin %d.", self.pin)
            except DeviceClosed:
                logging.warning("Device closed; cannot de-energize relay.")

    def cleanup(self) -> None:
        """Release GPIO resources and de-energize the relay."""
        if self.relay is not None:
            try:
                self.relay.close()
                logging.info("GPIO pin %d cleaned up.", self.pin)
            except Exception as e:
                logging.error("Error during GPIO cleanup: %s", e)
            finally:
                self.relay = None


def run_solenoid_sequence(controller: SolenoidController, num_pulses: int) -> None:
    """Run a sequence of solenoid activation pulses."""
    for i in range(num_pulses):
        logging.info("Starting pulse %d/%d", i + 1, num_pulses)
        controller.activate(ACTIVATION_DURATION)
        if i < num_pulses - 1:
            time.sleep(DELAY_BETWEEN_PULSES)


def signal_handler(signum, frame, controller: SolenoidController) -> None:
    """Handle SIGINT/SIGTERM by de-energizing the solenoid and exiting."""
    logging.info("Received signal %d, shutting down.", signum)
    controller.deactivate()
    controller.cleanup()
    sys.exit(0)


def main() -> None:
    """Main entry point: initialize controller, run sequence, and clean up."""
    controller: Optional[SolenoidController] = None
    try:
        controller = SolenoidController(SOLENOID_PIN)
        signal.signal(signal.SIGINT, lambda s, f: signal_handler(s, f, controller))
        signal.signal(signal.SIGTERM, lambda s, f: signal_handler(s, f, controller))
        run_solenoid_sequence(controller, 3)
    except Exception as e:
        logging.error("An error occurred: %s", e)
    finally:
        if controller is not None:
            controller.deactivate()
            controller.cleanup()


if __name__ == "__main__":
    main()

