import RPi.GPIO as GPIO
import time
import sys

# GPIO pins connected to the ULN2003 driver inputs (BCM numbering)
COIL_PINS = [18, 19, 20, 21]
STEPS_PER_REV = 4096  # 64 steps * 64 microsteps (half-stepping)

def setup_gpio():
    """Configure GPIO pins as outputs and ensure they start LOW."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    for pin in COIL_PINS:
        GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)

def angle_to_steps(angle_degrees):
    """Convert an angle in degrees (0-360) to half-step increments."""
    if not 0 <= angle_degrees <= 360:
        raise ValueError(f"Angle must be 0-360 degrees, got {angle_degrees}")
    return int(round((angle_degrees / 360.0) * STEPS_PER_REV))

def step_motor(steps):
    """Rotate the stepper motor by the given number of half-steps."""
    for halfstep in range(steps):
        for coil_index in range(4):
            # Half-step sequence: 1, 2, 3, 4, 1, 2, 3, 4, ...
            phase = (halfstep + coil_index) % 4
            if phase == 0:
                pattern = [1, 0, 0, 0]
            elif phase == 1:
                pattern = [0, 1, 0, 0]
            elif phase == 2:
                pattern = [0, 0, 1, 0]
            else:
                pattern = [0, 0, 0, 1]
            GPIO.output(COIL_PINS, pattern)
            time.sleep(0.001)  # 1 ms per half-step

def cleanup():
    """Release GPIO resources."""
    GPIO.cleanup()

def main():
    try:
        setup_gpio()
        target_bearing = 90  # Example bearing in degrees
        steps = angle_to_steps(target_bearing)
        print(f"Rotating to bearing {target_bearing} degrees ({steps} half-steps)")
        step_motor(steps)
        print("Position reached. Holding for 2 seconds...")
        time.sleep(2)
        print("Holding complete.")
    except ValueError as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)
    except KeyboardInterrupt:
        print("\nRotation interrupted by user.", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

