import time
import signal
import sys
import smbus2

# CCS811 I2C address and bus
CCS811_I2C_ADDRESS = 0x5B
I2C_BUS_NUMBER = 1

# Global flag for graceful shutdown
_running = True

def signal_handler(sig, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False

def initialize_i2c_bus(bus_number):
    """Initializes the I2C bus with error handling."""
    try:
        return smbus2.SMBus(bus_number)
    except FileNotFoundError:
        print(f"Error: I2C bus {bus_number} not found. Enable I2C via raspi-config.")
        return None
    except PermissionError:
        print(f"Error: Permission denied on I2C bus {bus_number}. Run as root or add user to i2c group.")
        return None
    except OSError as e:
        print(f"Error initializing I2C bus {bus_number}: {e}")
        return None

def verify_sensor_presence(i2c_bus, address):
    """Verifies sensor presence by scanning the I2C bus."""
    try:
        i2c_bus.read_byte(address)
        return True
    except OSError:
        return False

def initialize_sensor(i2c_bus, address):
    """Initializes the CCS811 sensor."""
    try:
        # Check if sensor is already initialized (AL_GAS register)
        i2c_bus.read_byte_data(address, 0x81)
        return True
    except OSError:
        return False

def read_co2_level(i2c_bus, address):
    """Reads the CO2 concentration from the sensor."""
    try:
        # Read 6 bytes starting from register 0x81 (AL_GAS)
        data = i2c_bus.read_i2c_block_data(address, 0x81, 6)
        # CO2 value is in the 3rd and 4th bytes (little-endian)
        co2 = (data[1] << 8) | data[0]
        return co2
    except OSError as e:
        print(f"I2C communication error reading CO2: {e}")
        return None

def main():
    """Main function to read CO2 levels from the CCS811 sensor."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    i2c_bus = initialize_i2c_bus(I2C_BUS_NUMBER)
    if i2c_bus is None:
        sys.exit(1)

    if not verify_sensor_presence(i2c_bus, CCS811_I2C_ADDRESS):
        print("Error: CCS811 sensor not found at address 0x5B on I2C bus 1.")
        i2c_bus.close()
        sys.exit(1)

    if not initialize_sensor(i2c_bus, CCS811_I2C_ADDRESS):
        print("Error: Failed to initialize CCS811 sensor. Check wiring and power.")
        i2c_bus.close()
        sys.exit(1)

    try:
        while _running:
            co2_level = read_co2_level(i2c_bus, CCS811_I2C_ADDRESS)
            if co2_level is not None:
                print(f"CO2 Concentration: {co2_level} ppm")
            else:
                print("Failed to read CO2 level.")
            time.sleep(2)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        i2c_bus.close()
        print("I2C bus closed. Exiting.")

if __name__ == "__main__":
    main()

