import serial
import time
import signal
import sys
import RPi.GPIO as GPIO

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 1.0
ALERT_PIN = 18
RADIATION_THRESHOLD = 50.0
READ_INTERVAL = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_serial(port, baud, timeout):
    try:
        ser = serial.Serial(port, baud, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}")
        return None

def read_radiation_level(serial_port):
    try:
        raw = serial_port.readline()
        if not raw:
            return None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        return float(line)
    except ValueError:
        print(f"Error: Could not convert data to float: {line!r}")
        return None
    except serial.SerialException as e:
        print(f"Serial read error: {e}")
        return None

def control_alert_system(radiation_level, alert_pin):
    if radiation_level > RADIATION_THRESHOLD:
        GPIO.output(alert_pin, GPIO.HIGH)
    else:
        GPIO.output(alert_pin, GPIO.LOW)

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setup(ALERT_PIN, GPIO.OUT, initial=GPIO.LOW)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, READ_TIMEOUT)
    if serial_connection is None:
        GPIO.cleanup()
        sys.exit(1)

    try:
        while _running:
            radiation = read_radiation_level(serial_connection)
            if radiation is not None:
                print(f"Radiation Level: {radiation:.2f} µSv/h")
                control_alert_system(radiation, ALERT_PIN)
            time.sleep(READ_INTERVAL)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
        GPIO.cleanup()
        print("Program terminated.")

if __name__ == "__main__":
    main()

