BAUD_RATE = 9600
READ_TIMEOUT = 1.0
ALARM_PIN = 18
RADIATION_THRESHOLD = 50.0
READ_INTERVAL = 1.0

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s [%(levelname)s] %(message)s',
)
log = logging.getLogger('radiation_monitor')

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def initialize_serial(port, baud, timeout):
    try:
        ser = serial.Serial(
            port=port,
            baudrate=baud,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=timeout,
        )
        log.info('Serial port %s opened at %d baud.', port, baud)
        return ser
    except serial.SerialException as exc:
        log.error('Failed to open serial port %s: %s', port, exc)
        return None
    except OSError as exc:
        log.error('OS error opening serial port %s: %s', port, exc)
        return None


def initialize_gpio(pin):
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
    log.info('GPIO%d initialized as alarm output (LOW).', pin)


def read_radiation_level(ser):
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        log.error('Serial read error: %s', exc)
        return None
    except OSError as exc:
        log.error('OS read error: %s', exc)
        return None

    if not raw:
        return None

    try:
        text = raw.decode('ascii', errors='replace').strip()
    except Exception as exc:
        log.warning('Decode error: %s', exc)
        return None

    if not text:
        return None

    try:
        return float(text)
    except ValueError:
        log.warning('Non-numeric data received: %r', text)
        return None


def control_alarm(pin, level, threshold):
    if level > threshold:
        GPIO.output(pin, GPIO.HIGH)
        state = 'TRIGGERED'
    else:
        GPIO.output(pin, GPIO.LOW)
        state = 'Cleared'
    log.info('Alarm %s (radiation %.2f µSv/h > %.1f µSv/h).', state, level, threshold)
    return state


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = initialize_serial(SERIAL_PORT, BAUD_RATE, READ_TIMEOUT)
    if ser is None:
        sys.exit(1)

    try:
        initialize_gpio(ALARM_PIN)
    except Exception as exc:
        log.error('GPIO initialization failed: %s', exc)
        ser.close()
        sys.exit(1)

    alarm_state = 'Cleared'
    try:
        while _running:
            level = read_radiation_level(ser)
            if level is not None:
                alarm_state = control_alarm(ALARM_PIN, level, RADIATION_THRESHOLD)
            time.sleep(READ_INTERVAL)
    except Exception as exc:
        log.exception('Unexpected error in main loop: %s', exc)
    finally:
        try:
            ser.close()
            log.info('Serial port closed.')
        except Exception:
            pass
        GPIO.cleanup()
        log.info('GPIO cleaned up. Exiting.')


if __name__ == '__main__':
    main()

