import serial
import serial.tools.list_ports
import signal
import sys
import time
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
SAMPLE_INTERVAL = 5
LOG_FILE = 'co2_readings_log.txt'

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def initialize_serial(port, baudrate, timeout):
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        ser.reset_input_buffer()
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None

def read_co2_level(ser):
    try:
        raw = ser.readline()
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}", file=sys.stderr)
        return None
    if not raw:
        return None
    line = raw.decode('ascii', errors='replace').strip()
    if not line:
        return None
    try:
        return int(line)
    except ValueError:
        print(f"Invalid data received (not an integer): {line!r}", file=sys.stderr)
        return None

def log_co2_reading(co2_value, log_file):
    timestamp = datetime.now().isoformat(timespec='seconds')
    log_entry = f"{timestamp} - CO2: {co2_value} ppm\n"
    try:
        with open(log_file, 'a', encoding='utf-8') as f:
            f.write(log_entry)
            f.flush()
    except OSError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if ser is None:
        sys.exit(1)

    try:
        while _running:
            co2_level = read_co2_level(ser)
            if co2_level is not None:
                print(f"CO2: {co2_level} ppm")
                log_co2_reading(co2_level, LOG_FILE)
            time.sleep(SAMPLE_INTERVAL)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        if ser and ser.is_open:
            ser.close()
            print("Serial port closed.", file=sys.stderr)
        print("Program terminated.", file=sys.stderr)

if __name__ == "__main__":
    main()

