import serial
import time
import signal
import sys

SERIAL_PORT = "/dev/serial0"
BAUD_RATE = 9600
TIMEOUT = 1

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def configure_serial(port, baudrate, timeout):
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None

def parse_gprmc(data):
    if not data.startswith("$GPRMC"):
        return None, None
    parts = data.split(",")
    if len(parts) < 7 or parts[2] != "A":
        return None, None
    lat_raw = parts[3]
    lat_dir = parts[4]
    lon_raw = parts[5]
    lon_dir = parts[6]
    if not lat_raw or not lon_raw:
        return None, None
    try:
        lat_deg = int(lat_raw[0:2])
        lat_min = lat_raw[2:]
        lat = lat_deg + (float(lat_min) / 60.0)
        if lat_dir == "S":
            lat = -lat
        lon_deg = int(lon_raw[0:3])
        lon_min = lon_raw[3:]
        lon = lon_deg + (float(lon_min) / 60.0)
        if lon_dir == "W":
            lon = -lon
        return lat, lon
    except (ValueError, IndexError):
        return None, None

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    ser = configure_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if ser is None:
        sys.exit(1)
    try:
        while _running:
            try:
                raw = ser.readline()
                if not raw:
                    continue
                line = raw.decode("utf-8", errors="ignore").strip()
                if not line:
                    continue
                lat, lon = parse_gprmc(line)
                if lat is not None and lon is not None:
                    print(f"Latitude: {lat:.6f}, Longitude: {lon:.6f}")
                time.sleep(1)
            except serial.SerialException as e:
                print(f"Serial read error: {e}", file=sys.stderr)
                time.sleep(1)
            except Exception as e:
                print(f"Unexpected error: {e}", file=sys.stderr)
                time.sleep(1)
    finally:
        if ser and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

