import serial
import pynmea2
import time
import signal
import sys

# Configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'gps_coordinates_log.txt'

# Global flag for graceful shutdown
_running = True

def signal_handler(sig, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial port with error handling."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error opening serial port: {e}")
        return None

def read_gps_data(serial_port):
    """Reads a line from the serial port and parses it as NMEA."""
    try:
        line = serial_port.readline().decode('latin-1').strip()
        if not line:
            return None
        return pynmea2.parse(line)
    except pynmea2.ParseError as e:
        print(f"NMEA parse error: {e}")
        return None
    except UnicodeDecodeError as e:
        print(f"Unicode decode error: {e}")
        return None
    except serial.SerialException as e:
        print(f"Serial read error: {e}")
        return None
    except Exception as e:
        print(f"Unexpected read error: {e}")
        return None

def extract_coordinates(gps_data):
    """Extracts latitude, longitude, and altitude from parsed GPS data."""
    if gps_data is None:
        return None, None, None
    try:
        latitude = gps_data.latitude
        longitude = gps_data.longitude
        if hasattr(gps_data, 'altitude'):
            altitude = gps_data.altitude
        else:
            altitude = None
        return latitude, longitude, altitude
    except AttributeError as e:
        print(f"Attribute error extracting coordinates: {e}")
        return None, None, None
    except Exception as e:
        print(f"Unexpected error extracting coordinates: {e}")
        return None, None, None

def log_coordinates(log_file, latitude, longitude, altitude):
    """Logs the coordinates to a file with error handling."""
    timestamp = time.strftime('%Y-%m-%dT%H:%M:%S')
    log_entry = f"{timestamp}, Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude}\n"
    try:
        with open(log_file, 'a') as file:
            file.write(log_entry)
    except IOError as e:
        print(f"Error writing to log file {log_file}: {e}")
    except Exception as e:
        print(f"Unexpected error writing to log file: {e}")

def display_coordinates(latitude, longitude, altitude):
    """Displays the coordinates to the console."""
    print(f"Current Coordinates - Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude}")

def main():
    """Main function to read GPS data, log coordinates, and display them."""
    global _running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.")
        sys.exit(1)

    try:
        while _running:
            gps_data = read_gps_data(serial_connection)
            if gps_data is not None:
                latitude, longitude, altitude = extract_coordinates(gps_data)
                if latitude is not None and longitude is not None:
                    if hasattr(gps_data, 'gps_qual') and gps_data.gps_qual == 1:
                        log_coordinates(LOG_FILE, latitude, longitude, altitude)
                        display_coordinates(latitude, longitude, altitude)
            time.sleep(0.1)  # Small delay to prevent excessive CPU usage
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

