import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'health_readings_log.txt'

running = True
serial_connection = None


def signal_handler(signum, frame):
    global running
    running = False


def process_data(data_string):
    try:
        parts = data_string.split(',')
        if len(parts) != 2:
            raise ValueError(f"Expected 2 fields, got {len(parts)}")
        heart_rate, spo2 = parts[0].strip(), parts[1].strip()
        if not heart_rate or not spo2:
            raise ValueError("Empty field in data string")
        return f"Heart Rate: {heart_rate}, SpO2: {spo2}"
    except ValueError as e:
        return f"Error parsing data: {e}"


def log_data(timestamp, data):
    try:
        with open(LOG_FILE, 'a') as logfile:
            logfile.write(f"{timestamp} - {data}\n")
    except IOError as e:
        print(f"Error writing to log file: {e}")


def main():
    global serial_connection

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f"Connected to {SERIAL_PORT} at {BAUD_RATE} baud.")
    except serial.SerialException as e:
        print(f"Failed to open serial port: {e}")
        sys.exit(1)

    try:
        while running:
            try:
                raw_data = serial_connection.readline()
                if not raw_data:
                    continue
                data_string = raw_data.decode('ascii', errors='replace').strip()
                if not data_string:
                    continue
                timestamp = time.strftime('%Y-%m-%dT%H:%M:%S')
                print(f"[{timestamp}] {process_data(data_string)}")
                log_data(timestamp, process_data(data_string))
            except ValueError as e:
                print(f"[{time.strftime('%Y-%m-%dT%H:%M:%S')}] {e}")
                log_data(time.strftime('%Y-%m-%dT%H:%M:%S'), str(e))
            except serial.SerialException as e:
                print(f"[{time.strftime('%Y-%m-%dT%H:%M:%S')}] Serial communication error: {e}")
                log_data(time.strftime('%Y-%m-%dT%H:%M:%S'), str(e))
            time.sleep(0.1)
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")


if __name__ == "__main__":
    main()

