import json
import signal
import sys
import threading
from http.server import BaseHTTPRequestHandler, HTTPServer
from typing import Any, Dict, List

import serial

PORT = "/dev/ttyUSB0"
BAUDRATE = 9600
TIMEOUT = 1
HOST = "0.0.0.0"
PORT_NUMBER = 5000

data: List[Dict[str, Any]] = [
    {"id": 1, "name": "Item 1", "done": False},
    {"id": 2, "name": "Item 2", "done": True},
]
data_lock = threading.Lock()
uart_lock = threading.Lock()
uart: Any = None


def init_uart() -> Any:
    global uart
    with uart_lock:
        if uart is not None and uart.is_open:
            try:
                uart.close()
            except Exception:
                pass
        uart = serial.Serial(
            port=PORT,
            baudrate=BAUDRATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
        )
    return uart


def close_uart() -> None:
    global uart
    with uart_lock:
        if uart is not None and uart.is_open:
            try:
                uart.close()
            except Exception:
                pass
        uart = None


def get_data() -> List[Dict[str, Any]]:
    with data_lock:
        return list(data)


def get_data_item(item_id: int) -> Dict[str, Any]:
    with data_lock:
        for item in data:
            if item["id"] == item_id:
                return item
    return None


def create_data_item(name: str, done: bool) -> Dict[str, Any]:
    new_id = (data[-1]["id"] + 1) if data else 1
    new_item = {"id": new_id, "name": name, "done": done}
    with data_lock:
        data.append(new_item)
    return new_item


def send_command(cmd: str) -> str:
    if not init_uart():
        raise RuntimeError("Failed to open UART port")
    try:
        uart.write(cmd.encode("ascii"))
        uart.flush()
        raw = uart.readline()
        if not raw:
            raise TimeoutError("No response within timeout")
        return raw.decode("ascii", errors="replace").strip()
    except Exception as e:
        raise RuntimeError(f"UART communication error: {e}")
    finally:
        close_uart()


class WebRequestHandler(BaseHTTPRequestHandler):
    def do_GET(self) -> None:
        if self.path == "/version":
            self._handle_version()
        elif self.path == "/data":
            self._handle_get_data()
        elif self.path.startswith("/data/"):
