import serial
import time
import signal
import sys

SERIAL_PORT = "/dev/serial0"
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = "power_consumption.log"

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def log_power_consumption(power_value):
    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
    log_entry = f"{timestamp} – Power: {power_value} W"
    try:
        with open(LOG_FILE, "a") as logfile:
            logfile.write(log_entry + "\n")
    except OSError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT) as ser:
            print(f"Opened {SERIAL_PORT} @ {BAUD_RATE} baud (timeout {TIMEOUT}s).")
            while _running:
                try:
                    raw = ser.readline()
                except serial.SerialException as e:
                    print(f"Serial read error: {e}", file=sys.stderr)
                    break

                if not raw:
                    continue

                line = raw.decode("ascii", errors="replace").strip()
                if not line:
                    continue

                try:
                    power = float(line)
                except ValueError:
                    print(f"Invalid data received (not numeric): {line!r}", file=sys.stderr)
                    continue

                log_power_consumption(power)

    except serial.SerialException as e:
        print(f"Error opening serial port: {e}", file=sys.stderr)
        sys.exit(1)
    except OSError as e:
        print(f"OS error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

