import http.server
import socketserver
import json
import serial
import time
import signal
import sys

PORT = 8000
HOST = '0.0.0.0'
SERIAL_PORT = '/dev/ttyUSB0'
BAUDRATE = 9600
TIMEOUT = 1
READ_DELAY = 0.1

data = [
    {"id": 1, "name": "Chips", "done": False},
    {"id": 2, "name": "Candy", "done": True},
]

running = True

def signal_handler(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def get_serial_connection():
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUDRATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
        )
        return ser
    except serial.SerialException as e:
        print(f"Serial connection error: {e}")
        return None

def send_scpi_command(ser, command):
    if ser is None:
        return None
    try:
        ser.write(command.encode('ascii'))
        ser.flush()
        time.sleep(READ_DELAY)
        return ser.read(ser.in_waiting or 1)
    except serial.SerialException as e:
        print(f"Serial communication error: {e}")
        return None

def handle_scpi_query(ser, command):
    response = send_scpi_command(ser, command)
    if response is None:
        return None
    try:
        return response.decode('ascii', errors='replace').replace('\n', '<br>')
    except Exception as e:
        print(f"Error decoding response: {e}")
        return None

class WebhookHandler(http.server.BaseHTTPRequestHandler):
    def _send_json(self, status, payload):
        body = json.dumps(payload).encode('utf-8')
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        if self.path == '/version':
            ser = get_serial_connection()
            try:
                response = handle_scpi_query(ser, "*IDN?\n")
                if response is not None:
                    self._send_json(200, {'status': 'ok', 'version': response})
                else:
                    self._send_json(503, {'status': 'error', 'message': 'No response from SCPI device'})
            finally:
                if ser is not None:
                    ser.close()
        elif self.path == '/getdata':
            self._send_json(200, data)
        elif self.path.startswith('/getset/'):
            try:
                item_id = int(self.path.split('/')[-1])
            except ValueError:
                self._send_json(400, {'status': 'error', 'message': 'Invalid item ID'})
                return
            item = next((it for it in data if it['id'] == item_id), None)
            if item is not None:
                self._send_json(200, item)
            else:
                self._send_json(404, {'status': 'error', 'message': 'Item not found'})
        elif self.path.startswith('/getpost/'):
            try:
                item_id, name = self.path.split('/')[-2], self.path.split('/')[-1]
                item_id = int(item_id)
            except ValueError:
                self._send_json(400, {'status': 'error', 'message': 'Invalid item ID or name'})
                return
            item = next((it for it in data if it['id'] == item_id), None)
            if item is not None:
                item['name'] = name
                item['done'] = False
                self._send_json(200, data)
            else:
                self._send_json(404, {'status': 'error', 'message': 'Item not found'})
        else:
            self._send_json(404, {'status': 'error', 'message': 'Not found'})

    def do_POST(self):
        if self.path == '/postjson':
            content_type = self.headers.get('Content-Type', '')
            if content_type in ('application/json', 'application/x-www-form-urlencoded'):
                try:
                    length = int(self.headers.get('Content-Length', 0))
                    body = self.rfile.read(length)
                    if not body:
                        self._send_json(400, {'status': 'error', 'message': 'Empty request body'})
                        return
                    data_copy = data.copy()
                    new_id = data_copy[-1]['id'] + 1 if data_copy else 1
                    new_item = {
                        'id': new_id,
                        'name': json.loads(body).get('name', ''),
                        'done': json.loads(body).get('done', False),
                    }
                    data_copy.append(new_item)
                    data[:] = data_copy
                    self._send_json(201, data)
                except (json.JSONDecodeError, ValueError) as e:
                    self._send_json(400, {'status': 'error', 'message': f'Malformed JSON: {e}'})
            else:
                self._send_json(400, {'status': 'error', 'message': 'Invalid Content-Type'})
        else:
            self._send_json(404, {'status': 'error', 'message': 'Not found'})

    def log_message(self, format, *args):
        pass

def main():
    httpd = socketserver.TCPServer((HOST, PORT), WebhookHandler)
    print(f'Server running on {HOST}:{PORT}...')
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        httpd.server_close()

if __name__ == '__main__':
    main()

